            local MarketplaceService, TweenService, Camera, UserInputService, GuiService, Root = cloneValue(game:GetService'MarketplaceService'), cloneValue(game:GetService'TweenService'), cloneValue(game:GetService'Workspace').CurrentCamera, cloneValue(game:GetService'UserInputService'), cloneValue(game:GetService'GuiService'), script
            local Components, Creator, Elements, Acrylic, Icons, Themes, Layout, Signal = Root.Components, require(Root.Modules.Creator), require(Root.Elements), require(Root.Modules.Acrylic), require(Root.Modules.Icons), require(Root.Themes), require(Root.Modules.Layout), require(Root.Packages.Signal)
            local Notification, GlobalEnv, New = require(Components.Notification), shared or _G or (getgenv and getgenv()) or getfenv(1), Creator.New
            local screenGui = New('ScreenGui', {Name = 'Fluent Renewed Base GUI'})
