            }

            function Library:SafeCallback(callback, ...)
                assert(typeof(callback) == 'function', debug.traceback(`Library:SafeCallback expects type 'function' at Argument #1, got '{typeof(callback)}'`, 2))
                task.spawn(function(...)
                    local ok, errMsg = pcall(callback, ...)
                    if not ok then
                        local startIdx, endIdx = errMsg:find':%d+: '
                        task.defer(error, debug.traceback(errMsg, 2))
                        Library:Notify {
                            Title = Creator.Translate('InterfaceTitle'),
                            Content = Creator.Translate('CallbackError'),
                            SubContent = (typeof(endIdx) == 'number' and {(errMsg:sub(endIdx + 1))} or {errMsg})[1],
                            Duration = 5
                        }
                    end
                end, ...)
            end

            function Library.Utilities:Resize(width, height)
                local widthRatio, heightRatio, viewportSize = width / 1920, height / 1080, Camera.ViewportSize
                return viewportSize.X * widthRatio, viewportSize.Y * heightRatio
            end

            function Library.Utilities:Truncate(num, digits, doRound)
                local multiplier = 10 ^ (typeof(digits) == 'number' and math.max(digits, 0) or 0)
                if doRound then
                    return math.round(num * multiplier) // 1 / multiplier
                else
                    return num * multiplier // 1 / multiplier
                end
            end

            function Library.Utilities:Round(num, digits)
                return Library.Utilities:Truncate(num, digits, true)
            end

            function Library.Utilities:GetIcon(iconName)
                return iconName ~= 'SetIcon' and Icons[iconName] or nil
            end

            function Library.Utilities:Prettify(value)
                if typeof(value) == 'EnumItem' then
                    return ({value.Name:gsub('(%l)(%u)', '%1 %2')})[1]
                elseif typeof(value) == 'string' then
                    return ({value:gsub('(%l)(%u)', '%1 %2')})[1]
                elseif typeof(value) == 'number' then
                    return Library.Utilities:Round(value, 2)
                else
                    return tostring(value)
                end
            end

            function Library.Utilities:Clone(value)
                return cloneValue(value)
            end

            function Library.Utilities:IsMobile()
                return Layout.CheckIsMobile()
            end

            function Library.Utilities:GetOS()
                local keyName = 'Unknown'
                if GuiService:IsTenFootInterface() then
                    local gamepadStr = UserInputService:GetStringForKeyCode(Enum.KeyCode.ButtonL2)
                    keyName = gamepadStr == 'ButtonLT' and 'Xbox' or (gamepadStr == 'ButtonL2' and 'PlayStation' or 'Console')
                elseif GuiService.IsWindows then
                    keyName = 'Windows'
                elseif version():find'^0.' == 1 then
                    keyName = 'macOS'
                elseif version():find'^2.' == 1 then
                    keyName = UserInputService.VREnabled and 'MetaHorizon' or 'Mobile'
                end
                return keyName
            end
            local ElementsMeta = {}
