                ElementsMeta[`Add{elementDef.__type}`] = ElementsMeta[`Create{elementDef.__type}`]
                ElementsMeta[elementDef.__type] = ElementsMeta[`Create{elementDef.__type}`]
                if elementDef.__type == 'Banner' then
                    ElementsMeta.CreateImageCard = ElementsMeta.CreateBanner
                    ElementsMeta.AddImageCard = ElementsMeta.CreateBanner
                    ElementsMeta.ImageCard = ElementsMeta.CreateBanner
                end
            end
            Library.Elements = ElementsMeta

            function Library:PlayIntro(opts, onComplete)
                opts = typeof(opts) == 'table' and opts or {}
                local Players = game:GetService'Players'
                local RunService = game:GetService'RunService'
                local ContentProvider = game:GetService'ContentProvider'
                local SoundService = game:GetService'SoundService'
                local player = Players.LocalPlayer
                local parentGui = Library.UIContainer or screenGui.Parent
                if not parentGui then
                    if typeof(onComplete) == 'function' then
                        onComplete()
                    end
                    return
                end

                for _, oldName in next, {'RezHub_IntroGui', 'MeisterUI_Environment'} do
                    local old = parentGui:FindFirstChild(oldName)
                    if old then
                        old:Destroy()
                    end
                end

                local isMob = Layout.IsMobile
                local brandTitle = typeof(opts.Title) == 'string' and opts.Title ~= '' and opts.Title or 'REZ HUB'
                local soundId = typeof(opts.SoundId) == 'string' and opts.SoundId ~= '' and opts.SoundId or 'rbxassetid://80874929641794'
                local userId = player and player.UserId or 1
                local userName = player and player.Name or 'Player'
                local avatarUrl = string.format('rbxthumb://type=AvatarHeadShot&id=%d&w=150&h=150', userId)

                local introGui = New('ScreenGui', {
                    Name = 'RezHub_IntroGui',
                    IgnoreGuiInset = true,
                    ResetOnSpawn = false,
                    ZIndexBehavior = Enum.ZIndexBehavior.Sibling,
                    DisplayOrder = 999,
                    Parent = parentGui
                })

                local function tw(obj, duration, style, dir, props)
                    local tween = TweenService:Create(obj, TweenInfo.new(duration, style or Enum.EasingStyle.Quart, dir or Enum.EasingDirection.Out), props)
                    tween:Play()
                    return tween
                end

                -- Classic full-screen black intro overlay
                local overlay = New('Frame', {
                    Name = 'IntroOverlay',
                    Size = UDim2.fromScale(1, 1),
                    Position = UDim2.fromScale(0, 0),
                    BackgroundColor3 = Color3.fromRGB(0, 0, 0),
                    BackgroundTransparency = 1,
                    BorderSizePixel = 0,
                    ZIndex = 999,
                    Parent = introGui
                })

                local baseW, baseH = isMob and 300 or 460, isMob and 68 or 96
                local breatheW, breatheH = isMob and 335 or 510, isMob and 76 or 106
                local exitW, exitH = isMob and 440 or 650, isMob and 100 or 136

                local titleShadow = New('TextLabel', {
                    Name = 'Shadow',
                    AnchorPoint = Vector2.new(0.5, 0.5),
                    Position = UDim2.new(0.5, 3, 0.44, -7),
                    Size = UDim2.fromOffset(baseW, baseH),
                    BackgroundTransparency = 1,
                    Font = Enum.Font.GothamBlack,
                    Text = brandTitle,
                    TextScaled = true,
                    TextColor3 = Color3.fromRGB(0, 0, 0),
                    TextTransparency = 1,
                    ZIndex = 1000,
                    Parent = overlay
                })
                local introTitle = New('TextLabel', {
                    Name = 'IntroTitle',
                    AnchorPoint = Vector2.new(0.5, 0.5),
                    Position = UDim2.new(0.5, 0, 0.44, -10),
                    Size = UDim2.fromOffset(baseW, baseH),
                    BackgroundTransparency = 1,
                    Font = Enum.Font.GothamBlack,
                    Text = brandTitle,
                    TextScaled = true,
                    TextColor3 = Color3.fromRGB(255, 255, 255),
                    TextTransparency = 1,
                    ZIndex = 1001,
                    Parent = overlay
                })

                -- Minimalist status row: rounded-square avatar + bold name + white progress bar + larger status text
                local stripW, stripH = isMob and 290 or 390, isMob and 64 or 72
                local statusStrip = New('Frame', {
                    Name = 'StatusStrip',
                    AnchorPoint = Vector2.new(0.5, 0.5),
                    Position = UDim2.new(0.5, 0, 0.58, 12),
                    Size = UDim2.fromOffset(stripW, stripH),
                    BackgroundTransparency = 1,
                    BorderSizePixel = 0,
                    ZIndex = 1001,
                    Parent = overlay
                })

                local avSize = isMob and 46 or 54
                local avFrame = New('Frame', {
                    AnchorPoint = Vector2.new(0, 0.5),
                    Position = UDim2.new(0, 0, 0.5, 0),
                    Size = UDim2.fromOffset(avSize, avSize),
                    BackgroundColor3 = Color3.fromRGB(30, 32, 38),
                    BackgroundTransparency = 1,
                    BorderSizePixel = 0,
                    ZIndex = 1002,
                    Parent = statusStrip
                }, {New('UICorner', {CornerRadius = UDim.new(0, 12)})})
                local avatarImg = New('ImageLabel', {
                    Size = UDim2.fromScale(1, 1),
                    BackgroundTransparency = 1,
                    Image = avatarUrl,
                    ImageTransparency = 1,
                    ScaleType = Enum.ScaleType.Crop,
                    ZIndex = 1003,
                    Parent = avFrame
                }, {New('UICorner', {CornerRadius = UDim.new(0, 12)})})

                local infoX = avSize + (isMob and 12 or 14)
                local nameLabel = New('TextLabel', {
                    Position = UDim2.fromOffset(infoX, isMob and 2 or 4),
                    Size = UDim2.new(1, -infoX, 0, isMob and 20 or 22),
                    BackgroundTransparency = 1,
                    Font = Enum.Font.GothamBlack,
                    Text = string.upper(userName),
                    TextColor3 = Color3.fromRGB(255, 255, 255),
                    TextTransparency = 1,
                    TextSize = isMob and 15 or 17,
                    TextXAlignment = Enum.TextXAlignment.Left,
                    TextTruncate = Enum.TextTruncate.AtEnd,
                    ZIndex = 1002,
                    Parent = statusStrip
                })
                local track = New('Frame', {
                    Position = UDim2.fromOffset(infoX, isMob and 27 or 31),
                    Size = UDim2.new(1, -infoX, 0, isMob and 9 or 11),
                    BackgroundColor3 = Color3.fromRGB(42, 44, 50),
                    BackgroundTransparency = 1,
                    BorderSizePixel = 0,
                    ClipsDescendants = true,
                    ZIndex = 1002,
                    Parent = statusStrip
                }, {New('UICorner', {CornerRadius = UDim.new(0, 3)})})
                local fill = New('Frame', {
                    Size = UDim2.fromScale(0, 1),
                    BackgroundColor3 = Color3.fromRGB(255, 255, 255),
                    BackgroundTransparency = 1,
                    BorderSizePixel = 0,
                    ZIndex = 1003,
                    Parent = track
                }, {New('UICorner', {CornerRadius = UDim.new(0, 3)})})
                local statusLabel = New('TextLabel', {
                    Position = UDim2.fromOffset(infoX, isMob and 41 or 47),
                    Size = UDim2.new(1, -infoX, 0, isMob and 20 or 22),
                    BackgroundTransparency = 1,
                    Font = Enum.Font.GothamMedium,
                    Text = 'Loading...',
                    TextColor3 = Color3.fromRGB(215, 220, 228),
                    TextTransparency = 1,
                    TextSize = isMob and 14 or 16,
                    TextXAlignment = Enum.TextXAlignment.Left,
                    TextTruncate = Enum.TextTruncate.AtEnd,
                    ZIndex = 1002,
                    Parent = statusStrip
                })

                local function setStatus(msg)
                    if statusLabel and statusLabel.Parent and typeof(msg) == 'string' then
                        statusLabel.Text = msg
                    end
                end
                local function setProgress(val)
                    local p = math.clamp(tonumber(val) or 0, 0, 1)
                    if fill and fill.Parent then
                        tw(fill, 0.30, Enum.EasingStyle.Quint, Enum.EasingDirection.Out, {Size = UDim2.fromScale(p, 1)})
                    end
                end

                local function waitUntil(pred, timeout, step)
                    local t0 = os.clock()
                    step = step or 0.08
                    while os.clock() - t0 < (timeout or 8) do
                        local ok, res = pcall(pred)
                        if ok and res then
                            return true
                        end
                        task.wait(step)
                    end
                    return false
                end

                local function checkFps(minFps, stableSec, maxWait, onSample)
                    local t0, stableStart, ema, lastEmit = os.clock(), nil, 60, os.clock()
                    local hbConn = RunService.Heartbeat:Connect(function(dt)
                        if dt > 0 then
                            ema += ((1 / dt) - ema) * 0.18
                        end
                    end)
                    local passed = false
                    while os.clock() - t0 < maxWait do
                        local fps = math.floor(ema + 0.5)
                        if onSample and os.clock() - lastEmit >= 0.15 then
                            lastEmit = os.clock()
                            onSample(fps)
                        end
                        if ema >= minFps then
                            stableStart = stableStart or os.clock()
                            if os.clock() - stableStart >= stableSec then
                                passed = true
                                break
                            end
                        else
                            stableStart = nil
                        end
                        task.wait(0.08)
                    end
                    if hbConn then
                        hbConn:Disconnect()
                    end
                    return passed, math.floor(ema + 0.5)
                end

                task.spawn(function()
                    -- 1. Smooth black fade-in
                    tw(overlay, 0.65, Enum.EasingStyle.Quart, Enum.EasingDirection.Out, {BackgroundTransparency = 0})
                    task.wait(0.55)

                    -- 2. Smooth title fade-in + sound + status row fade-in
                    local titleAppearAt = os.clock()
                    local sfx = New('Sound', {
                        SoundId = soundId,
                        Volume = 0.75,
                        Parent = SoundService
                    })
                    pcall(function()
                        sfx:Play()
                    end)
                    sfx.Ended:Connect(function()
                        if sfx and sfx.Parent then
                            sfx:Destroy()
                        end
                    end)
                    task.delay(6, function()
                        if sfx and sfx.Parent then
                            sfx:Destroy()
                        end
                    end)

                    tw(introTitle, 1.1, Enum.EasingStyle.Sine, Enum.EasingDirection.Out, {TextTransparency = 0})
                    tw(titleShadow, 1.1, Enum.EasingStyle.Sine, Enum.EasingDirection.Out, {TextTransparency = 0.4})
                    tw(introTitle, 1.5, Enum.EasingStyle.Sine, Enum.EasingDirection.InOut, {Size = UDim2.fromOffset(breatheW, breatheH)})
                    tw(titleShadow, 1.5, Enum.EasingStyle.Sine, Enum.EasingDirection.InOut, {Size = UDim2.fromOffset(breatheW, breatheH)})

                    tw(statusStrip, 0.75, Enum.EasingStyle.Quint, Enum.EasingDirection.Out, {
                        Position = UDim2.new(0.5, 0, 0.58, 0)
                    })
                    tw(avFrame, 0.7, Enum.EasingStyle.Quint, Enum.EasingDirection.Out, {BackgroundTransparency = 0.15})
                    tw(nameLabel, 0.7, Enum.EasingStyle.Quint, Enum.EasingDirection.Out, {TextTransparency = 0})
                    tw(track, 0.7, Enum.EasingStyle.Quint, Enum.EasingDirection.Out, {BackgroundTransparency = 0.25})
                    tw(fill, 0.7, Enum.EasingStyle.Quint, Enum.EasingDirection.Out, {BackgroundTransparency = 0})
                    tw(statusLabel, 0.7, Enum.EasingStyle.Quint, Enum.EasingDirection.Out, {TextTransparency = 0})

                    -- 3. Verify all conditions before allowing the lib to open
                    if Creator.Locale.Mode == 'Auto' and Creator.Locale.DetectedLang == nil then
                        Creator.DetectCountryLocaleAsync()
                    end
                    if opts.SkipChecks ~= true then
                        setProgress(0.12)
                        setStatus('Loading...')
                        waitUntil(function()
                            return game:IsLoaded()
                        end, 20, 0.08)

                        setProgress(0.26)
                        if Creator.Locale.Mode == 'Auto' and Creator.Locale.DetectedLang == nil then
                            waitUntil(function()
                                return Creator.Locale.DetectedLang ~= nil
                            end, 2.5, 0.05)
                        end

                        setProgress(0.38)
                        pcall(ContentProvider.PreloadAsync, ContentProvider, {avatarImg})
                        tw(avatarImg, 0.45, Enum.EasingStyle.Sine, Enum.EasingDirection.Out, {ImageTransparency = 0})

                        setProgress(0.50)
                        local lastFps = 0
                        local fpsOk = checkFps(10, 0.65, 10, function(fps)
                            if fps ~= lastFps then
                                lastFps = fps
                                setStatus(fps < 10 and string.format('Waiting FPS (%d)...', fps) or 'Loading...')
                            end
                        end)
                        if not fpsOk then
                            setStatus('Loading...')
                            task.wait(0.2)
                        end

                        setProgress(0.75)
                        setStatus('Loading character...')
                        local function charReady()
                            local ch = player and player.Character
                            if not (ch and ch.Parent) then
                                return false
                            end
                            local hum = ch:FindFirstChildOfClass('Humanoid')
                            local hrp = ch:FindFirstChild('HumanoidRootPart')
                            return hum ~= nil and hrp ~= nil and hum.Health > 0
                        end
                        waitUntil(charReady, 8, 0.1)

                        setProgress(0.90)
                        setStatus('Finalizing...')
                        waitUntil(function()
                            return workspace.CurrentCamera ~= nil and game:GetService('ReplicatedStorage') ~= nil and Players.LocalPlayer ~= nil
                        end, 6, 0.08)
                    else
                        pcall(ContentProvider.PreloadAsync, ContentProvider, {avatarImg})
                        tw(avatarImg, 0.4, Enum.EasingStyle.Sine, Enum.EasingDirection.Out, {ImageTransparency = 0})
                    end

                    setProgress(1)
                    setStatus('Ready!')

                    -- Ensure intro title has enough breathing time to feel smooth
                    local minDisplay = 1.65
                    local elapsedTitle = os.clock() - titleAppearAt
                    if elapsedTitle < minDisplay then
                        task.wait(minDisplay - elapsedTitle)
                    else
                        task.wait(0.35)
                    end

                    -- 4. Smooth fade-out of title & status row, then overlay -> reveal lib
                    tw(introTitle, 0.85, Enum.EasingStyle.Quart, Enum.EasingDirection.InOut, {
                        TextTransparency = 1,
                        Size = UDim2.fromOffset(exitW, exitH)
                    })
                    tw(titleShadow, 0.85, Enum.EasingStyle.Quart, Enum.EasingDirection.InOut, {
                        TextTransparency = 1,
                        Size = UDim2.fromOffset(exitW, exitH)
                    })
                    tw(statusStrip, 0.55, Enum.EasingStyle.Quart, Enum.EasingDirection.Out, {
                        Position = UDim2.new(0.5, 0, 0.58, 12)
                    })
                    tw(avFrame, 0.50, Enum.EasingStyle.Quart, Enum.EasingDirection.Out, {BackgroundTransparency = 1})
                    tw(avatarImg, 0.50, Enum.EasingStyle.Quart, Enum.EasingDirection.Out, {ImageTransparency = 1})
                    tw(nameLabel, 0.50, Enum.EasingStyle.Quart, Enum.EasingDirection.Out, {TextTransparency = 1})
                    tw(track, 0.50, Enum.EasingStyle.Quart, Enum.EasingDirection.Out, {BackgroundTransparency = 1})
                    tw(fill, 0.50, Enum.EasingStyle.Quart, Enum.EasingDirection.Out, {BackgroundTransparency = 1})
                    tw(statusLabel, 0.50, Enum.EasingStyle.Quart, Enum.EasingDirection.Out, {TextTransparency = 1})

                    task.wait(0.45)
                    local fadeOut = tw(overlay, 0.95, Enum.EasingStyle.Quart, Enum.EasingDirection.Out, {BackgroundTransparency = 1})
                    fadeOut.Completed:Wait()

                    if introGui and introGui.Parent then
                        introGui:Destroy()
                    end
                    if typeof(onComplete) == 'function' then
                        pcall(onComplete)
                    end
                end)
            end

            function Library:Window(config)
                assert(Library.CreatedWindow == nil, debug.traceback('You cannot create more than one window.', 2))
                if not config.Title then
                    local ok, productInfo = pcall(MarketplaceService.GetProductInfo, MarketplaceService, game.PlaceId)
                    config.Title = ok and productInfo.Name or 'Fluent Renewed'
                end
                config.MinSize = (typeof(config.MinSize) == 'Vector2' and {(config.MinSize)} or {(Vector2.new(Layout.IsMobile and 320 or 470, Layout.IsMobile and 240 or 380))})[1]
                local resolvedSize, resolvedMinSize = Layout.ResolveWindowSize(config.Size, config.MinSize)
                if config.Resize == true then
                    resolvedSize = UDim2.fromOffset(Library.Utilities:Resize(resolvedSize.X.Offset, resolvedSize.Y.Offset))
                    resolvedMinSize = Vector2.new(Library.Utilities:Resize(resolvedMinSize.X, resolvedMinSize.Y))
                    resolvedSize, resolvedMinSize = Layout.ResolveWindowSize(resolvedSize, resolvedMinSize)
                end
                config.Size = resolvedSize
                config.MinSize = resolvedMinSize
                Library.MinimizeKey = ((typeof(config.MinimizeKey) == 'string' or typeof(config.MinimizeKey) == 'EnumItem' and config.MinimizeKey.EnumType == Enum.KeyCode) and {(config.MinimizeKey)} or {(Enum.KeyCode.LeftControl)})[1]
                Library.UseAcrylic = false
                Library.Acrylic = false
                local savedSettings = Creator.LoadSettings()
                if typeof(savedSettings.MenuFontSize) == 'number' then
                    Creator.SetFontSize(savedSettings.MenuFontSize, true)
                elseif typeof(config.FontSize) == 'number' then
                    Creator.SetFontSize(config.FontSize, true)
                end
                if typeof(savedSettings.MenuFontFamily) == 'string' and savedSettings.MenuFontFamily ~= '' then
                    Creator.SetFontFamily(savedSettings.MenuFontFamily, true)
                elseif typeof(config.FontFamily) == 'string' and config.FontFamily ~= '' then
                    Creator.SetFontFamily(config.FontFamily, true)
                end
                local defaultTheme = (typeof(config.Theme) == 'string' and {(config.Theme)} or {'Vynixu'})[1]
                Library.Theme = (typeof(savedSettings.Theme) == 'string' and table.find(Library.Themes, savedSettings.Theme)) and savedSettings.Theme or defaultTheme
                local tabWidth = Layout.IsMobile and math.min(config.TabWidth or Layout.Window.DefaultTabWidth, 100) or (config.TabWidth or 160)
                local window = require(Components.Window) {
                    Config = config,
                    Parent = screenGui,
                    Size = config.Size,
                    MinSize = config.MinSize,
                    Title = config.Title,
                    SubTitle = config.SubTitle or 'Made with Fluent Renewed',
                    TabWidth = tabWidth,
                    Mobile = config.Mobile or {
                        GetIcon = function(isVisible)
                            return Library.Utilities:GetIcon(isVisible and 'phosphor-eye' or 'phosphor-eye-slash')
                        end,
                        Size = UDim2.fromOffset(30, 30)
                    }
                }
                if typeof(savedSettings.LanguageMode) == 'string' and savedSettings.LanguageMode ~= '' then
                    Creator.Locale.Mode = savedSettings.LanguageMode
                elseif typeof(config.Language) == 'string' and config.Language ~= '' then
                    Creator.Locale.Mode = config.Language
                end
                if savedSettings.AutoTranslate ~= nil then
                    Creator.Locale.AutoTranslate = savedSettings.AutoTranslate ~= false
                elseif config.AutoTranslate ~= nil then
                    Creator.Locale.AutoTranslate = config.AutoTranslate ~= false
                end
                if Creator.Locale.Mode == 'Auto' and Creator.Locale.DetectedLang == nil then
                    Creator.DetectCountryLocaleAsync()
                end
                Creator.UpdateLocale()
                screenGui.Name = `FluentRenewed_{config.Title}`
                Library.CreatedWindow = window
                Library:SetTheme(Library.Theme, true)

                if typeof(savedSettings.WindowTransparency) == 'number' then
                    window:SetWindowTransparency(savedSettings.WindowTransparency, true)
                elseif typeof(config.Transparency) == 'number' then
                    window:SetWindowTransparency(config.Transparency, true)
                end

                if typeof(savedSettings.BackgroundScaleMode) == 'string' then
                    window:SetBackgroundScale(savedSettings.BackgroundScaleMode, true)
                end
                if typeof(savedSettings.BackgroundTransparency) == 'number' then
                    window:SetBackgroundTransparency(savedSettings.BackgroundTransparency, true)
                end
                if typeof(savedSettings.BackgroundOverlay) == 'number' then
                    window:SetBackgroundOverlay(savedSettings.BackgroundOverlay, true)
                end

                if savedSettings.BackgroundSource ~= nil then
                    if savedSettings.BackgroundSource ~= '' then
                        window:SetBackgroundImage(savedSettings.BackgroundSource, {
                            ScaleMode = savedSettings.BackgroundScaleMode or window.BackgroundState.ScaleMode,
                            Transparency = savedSettings.BackgroundTransparency or window.BackgroundState.ImageTransparency,
                            Overlay = savedSettings.BackgroundOverlay or window.BackgroundState.OverlayTransparency,
                            Silent = true,
                            SkipSave = true
                        })
                    end
                elseif typeof(config.Background) == 'table' then
                    window:SetBackgroundImage(config.Background.Image or config.Background.Asset or '', {
                        ScaleMode = config.Background.ScaleMode,
                        Transparency = config.Background.Transparency,
                        Overlay = config.Background.Overlay,
                        Silent = true,
                        SkipSave = true
                    })
                end

                if config.AutoSettingsTab ~= false then
                    local settingsTab = window.TabManager:New(Creator.Translate('SettingsTab'), 'settings', window.TabHolder, {
                        IsSystem = true,
                        LayoutOrder = 999999,
                        LocaleKey = 'SettingsTab'
                    })
                    window.SettingsTab = settingsTab

                    local langDisplayNames = {
                        vi = 'Tiếng Việt',
                        en = 'English'
                    }
                    local langCodes = {'Auto', 'vi', 'en'}
                    local initialLangCode = (Creator.Locale.Mode == 'Auto' or Creator.Locale.Mode == '' or Creator.Locale.Mode == nil) and 'Auto' or Creator.GetActiveLocale()

                    local interfaceSec = settingsTab:AddSection(Creator.Translate('SettingsInterfaceSection'))
                    local langDropdown = interfaceSec:AddDropdown('FluentBuiltInLanguage', {
                        Title = Creator.Translate('SettingsLanguageTitle'),
                        Description = Creator.Translate('SettingsLanguageDesc'),
                        Values = langCodes,
                        Multi = false,
                        Default = initialLangCode,
                        Displayer = function(code)
                            if code == 'Auto' then
                                return Creator.Translate('SettingsAutoLangOption')
                            end
                            return langDisplayNames[code] or tostring(code)
                        end,
                        Callback = function(selectedCode)
                            local targetMode = selectedCode or 'Auto'
                            if targetMode ~= Creator.Locale.Mode then
                                Library:SetLanguage(targetMode)
                            end
                        end
                    })

                    local autoTranslateToggle = interfaceSec:AddToggle('FluentBuiltInAutoTranslate', {
                        Title = Creator.Translate('SettingsAutoTranslateTitle'),
                        Description = Creator.Translate('SettingsAutoTranslateDesc'),
                        Default = Creator.Locale.AutoTranslate,
                        Callback = function(enabled)
                            if enabled ~= Creator.Locale.AutoTranslate then
                                Library:SetAutoTranslate(enabled)
                            end
                        end
                    })

                    local syncingTheme = false
                    local themeDropdown = interfaceSec:AddDropdown('FluentBuiltInTheme', {
                        Title = Creator.Translate('SettingsThemeTitle'),
                        Description = Creator.Translate('SettingsThemeDesc'),
                        Values = Library.Themes,
                        Multi = false,
                        Default = Library.Theme,
                        Callback = function(selectedTheme)
                            if not syncingTheme and selectedTheme ~= Library.Theme then
                                Library:SetTheme(selectedTheme)
                            end
                        end
                    })
                    Creator.AddSignal(Library.ThemeChanged, function(newTheme)
                        if themeDropdown.Value ~= newTheme then
                            syncingTheme = true
                            themeDropdown:SetValue(newTheme)
                            syncingTheme = false
                        end
                    end)

                    local winTransSlider = interfaceSec:AddSlider('FluentBuiltInWinTrans', {
                        Title = Creator.Translate('SettingsWinTransTitle'),
                        Description = Creator.Translate('SettingsWinTransDesc'),
                        Default = window.BackgroundState.MenuTransparency or 0,
                        Min = 0,
                        Max = 0.85,
                        Rounding = 2,
                        Callback = function(val)
                            if math.abs((tonumber(val) or 0) - (window.BackgroundState.MenuTransparency or 0)) > 0.001 then
                                window:SetWindowTransparency(val)
                            end
                        end
                    })

                    local fontSizeSlider = interfaceSec:AddSlider('FluentBuiltInFontSize', {
                        Title = Creator.Translate('SettingsFontSizeTitle'),
                        Description = Creator.Translate('SettingsFontSizeDesc'),
                        Default = Creator.FontSize or 14,
                        Min = 14,
                        Max = 20,
                        Rounding = 0,
                        Callback = function(val)
                            local nextVal = math.clamp(math.floor((tonumber(val) or 14) + 0.5), 14, 20)
                            if nextVal ~= Creator.FontSize then
                                Library:SetFontSize(nextVal)
                            end
                        end
                    })

                    local fontFamilyDropdown = interfaceSec:AddDropdown('FluentBuiltInFontFamily', {
                        Title = Creator.Translate('SettingsFontFamilyTitle'),
                        Description = Creator.Translate('SettingsFontFamilyDesc'),
                        Values = Creator.FontPresetOrder,
                        Multi = false,
                        Default = Creator.FontFamily or 'Default',
                        Displayer = function(fontKey)
                            local preset = Creator.FontPresets and Creator.FontPresets[fontKey]
                            return (preset and preset.Label) or tostring(fontKey)
                        end,
                        Callback = function(selectedFont)
                            local nextFont = selectedFont or 'Default'
                            if nextFont ~= Creator.FontFamily then
                                Library:SetFontFamily(nextFont)
                            end
                        end
                    })

                    local bgSec = settingsTab:AddSection(Creator.Translate('SettingsBackgroundSection'))
                    local bgSourceText = window.BackgroundState.Source or ''
                    local bgInput = bgSec:AddInput('FluentBuiltInBgInput', {
                        Title = Creator.Translate('SettingsBgInputTitle'),
                        Description = Creator.Translate('SettingsBgInputDesc'),
                        Default = bgSourceText,
                        Placeholder = Creator.Translate('SettingsBgInputPlaceholder'),
                        Finished = false,
                        Callback = function(val)
                            bgSourceText = tostring(val or '')
                        end
                    })

                    local bgApplyBtn = bgSec:AddButton({
                        Title = Creator.Translate('SettingsBgApplyTitle'),
                        Description = Creator.Translate('SettingsBgApplyDesc'),
                        Callback = function()
                            window:SetBackgroundImage(bgSourceText)
                        end
                    })

                    local bgResetBtn = bgSec:AddButton({
                        Title = Creator.Translate('SettingsBgResetTitle'),
                        Description = Creator.Translate('SettingsBgResetDesc'),
                        Callback = function()
                            bgSourceText = ''
                            bgInput:SetValue('')
                            window:ResetBackground()
                        end
                    })

                    local selectedSavedBg = nil
                    local function getSavedBgDropdownValues()
                        local files = Creator.ListSavedBackgrounds()
                        if #files == 0 then
                            return {'__none__'}
                        end
                        return files
                    end

                    local bgSavedDropdown = bgSec:AddDropdown('FluentBuiltInBgSaved', {
                        Title = Creator.Translate('SettingsBgSavedTitle'),
                        Description = Creator.Translate('SettingsBgSavedDesc'),
                        Values = getSavedBgDropdownValues(),
                        Multi = false,
                        AllowNull = true,
                        Default = (typeof(window.BackgroundState.Source) == 'string' and table.find(Creator.ListSavedBackgrounds(), window.BackgroundState.Source)) and window.BackgroundState.Source or nil,
                        Displayer = function(val)
                            if val == '__none__' then
                                return Creator.Translate('SettingsBgNoSaved')
                            end
                            return Creator.FormatSavedBackgroundName(val)
                        end,
                        Callback = function(selectedFile)
                            if not selectedFile or selectedFile == '__none__' then
                                selectedSavedBg = nil
                                return
                            end
                            selectedSavedBg = selectedFile
                            bgSourceText = selectedFile
                            bgInput:SetValue(selectedFile)
                            if selectedFile ~= window.BackgroundState.Source then
                                window:SetBackgroundImage(selectedFile)
                            end
                        end
                    })

                    local function refreshSavedBgDropdown()
                        local nextVals = getSavedBgDropdownValues()
                        if selectedSavedBg and not table.find(nextVals, selectedSavedBg) then
                            selectedSavedBg = nil
                            rawset(bgSavedDropdown, 'Value', nil)
                        end
                        bgSavedDropdown:SetValues(nextVals)
                        bgSavedDropdown:Display()
                    end
                    window._bgListListeners = window._bgListListeners or {}
                    window._bgListListeners[#window._bgListListeners + 1] = refreshSavedBgDropdown

                    local bgDeleteBtn = bgSec:AddButton({
                        Title = Creator.Translate('SettingsBgDeleteTitle'),
                        Description = Creator.Translate('SettingsBgDeleteDesc'),
                        Callback = function()
                            local targetPath = selectedSavedBg
                            if not targetPath or targetPath == '__none__' then
                                Library:Notify {
                                    Title = Creator.Translate('SettingsBackgroundSection'),
                                    Content = Creator.Translate('SettingsBgDeleteEmpty'),
                                    Duration = 3
                                }
                                return
                            end
                            local deleted = Creator.DeleteSavedBackground(targetPath)
                            if deleted then
                                if window.BackgroundState.Source == targetPath then
                                    bgSourceText = ''
                                    bgInput:SetValue('')
                                    window:ResetBackground()
                                end
                                selectedSavedBg = nil
                                rawset(bgSavedDropdown, 'Value', nil)
                                refreshSavedBgDropdown()
                                Library:Notify {
                                    Title = Creator.Translate('SettingsBackgroundSection'),
                                    Content = Creator.Translate('SettingsBgDeleted'),
                                    Duration = 3
                                }
                            else
                                refreshSavedBgDropdown()
                            end
                        end
                    })

                    local bgScaleDropdown = bgSec:AddDropdown('FluentBuiltInBgScale', {
                        Title = Creator.Translate('SettingsBgScaleTitle'),
                        Description = Creator.Translate('SettingsBgScaleDesc'),
                        Values = {'Crop', 'Fit', 'Tile', 'Stretch'},
                        Multi = false,
                        Default = window.BackgroundState.ScaleMode or 'Crop',
                        Displayer = function(modeKey)
                            return Creator.Translate('SettingsScale' .. tostring(modeKey))
                        end,
                        Callback = function(selectedMode)
                            local nextMode = selectedMode or 'Crop'
                            if nextMode ~= window.BackgroundState.ScaleMode then
                                window:SetBackgroundScale(nextMode)
                            end
                        end
                    })

                    local bgTransSlider = bgSec:AddSlider('FluentBuiltInBgTrans', {
                        Title = Creator.Translate('SettingsBgTransTitle'),
                        Description = Creator.Translate('SettingsBgTransDesc'),
                        Default = window.BackgroundState.ImageTransparency,
                        Min = 0,
                        Max = 0.9,
                        Rounding = 2,
                        Callback = function(val)
                            if math.abs((tonumber(val) or 0) - (window.BackgroundState.ImageTransparency or 0)) > 0.001 then
                                window:SetBackgroundTransparency(val)
                            end
                        end
                    })

                    local bgOverlaySlider = bgSec:AddSlider('FluentBuiltInBgOverlay', {
                        Title = Creator.Translate('SettingsBgOverlayTitle'),
                        Description = Creator.Translate('SettingsBgOverlayDesc'),
                        Default = window.BackgroundState.OverlayTransparency,
                        Min = 0.05,
                        Max = 1,
                        Rounding = 2,
                        Callback = function(val)
                            if math.abs((tonumber(val) or 0.55) - (window.BackgroundState.OverlayTransparency or 0.55)) > 0.001 then
                                window:SetBackgroundOverlay(val)
                            end
                        end
                    })

                    local function refreshBuiltInSettingsLocale()
                        interfaceSec:SetTitle(Creator.Translate('SettingsInterfaceSection'))
                        langDropdown:SetTitle(Creator.Translate('SettingsLanguageTitle'))
                        langDropdown:SetDesc(Creator.Translate('SettingsLanguageDesc'))
                        langDropdown:BuildDropdownList()
                        langDropdown:Display()
                        autoTranslateToggle:SetTitle(Creator.Translate('SettingsAutoTranslateTitle'))
                        autoTranslateToggle:SetDesc(Creator.Translate('SettingsAutoTranslateDesc'))
                        themeDropdown:SetTitle(Creator.Translate('SettingsThemeTitle'))
                        themeDropdown:SetDesc(Creator.Translate('SettingsThemeDesc'))
                        winTransSlider:SetTitle(Creator.Translate('SettingsWinTransTitle'))
                        winTransSlider:SetDesc(Creator.Translate('SettingsWinTransDesc'))
                        fontSizeSlider:SetTitle(Creator.Translate('SettingsFontSizeTitle'))
                        fontSizeSlider:SetDesc(Creator.Translate('SettingsFontSizeDesc'))
                        fontFamilyDropdown:SetTitle(Creator.Translate('SettingsFontFamilyTitle'))
                        fontFamilyDropdown:SetDesc(Creator.Translate('SettingsFontFamilyDesc'))
                        bgSec:SetTitle(Creator.Translate('SettingsBackgroundSection'))
                        bgInput:SetTitle(Creator.Translate('SettingsBgInputTitle'))
                        bgInput:SetDesc(Creator.Translate('SettingsBgInputDesc'))
                        if bgInput.Instance and bgInput.Instance.Frame then
                            local tb = bgInput.Instance.Frame:FindFirstChildWhichIsA('TextBox', true)
                            if tb then
                                tb.PlaceholderText = Creator.Translate('SettingsBgInputPlaceholder')
                            end
                        end
                        bgApplyBtn:SetTitle(Creator.Translate('SettingsBgApplyTitle'))
                        bgApplyBtn:SetDesc(Creator.Translate('SettingsBgApplyDesc'))
                        bgResetBtn:SetTitle(Creator.Translate('SettingsBgResetTitle'))
                        bgResetBtn:SetDesc(Creator.Translate('SettingsBgResetDesc'))
                        bgSavedDropdown:SetTitle(Creator.Translate('SettingsBgSavedTitle'))
                        bgSavedDropdown:SetDesc(Creator.Translate('SettingsBgSavedDesc'))
                        bgSavedDropdown:BuildDropdownList()
                        bgSavedDropdown:Display()
                        bgDeleteBtn:SetTitle(Creator.Translate('SettingsBgDeleteTitle'))
                        bgDeleteBtn:SetDesc(Creator.Translate('SettingsBgDeleteDesc'))
                        bgScaleDropdown:SetTitle(Creator.Translate('SettingsBgScaleTitle'))
                        bgScaleDropdown:SetDesc(Creator.Translate('SettingsBgScaleDesc'))
                        bgScaleDropdown:BuildDropdownList()
                        bgScaleDropdown:Display()
                        bgTransSlider:SetTitle(Creator.Translate('SettingsBgTransTitle'))
                        bgTransSlider:SetDesc(Creator.Translate('SettingsBgTransDesc'))
                        bgOverlaySlider:SetTitle(Creator.Translate('SettingsBgOverlayTitle'))
                        bgOverlaySlider:SetDesc(Creator.Translate('SettingsBgOverlayDesc'))
                    end
                    Creator.AddSignal(Library.LanguageChanged, refreshBuiltInSettingsLocale)
                end

                if config.AutoSocialTabs ~= false then
                    local socialCfg = typeof(config.Social) == 'table' and config.Social or {}
                    local profileCfg = typeof(config.Profile) == 'table' and config.Profile or {}
                    local discordUserId = tostring(socialCfg.DiscordUserId or '1542784329703227425')
                    local fbUrl = tostring(socialCfg.Facebook or 'https://www.facebook.com/nguynduyz')
                    local tiktokUrl = tostring(socialCfg.TikTok or 'https://www.tiktok.com/@rezhub_official')
                    local zaloUrl = tostring(socialCfg.Zalo or 'https://zalo.me/g/fefao7jgu5oypks7tual')
                    local subCode = typeof(config.SubTitle) == 'string' and config.SubTitle:match('discord%.gg/([%w%-_]+)')
                    local inviteSrc = tostring(socialCfg.DiscordInvite or profileCfg.DiscordInviteUrl or profileCfg.DiscordInvite or subCode or 'rezhub')
                    local inviteCode = inviteSrc:match('discord%.gg/([%w%-_]+)') or inviteSrc:match('^([%w%-_]+)$') or 'rezhub'
                    local inviteLink = 'https://discord.gg/' .. inviteCode
                    local isMobUI = Layout.IsMobile

                    local infoTab = window.TabManager:New(Creator.Translate('InfoTab'), 'info', window.TabHolder, {
                        IsSystem = true,
                        LayoutOrder = -2,
                        LocaleKey = 'InfoTab'
                    })
                    local discordTab = window.TabManager:New(Creator.Translate('DiscordTab'), 'message-circle', window.TabHolder, {
                        IsSystem = true,
                        LayoutOrder = -1,
                        LocaleKey = 'DiscordTab'
                    })
                    window.InfoTab = infoTab
                    window.DiscordTab = discordTab

                    local function openOrCopySocial(url, labelText)
                        local copied = Creator.OpenExternalUrl(url)
                        Library:Notify {
                            Title = labelText or 'Rez Hub',
                            Content = copied and (Creator.Translate('CopiedPrefix') .. ': ' .. url) or Creator.Translate('ClipboardUnsupported'),
                            Duration = 3
                        }
                    end

                    -- ========================================================
                    -- TAB 1: INFO -> 1 Section "Rez Hub Official" + Native Avatar Buttons
                    -- ========================================================
                    local officialSec = infoTab:AddSection('Rez Hub Official')
                    local btnAvSize = isMobUI and 34 or 40

                    local ownerBtn = officialSec:AddButton({
                        Title = 'Discord • @rez_hub',
                        Description = Creator.Translate('SocialLoading'),
                        Avatar = '',
                        AvatarSize = btnAvSize,
                        AccentColor = Color3.fromRGB(88, 101, 242),
                        Fallback = 'D',
                        StatusColor = Color3.fromRGB(128, 132, 142),
                        Callback = function()
                            openOrCopySocial(discordUserId, 'Discord ID')
                        end
                    })

                    local fbBtn = officialSec:AddButton({
                        Title = 'Facebook • nguynduyz',
                        Description = Creator.Translate('SocialLoading'),
                        Avatar = '',
                        AvatarSize = btnAvSize,
                        AccentColor = Color3.fromRGB(24, 119, 242),
                        Fallback = 'f',
                        Callback = function()
                            openOrCopySocial(fbUrl, 'Facebook')
                        end
                    })

                    local ttBtn = officialSec:AddButton({
                        Title = 'TikTok • @rezhub_official',
                        Description = Creator.Translate('SocialLoading'),
                        Avatar = '',
                        AvatarSize = btnAvSize,
                        AccentColor = Color3.fromRGB(238, 29, 82),
                        Fallback = '♪',
                        Callback = function()
                            openOrCopySocial(tiktokUrl, 'TikTok')
                        end
                    })

                    local zaloBtn = officialSec:AddButton({
                        Title = 'Zalo • Rez Hub Group',
                        Description = Creator.Translate('SocialZaloDesc'),
                        Avatar = '',
                        AvatarSize = btnAvSize,
                        AccentColor = Color3.fromRGB(0, 104, 255),
                        Fallback = 'Z',
                        Callback = function()
                            openOrCopySocial(zaloUrl, 'Zalo')
                        end
                    })

                    -- ========================================================
                    -- TAB 2: DISCORD SERVER (Native Banner Element)
                    -- ========================================================
                    local function triggerJoinDiscord()
                        local copied, link = Creator.OpenDiscordInvite(inviteCode)
                        Library:Notify {
                            Title = 'Discord',
                            Content = copied and (Creator.Translate('DiscordOpeningNotice') .. ': ' .. link) or Creator.Translate('ClipboardUnsupported'),
                            Duration = 4
                        }
                    end

                    local discordBanner = discordTab:AddBanner({
                        Title = 'Rez Hub Community',
                        Description = inviteLink,
                        BannerHeight = isMobUI and 96 or 124,
                        Avatar = '',
                        AvatarSize = isMobUI and 54 or 64,
                        AvatarCorner = 16,
                        Stats = {
                            {Text = '... ' .. Creator.Translate('DiscordOnlineWord'), Color = Color3.fromRGB(35, 165, 90)},
                            {Text = '... ' .. Creator.Translate('DiscordMembersWord'), Color = Color3.fromRGB(148, 155, 164)}
                        },
                        ButtonText = Creator.Translate('JoinDiscordBtn') .. '  (' .. inviteLink .. ')',
                        ButtonColor = Color3.fromRGB(88, 101, 242),
                        Callback = triggerJoinDiscord
                    })

                    local latestLanyard, latestSrvStats
                    local statusColorMap = {
                        online = Color3.fromRGB(35, 165, 90),
                        idle = Color3.fromRGB(240, 178, 50),
                        dnd = Color3.fromRGB(242, 63, 67),
                        offline = Color3.fromRGB(128, 132, 142)
                    }
                    local function renderLanyardInfo(info)
                        if not info then
                            return
                        end
                        latestLanyard = info
                        local nameTxt = (info.displayName and info.displayName ~= '' and info.displayName or 'Rez Hub Owner') .. ' (@' .. (info.username or 'rez_hub') .. ')'
                        ownerBtn:SetTitle(nameTxt)
                        ownerBtn:SetStatusColor(statusColorMap[info.status] or statusColorMap.offline)
                        if info.activity and info.activity ~= '' then
                            ownerBtn:SetDesc(info.status:upper() .. ' • ' .. info.activity .. '  |  ID: ' .. discordUserId)
                        else
                            ownerBtn:SetDesc((info.status or 'offline'):upper() .. '  |  ID: ' .. discordUserId)
                        end
                    end
                    local function renderDiscordServerStats(info)
                        if not info then
                            return
                        end
                        latestSrvStats = info
                        discordBanner:SetTitle(info.name or 'Rez Hub Community')
                        discordBanner:SetDesc((info.description and info.description ~= '') and info.description or inviteLink)
                        discordBanner:SetStats({
                            {Text = Creator.FormatNumber(info.online or 0) .. ' ' .. Creator.Translate('DiscordOnlineWord'), Color = Color3.fromRGB(35, 165, 90)},
                            {Text = Creator.FormatNumber(info.members or 0) .. ' ' .. Creator.Translate('DiscordMembersWord'), Color = Color3.fromRGB(148, 155, 164)}
                        })
                    end
                    Creator.AddSignal(Library.LanguageChanged, function()
                        discordBanner:SetButtonText(Creator.Translate('JoinDiscordBtn') .. '  (' .. inviteLink .. ')')
                        if not latestLanyard then
                            ownerBtn:SetDesc(Creator.Translate('SocialLoading'))
                        else
                            renderLanyardInfo(latestLanyard)
                        end
                        renderDiscordServerStats(latestSrvStats)
                    end)

                    task.spawn(function()
                        local lInfo = Creator.FetchLanyardUser(discordUserId)
                        if lInfo then
                            renderLanyardInfo(lInfo)
                            if lInfo.avatarUrl then
                                ownerBtn:SetAvatar(lInfo.avatarUrl, 'dc_u_' .. discordUserId)
                            end
                            if lInfo.decorationUrl then
                                ownerBtn:SetDecoration(lInfo.decorationUrl, 'dc_deco_' .. tostring(lInfo.decorationAsset or discordUserId))
                            end
                        else
                            ownerBtn:SetDesc('Discord ID: ' .. discordUserId)
                        end
                    end)
                    task.spawn(function()
                        local sInfo = Creator.FetchDiscordInviteStats(inviteCode)
                        if sInfo then
                            renderDiscordServerStats(sInfo)
                            if sInfo.iconUrl then
                                discordBanner:SetAvatar(sInfo.iconUrl, 'dc_srv_icon_' .. inviteCode)
                            end
                            if sInfo.bannerUrl then
                                discordBanner:SetBanner(sInfo.bannerUrl, 'dc_srv_banner_' .. inviteCode)
                            end
                        end
                    end)
                    task.spawn(function()
                        local fbMeta = Creator.FetchSocialProfileMeta(fbUrl)
                        if fbMeta then
                            if fbMeta.title and fbMeta.title ~= '' then
                                fbBtn:SetTitle('Facebook • ' .. fbMeta.title)
                            end
                            fbBtn:SetDesc((fbMeta.summary and fbMeta.summary ~= '') and fbMeta.summary or fbUrl)
                            if fbMeta.image and fbMeta.image ~= '' then
                                fbBtn:SetAvatar(fbMeta.image, 'fb_av_nguynduyz')
                            end
                        else
                            fbBtn:SetDesc(fbUrl)
                        end
                    end)
                    task.spawn(function()
                        local ttMeta = Creator.FetchSocialProfileMeta(tiktokUrl)
                        if ttMeta then
                            if ttMeta.title and ttMeta.title ~= '' then
                                ttBtn:SetTitle('TikTok • ' .. ttMeta.title)
                            end
                            ttBtn:SetDesc((ttMeta.summary and ttMeta.summary ~= '') and ttMeta.summary or tiktokUrl)
                            if ttMeta.image and ttMeta.image ~= '' then
                                ttBtn:SetAvatar(ttMeta.image, 'tt_av_rezhub')
                            end
                        else
                            ttBtn:SetDesc(tiktokUrl)
                        end
                    end)
                    task.spawn(function()
                        local zMeta = Creator.FetchSocialProfileMeta(zaloUrl)
                        if zMeta and zMeta.title and not zMeta.title:find('Đăng nhập') then
                            zaloBtn:SetTitle('Zalo • ' .. zMeta.title)
                            if zMeta.summary and zMeta.summary ~= '' then
                                zaloBtn:SetDesc(zMeta.summary)
                            end
                            if zMeta.image and zMeta.image ~= '' then
                                zaloBtn:SetAvatar(zMeta.image, 'zalo_av_rezhub')
                            end
                        end
                    end)
                end

                task.defer(function()
                    if window.TabManager and window.TabManager.SelectedItem == nil then
                        if window.TabManager.UserTabs[1] then
                            window:SelectTab(1)
                        elseif window.InfoTab then
                            window.TabManager:SelectItem(1, window.InfoTab)
                        elseif window.SettingsTab then
                            window.TabManager:SelectItem(1, window.SettingsTab)
                        end
                    end
                end)

                if config.Intro ~= false then
                    local introCfg = typeof(config.Intro) == 'table' and config.Intro or {}
                    window.Root.Visible = false
                    Library:PlayIntro({
                        Title = introCfg.Title or 'REZ HUB',
                        SoundId = introCfg.SoundId or 'rbxassetid://80874929641794',
                        SkipChecks = introCfg.SkipChecks
                    }, function()
                        if window.Root and window.Root.Parent and not window.Minimized then
                            window.Root.Visible = true
                            window:PlayEntranceAnim(0.38, 0.92, Layout.IsMobile and 14 or 22)
                        end
                    end)
                end
                return window
            end

            function Library:GetLocale()
                return Creator.GetActiveLocale()
            end

            function Library:GetLanguageMode()
                return Creator.Locale.Mode
            end

            function Library:SetLanguage(mode)
                Creator.Locale.Mode = (typeof(mode) == 'string' and mode ~= '') and mode or 'Auto'
                Creator.SaveSettings({LanguageMode = Creator.Locale.Mode})
                Creator.UpdateLocale()
            end

            function Library:SetAutoTranslate(enabled)
                local state = enabled ~= false
                Creator.SaveSettings({AutoTranslate = state})
                Creator.SetAutoTranslate(state)
            end

            function Library:Translate(key, fallback)
                return Creator.Translate(key, fallback)
            end

