                    element.Border,
                    element.LabelHolder
                }))

                local rawTitle, rawDesc = title, desc

                function element:SetTitle(text)
                    rawTitle = text
                    element.TitleLabel.Text = Creator.TranslateRaw(rawTitle)
                end

                function element:SetDesc(text)
                    if text == nil then
                        text = ''
                    end
                    rawDesc = text
                    if text == '' then
                        element.DescLabel.Visible = false
                    else
                        element.DescLabel.Visible = true
                    end
                    element.DescLabel.Text = Creator.TranslateRaw(rawDesc)
                end

                function element:Destroy()
                    element.Frame:Destroy()
