                Creator.BindFont(element.TitleLabel, Layout.Card.TitleTextSize, {
                    maxCap = 22,
                    onResize = function(sz)
                        element.TitleLabel.Size = UDim2.new(1, 0, 0, math.max(Layout.Card.TitleHeight, sz + 3))
                    end
                })
                Creator.BindFont(element.DescLabel, Layout.Card.DescTextSize, {maxCap = 20})
                Creator.BindLocale(element.TitleLabel, 'Text', function()
                    return Creator.TranslateRaw(rawTitle)
                end)
                Creator.BindLocale(element.DescLabel, 'Text', function()
                    return Creator.TranslateRaw(rawDesc)
                end)
                element:SetTitle(title)
                element:SetDesc(desc)
                if clickable then
                    local _, hoverMotor, setHoverAlpha = Root.Themes, Creator.SpringMotor(Creator.GetThemeProperty'ElementTransparency', element.Frame, 'BackgroundTransparency', false, true)
                    Creator.AddSignal(element.Frame.MouseEnter, function()
                        setHoverAlpha(Creator.GetThemeProperty'ElementTransparency' - Creator.GetThemeProperty'HoverChange')
                    end)
                    Creator.AddSignal(element.Frame.MouseLeave, function()
                        setHoverAlpha(Creator.GetThemeProperty'ElementTransparency')
                    end)
                    Creator.AddSignal(element.Frame.MouseButton1Down, function()
                        setHoverAlpha(Creator.GetThemeProperty'ElementTransparency' + Creator.GetThemeProperty'HoverChange')
                    end)
                    Creator.AddSignal(element.Frame.MouseButton1Up, function()
                        setHoverAlpha(Creator.GetThemeProperty'ElementTransparency' - Creator.GetThemeProperty'HoverChange')
                    end)
                end
                return setmetatable(element, {
                    __newindex = function(tbl, key, val)
                        if key == 'Title' then
                            element:SetTitle(val)
                        elseif key == 'Description' or key == 'Desc' then
                            element:SetDesc(val)
                        end
                        return rawset(tbl, key, val)
                    end
                })
            end
        end)()
    end,

