    [10] = function()
        local env, script, require = waxGetEnv(10)
        return (function(...)
            local TextService, Root = game:GetService'TextService', script.Parent.Parent
            local Flipper, Creator, Layout = require(Root.Packages.Flipper), require(Root.Modules.Creator), require(Root.Modules.Layout)
            local New = Creator.New
            return function(parent, acrylic)
                local textbox, boxPad, indBottom = {}, Layout.IsMobile and 6 or 10, Layout.IsMobile and -3 or -5
                acrylic = acrylic or false
                textbox.Input = New('TextBox', {
                    FontFace = Font.new'rbxasset://fonts/families/GothamSSm.json',
                    TextColor3 = Color3.fromRGB(200, 200, 200),
                    TextSize = Layout.Card.ControlTextSize,
                    TextWrapped = false,
                    MultiLine = false,
                    TextXAlignment = Enum.TextXAlignment.Left,
                    TextYAlignment = Enum.TextYAlignment.Center,
                    BackgroundColor3 = Color3.fromRGB(255, 255, 255),
                    AutomaticSize = Enum.AutomaticSize.Y,
                    BackgroundTransparency = 1,
                    Size = UDim2.fromScale(1, 1),
                    Position = UDim2.fromOffset(4, 0),
                    ThemeTag = {TextColor3 = 'Text', PlaceholderColor3 = 'SubText'}
                })
                textbox.Container = New('Frame', {
                    BackgroundTransparency = 1,
                    ClipsDescendants = true,
                    Position = UDim2.new(0, boxPad, 0, 0),
                    Size = UDim2.new(1, -(boxPad * 2), 1, 0)
                }, {textbox.Input})
                textbox.Indicator = New('Frame', {
                    Size = UDim2.new(1, -(boxPad * 2), 0, 2),
                    Position = UDim2.new(0, boxPad, 1, indBottom),
                    AnchorPoint = Vector2.new(0, 1),
                    BackgroundTransparency = acrylic and 1 or 0.4,
                    ThemeTag = {BackgroundColor3 = acrylic and 'InputIndicator' or 'DialogInputLine'}
                })
                textbox.Frame = New('Frame', {
                    Size = UDim2.new(0, 0, 0, Layout.Card.ControlHeight),
                    BackgroundTransparency = acrylic and 0.8 or 0.08,
                    Parent = parent,
                    ThemeTag = {BackgroundColor3 = acrylic and 'Input' or 'DialogInput'}
                }, {
                    New('UICorner', {CornerRadius = UDim.new(0, Layout.Card.Radius)}),
                    New('UIStroke', {
                        ApplyStrokeMode = Enum.ApplyStrokeMode.Border,
                        Transparency = acrylic and 0.35 or 0.45,
                        ThemeTag = {Color = acrylic and 'InElementBorder' or 'DialogButtonBorder'}
                    }),
                    textbox.Indicator,
                    textbox.Container
                })

                local function updateInputOffset()
                    local padding, xPos = 2, textbox.Container.AbsoluteSize.X
                    if not textbox.Input:IsFocused() or textbox.Input.TextBounds.X <= xPos - 2 * padding then
                        textbox.Input.Position = UDim2.new(0, padding, 0, 0)
                    else
                        local cursorPos = textbox.Input.CursorPosition
                        if cursorPos ~= -1 then
                            local prefixText = string.sub(textbox.Input.Text, 1, cursorPos - 1)
                            local xPos2 = TextService:GetTextSize(prefixText, textbox.Input.TextSize, textbox.Input.Font, Vector2.new(math.huge, math.huge)).X
                            local cursorOffsetX = textbox.Input.Position.X.Offset + xPos2
                            if cursorOffsetX < padding then
                                textbox.Input.Position = UDim2.fromOffset(padding - xPos2, 0)
                            elseif cursorOffsetX > xPos - padding - 1 then
                                textbox.Input.Position = UDim2.fromOffset(xPos - xPos2 - padding - 1, 0)
                            end
                        end
                    end
                end
                task.spawn(updateInputOffset)
                Creator.AddSignal(textbox.Input:GetPropertyChangedSignal'Text', updateInputOffset)
                Creator.AddSignal(textbox.Input:GetPropertyChangedSignal'CursorPosition', updateInputOffset)
                Creator.AddSignal(textbox.Input.Focused, function()
                    updateInputOffset()
                    textbox.Indicator.Size = UDim2.new(1, -(boxPad * 2), 0, 2)
                    textbox.Indicator.Position = UDim2.new(0, boxPad, 1, indBottom)
                    textbox.Indicator.BackgroundTransparency = 0
                    Creator.OverrideTag(textbox.Frame, {BackgroundColor3 = acrylic and 'InputFocused' or 'DialogHolder'})
                    Creator.OverrideTag(textbox.Indicator, {BackgroundColor3 = 'Accent'})
                end)
                Creator.AddSignal(textbox.Input.FocusLost, function()
                    updateInputOffset()
                    textbox.Indicator.Size = UDim2.new(1, -(boxPad * 2), 0, 2)
                    textbox.Indicator.Position = UDim2.new(0, boxPad, 1, indBottom)
                    textbox.Indicator.BackgroundTransparency = acrylic and 1 or 0.4
                    Creator.OverrideTag(textbox.Frame, {BackgroundColor3 = acrylic and 'Input' or 'DialogInput'})
                    Creator.OverrideTag(textbox.Indicator, {BackgroundColor3 = acrylic and 'InputIndicator' or 'DialogInputLine'})
                end)
                return textbox
            end
        end)()
    end,

