                local function getExecutorName()
                    if typeof(identifyexecutor) == 'function' then
                        local ok, executorName = pcall(identifyexecutor)
                        if ok and executorName then
                            return tostring(executorName)
                        end
                    end
                    return 'Unknown'
                end

                local function sendWebhook(feedbackType, webhookUrl, subject, bodyText)
                    local httpReq = getHttpRequest()
                    if typeof(httpReq) ~= 'function' then
                        return false, 'HTTP requests are not supported by this executor.'
                    end
                    local payload = {
                        embeds = {
                            {
                                title = `Script {feedbackType}: {subject}`,
                                color = feedbackType == 'Suggest' and 16766720 or 16740488,
                                fields = {
                                    {name = 'Name Script', value = subject, inline = false},
                                    {
                                        name = feedbackType == 'Suggest' and 'Suggest' or 'Report Bug',
                                        value = bodyText,
                                        inline = false
                                    },
                                    {name = 'Executor', value = getExecutorName(), inline = false}
                                },
                                footer = {text = 'Time: ' .. os.date'%c'}
                            }
                        }
                    }
                    local ok, response = pcall(httpReq, {
                        Url = webhookUrl,
                        Method = 'POST',
                        Headers = {['Content-Type'] = 'application/json'},
                        Body = HttpService:JSONEncode(payload)
                    })
                    if not ok then
                        return false, tostring(response)
                    end
                    if typeof(response) == 'table' then
                        local statusCode = tonumber(response.StatusCode or response.Status)
                        if statusCode and (statusCode < 200 or statusCode >= 300) then
                            return false, response.Body or `Request failed ({statusCode}).`
                        end
                    end
                    return true
                end

