                function Window:PlayEntranceAnim(duration, startScale, yOffset)
                    if not Window.Root or not Window.Root.Parent then
                        return
                    end
                    local d = duration or 0.34
                    local oldScale = Window.Root:FindFirstChild('_RezIntroScale')
                    if oldScale then
                        oldScale:Destroy()
                    end
                    local introScale = New('UIScale', {
                        Name = '_RezIntroScale',
                        Scale = startScale or 0.90,
                        Parent = Window.Root
                    })
                    local targetX, targetY = Window.Position.X.Offset, Window.Position.Y.Offset
                    if Window.Maximized then
                        targetX, targetY = 0, 0
                    end
                    local slideY = targetY + (yOffset or (isMobile and 14 or 22))
                    posMotor:setGoal {X = Instant(targetX), Y = Instant(slideY)}
                    posMotor:step(0)
                    posMotor:setGoal {
                        X = Spring(targetX, {frequency = 7.5, dampingRatio = 0.9}),
                        Y = Spring(targetY, {frequency = 7.5, dampingRatio = 0.9})
                    }
                    TweenService:Create(introScale, TweenInfo.new(d, Enum.EasingStyle.Quint, Enum.EasingDirection.Out), {Scale = 1}):Play()
                    task.delay(d + 0.05, function()
                        if introScale and introScale.Parent then
                            introScale:Destroy()
                        end
                    end)
                end
                if config.Config and config.Config.Intro == false then
                    Window:PlayEntranceAnim(0.36, 0.90, isMobile and 14 or 22)
                end
