                    Window.TitleBar.MaxButton.Frame.Icon.Image = maximized and Assets.Restore or Assets.Max
                    if maximized then
                        savedWidth = Window.Size.X.Offset
                        savedHeight = Window.Size.Y.Offset
                    end
                    local targetWidth, targetHeight = maximized and Camera.ViewportSize.X or savedWidth, maximized and Camera.ViewportSize.Y or savedHeight
                    sizeMotor:setGoal {
                        X = Flipper[noMinimize and 'Instant' or 'Spring'].new(targetWidth, {frequency = 6}),
                        Y = Flipper[noMinimize and 'Instant' or 'Spring'].new(targetHeight, {frequency = 6})
                    }
                    Window.Size = UDim2.fromOffset(targetWidth, targetHeight)
                    if not instant then
                        posMotor:setGoal {
                            X = Spring(maximized and 0 or Window.Position.X.Offset, {frequency = 6}),
                            Y = Spring(maximized and 0 or Window.Position.Y.Offset, {frequency = 6})
                        }
                    end
                    Window.PostMaximized:Fire(tick())
                end
                Creator.AddSignal(Window.TitleBar.Frame.InputBegan, function(input)
                    if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
                        isDragging = true
                        dragStartPos = input.Position
                        startWindowPos = Window.Root.Position
                        if Window.Maximized then
                            startWindowPos = UDim2.fromOffset(Mouse.X - (Mouse.X * ((savedWidth - 100) / Window.Root.AbsoluteSize.X)), Mouse.Y - (Mouse.Y * (savedHeight / Window.Root.AbsoluteSize.Y)))
                        end
                        input.Changed:Connect(function()
                            if input.UserInputState == Enum.UserInputState.End then
                                isDragging = false
                            end
                        end)
                    end
                end)
                Creator.AddSignal(Window.TitleBar.Frame.InputChanged, function(input)
                    if input.UserInputType == Enum.UserInputType.MouseMovement or input.UserInputType == Enum.UserInputType.Touch then
                        dragInput = input
                    end
                end)
                Creator.AddSignal(resizeGrip.InputBegan, function(input)
                    if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
                        isResizing = true
                        resizeStartPos = input.Position
                    end
                end)
                Creator.AddSignal(UserInputService.InputChanged, function(input)
                    if input == dragInput and isDragging then
                        local dragDelta = input.Position - dragStartPos
                        Window.Position = UDim2.fromOffset(startWindowPos.X.Offset + dragDelta.X, startWindowPos.Y.Offset + dragDelta.Y)
                        posMotor:setGoal {X = Instant(Window.Position.X.Offset), Y = Instant(Window.Position.Y.Offset)}
                        if Window.Maximized then
                            Window.Maximize(false, true, true)
                        end
                    end
                    if (input.UserInputType == Enum.UserInputType.MouseMovement or input.UserInputType == Enum.UserInputType.Touch) and isResizing then
                        local resizeDelta, startSize, vp = input.Position - resizeStartPos, Window.Size, Layout.GetViewportSize()
                        local maxW, maxH = isMobile and math.max(Window.MinSize.X, vp.X) or 2048, isMobile and math.max(Window.MinSize.Y, vp.Y) or 2048
                        local rawSize = Vector3.new(startSize.X.Offset, startSize.Y.Offset, 0) + Vector3.new(1, 1, 0) * resizeDelta
                        local clampedSize = Vector2.new(math.clamp(rawSize.X, Window.MinSize.X, maxW), math.clamp(rawSize.Y, Window.MinSize.Y, maxH))
                        sizeMotor:setGoal {X = Flipper.Instant.new(clampedSize.X), Y = Flipper.Instant.new(clampedSize.Y)}
                    end
                end)
                Creator.AddSignal(UserInputService.InputEnded, function(input)
                    if isResizing == true or input.UserInputType == Enum.UserInputType.Touch then
                        isResizing = false
                        Window.Size = UDim2.fromOffset(sizeMotor:getValue().X, sizeMotor:getValue().Y)
                    end
                end)
                Creator.AddSignal(Window.TabHolder.UIListLayout:GetPropertyChangedSignal'AbsoluteContentSize', function()
                    if Window.TabHolder.CanvasSize ~= UDim2.fromOffset(0, Window.TabHolder.UIListLayout.AbsoluteContentSize.Y) then
                        Window.TabHolder.CanvasSize = UDim2.fromOffset(0, Window.TabHolder.UIListLayout.AbsoluteContentSize.Y)
                    end
                end)

                function Window:Minimize()
                    Window.Minimized = not Window.Minimized
                    Window.Root.Visible = not Window.Minimized
                    if Window.Root.Visible then
                        Window:PlayEntranceAnim(0.24, 0.94, isMobile and 8 or 12)
                    end
                    if Window.ToggleGlow then
                        Window.ToggleGlow.Enabled = Window.Minimized
                    end
                    Window.OnMinimized:Fire(tick(), Window.Root.Visible)
                    if not minimizedNoticeShown then
                        local minKey = Library.MinimizeKeybind and Library.MinimizeKeybind.Value or typeof(Library.MinimizeKey) == 'string' and Library.MinimizeKey or Library.MinimizeKey.Name
                        minimizedNoticeShown = true
                        Library:Notify {
                            Title = Creator.Translate('InterfaceTitle'),
                            Content = string.format(Creator.Translate('MinimizeNotice'), tostring(Library.Utilities:Prettify(minKey))),
                            Duration = 6
                        }
                    end
                    Window.PostMinimized:Fire(tick(), Window.Root.Visible)
                end
                Creator.AddSignal(UserInputService.InputBegan, function(input)
                    if type(Library.MinimizeKeybind) == 'table' and Library.MinimizeKeybind.Type == 'Keybind' and not UserInputService:GetFocusedTextBox() then
                        if input.KeyCode.Name == Library.MinimizeKeybind.Value or input.KeyCode.Name == Library.MinimizeKeybind.Value.Name then
                            Window:Minimize()
                        end
                    elseif (input.KeyCode == Library.MinimizeKey or input.KeyCode.Name == Library.MinimizeKey) and not UserInputService:GetFocusedTextBox() then
                        Window:Minimize()
                    end
                end)

                function Window:Destroy()
                    if windowAnimConn then
                        windowAnimConn:Disconnect()
                        windowAnimConn = nil
                    end
                    if Window.AcrylicPaint and Window.AcrylicPaint.SetBackground then
                        Window.AcrylicPaint.SetBackground('')
                    end
                    if Library.UseAcrylic then
                        Window.AcrylicPaint.Model:Destroy()
                    end
                    if Window.ToggleScreenGui then
                        Window.ToggleScreenGui:Destroy()
                    end
                    Window.Root:Destroy()
                end
                local dialogFactory = require(ParentFolder.Dialog):Init(Window)

                function Window:Dialog(config)
                    local dialog = dialogFactory:Create()
                    dialog.Title.Text = config.Title
                    local winW, winH = Window.Size.X.Offset, Window.Size.Y.Offset
                    local minW = math.min(isMobile and 240 or 300, math.max(200, winW - 24))
                    local maxWidth = math.max(minW, math.min(620, winW - (isMobile and 28 or 120)))
                    local minH = math.min(isMobile and 126 or 165, math.max(108, winH - 20))
                    local maxHeight = math.max(minH, winH - (isMobile and 20 or 24))
                    local padX, contentTop = isMobile and 14 or 20, isMobile and 38 or 60
                    local label = New('TextLabel', {
                        FontFace = Font.new'rbxasset://fonts/families/GothamSSm.json',
                        Text = config.Content,
                        TextColor3 = Color3.fromRGB(240, 240, 240),
                        TextSize = isMobile and 12 or 14,
                        TextXAlignment = Enum.TextXAlignment.Left,
                        TextYAlignment = Enum.TextYAlignment.Top,
                        AutomaticSize = Enum.AutomaticSize.Y,
                        TextWrapped = true,
                        Size = UDim2.new(1, -(padX * 2), 0, 0),
                        Position = UDim2.fromOffset(padX, contentTop),
                        BackgroundTransparency = 1,
                        Parent = dialog.Root,
                        ClipsDescendants = false,
                        ThemeTag = {TextColor3 = 'Text'}
                    })
                    New('UISizeConstraint', {MinSize = Vector2.new(minW, minH), MaxSize = Vector2.new(maxWidth, maxHeight), Parent = dialog.Root})
                    local dialogWidth = math.clamp(label.TextBounds.X + (padX * 2), minW, maxWidth)
                    dialog.Root.Size = UDim2.fromOffset(dialogWidth, minH)
                    task.wait()
                    dialog.Root.Size = UDim2.fromOffset(dialogWidth, math.clamp(label.TextBounds.Y + (isMobile and 104 or 150), minH, maxHeight))
                    for _, btnInfo in next, config.Buttons do
                        dialog:Button(btnInfo.Title, btnInfo.Callback)
                    end
                    dialog:Open()
                    if config.Yield then
                        dialog.Closed:Wait()
                    end
                    return dialog
                end

                function Window:OpenFeedbackDialog(feedbackConfig)
                    local winW, winH = Window.Size.X.Offset, Window.Size.Y.Offset
                    local compactDlg = isMobile or winW < 610 or winH < 465
                    local availW = math.max(260, winW - (compactDlg and 24 or 210))
                    local availH = math.max(220, winH - (compactDlg and 20 or 165))
                    local minW = math.min(compactDlg and 280 or 400, availW)
                    local minH = math.min(compactDlg and 230 or 300, availH)
                    local dialog, dialogWidth, dialogHeight, isSubmitting, canClose = dialogFactory:Create(), math.clamp(availW, minW, 460), math.clamp(availH, minH, 340), false, true
                    local padX, titleY, titleSize = compactDlg and 12 or 18, compactDlg and 10 or 16, compactDlg and 15 or 18
                    local descY, descH, descSize = compactDlg and 34 or 48, compactDlg and 16 or 18, compactDlg and 11 or 12
                    local subjectY, subjectH = compactDlg and 54 or 76, compactDlg and 28 or 34
                    local bodyY, footerH, btnH = compactDlg and 88 or 120, compactDlg and 46 or 58, compactDlg and 32 or 40
                    local bodyH = compactDlg and math.max(60, dialogHeight - footerH - bodyY - 8) or 110
                    dialog.Title.Text = feedbackConfig.Title
                    dialog.Root.Size = UDim2.fromOffset(dialogWidth, dialogHeight)
                    dialog.Root.BackgroundTransparency = 0.08
                    dialog.Root.UIStroke.Color = feedbackConfig.StrokeColor
                    dialog.Root.UIStroke.Transparency = 0.2
                    dialog.Root.ClipsDescendants = true
                    dialog.Title.Position = UDim2.fromOffset(padX, titleY)
                    dialog.Title.Size = UDim2.new(1, -(padX * 2), 0, compactDlg and 20 or 24)
                    dialog.Title.TextSize = titleSize
                    New('UISizeConstraint', {MinSize = Vector2.new(minW, minH), MaxSize = Vector2.new(460, 340), Parent = dialog.Root})
                    New('Frame', {
                        Size = UDim2.fromScale(1, 1),
                        BackgroundColor3 = Color3.fromRGB(10, 13, 19),
                        BackgroundTransparency = 0.06,
                        ZIndex = 0,
                        Parent = dialog.Root
                    }, {
                        New('UICorner', {CornerRadius = UDim.new(0, 8)}),
                        New('UIGradient', {
                            Color = ColorSequence.new {
                                ColorSequenceKeypoint.new(0, Color3.fromRGB(16, 19, 28)),
                                ColorSequenceKeypoint.new(1, Color3.fromRGB(24, 17, 23))
                            },
                            Rotation = 18
                        })
                    })
                    New('TextLabel', {
                        BackgroundTransparency = 1,
                        Position = UDim2.fromOffset(padX, descY),
                        Size = UDim2.new(1, -(padX * 2), 0, descH),
                        FontFace = Font.new('rbxasset://fonts/families/GothamSSm.json', Enum.FontWeight.Medium, Enum.FontStyle.Normal),
                        Text = feedbackConfig.Description,
                        TextSize = descSize,
                        TextWrapped = true,
                        TextXAlignment = Enum.TextXAlignment.Left,
                        TextColor3 = Color3.fromRGB(209, 213, 222),
                        Parent = dialog.Root
                    })
                    local subjectBox = require(ParentFolder.Textbox)(dialog.Root, false)
                    subjectBox.Frame.Size = UDim2.new(1, -(padX * 2), 0, subjectH)
                    subjectBox.Frame.Position = UDim2.fromOffset(padX, subjectY)
                    subjectBox.Input.PlaceholderText = Creator.Translate('ScriptNamePlaceholder')
                    subjectBox.Input.ClearTextOnFocus = false
                    subjectBox.Input.Text = config.Title or ''
                    subjectBox.Input.Size = UDim2.new(1, -8, 1, 0)
                    subjectBox.Input.Position = UDim2.fromOffset(4, 0)
                    local bodyContainer = New('Frame', {
                        Size = UDim2.new(1, -(padX * 2), 0, bodyH),
                        Position = UDim2.fromOffset(padX, bodyY),
                        BackgroundTransparency = 0.08,
                        Parent = dialog.Root,
                        ThemeTag = {BackgroundColor3 = 'DialogInput'}
                    }, {
                        New('UICorner', {CornerRadius = UDim.new(0, 10)}),
                        New('UIStroke', {Transparency = 0.45, ThemeTag = {Color = 'DialogButtonBorder'}})
                    })
                    local bodyInput = New('TextBox', {
                        BackgroundTransparency = 1,
                        Position = UDim2.fromOffset(compactDlg and 8 or 12, compactDlg and 8 or 10),
                        Size = UDim2.new(1, compactDlg and -16 or -24, 1, compactDlg and -16 or -20),
                        FontFace = Font.new'rbxasset://fonts/families/GothamSSm.json',
                        Text = '',
                        PlaceholderText = feedbackConfig.PlaceholderText,
                        TextSize = compactDlg and 11 or 13,
                        ClearTextOnFocus = false,
                        MultiLine = true,
                        TextWrapped = true,
                        TextXAlignment = Enum.TextXAlignment.Left,
                        TextYAlignment = Enum.TextYAlignment.Top,
                        ThemeTag = {TextColor3 = 'Text', PlaceholderColor3 = 'SubText'},
                        Parent = bodyContainer
                    })
                    dialog.ButtonHolderFrame.BackgroundTransparency = 1
                    dialog.ButtonHolderFrame.Frame.BackgroundColor3 = feedbackConfig.StrokeColor
                    dialog.ButtonHolderFrame.Frame.BackgroundTransparency = 0.9
                    dialog.ButtonHolderFrame.Size = UDim2.new(1, 0, 0, footerH)
                    dialog.ButtonHolderFrame.Position = UDim2.new(0, 0, 1, -footerH)
                    dialog.ButtonHolder.Size = UDim2.new(1, -(padX * 2), 0, btnH)
                    dialog.ButtonHolder.Position = UDim2.fromScale(0.5, 0.5)
                    local sendBtn, cancelBtn = Button('', dialog.ButtonHolder, true), Button('', dialog.ButtonHolder, true)
                    sendBtn.Title.Text = Creator.Translate('Send')
                    cancelBtn.Title.Text = Creator.Translate('Cancel')
                    for _, btnObj in next, {sendBtn, cancelBtn} do
                        btnObj.Frame.Size = UDim2.new(0.5, -5, 0, btnH)
                        btnObj.Frame.UICorner.CornerRadius = UDim.new(0, compactDlg and 8 or 10)
                        btnObj.Frame.UIStroke.Transparency = 0.28
                        btnObj.Title.TextSize = compactDlg and 11 or 12
                    end
                    sendBtn.Frame.BackgroundTransparency = 0
                    sendBtn.Frame.BackgroundColor3 = feedbackConfig.ButtonColor
                    sendBtn.Frame.UIStroke.Color = feedbackConfig.StrokeColor
                    sendBtn.Title.TextColor3 = feedbackConfig.ButtonTextColor
                    sendBtn.HoverFrame.BackgroundTransparency = 1
                    cancelBtn.Frame.BackgroundColor3 = Color3.fromRGB(38, 44, 56)
                    cancelBtn.Frame.BackgroundTransparency = 0.14
                    cancelBtn.Frame.UIStroke.Color = Color3.fromRGB(145, 153, 166)
                    cancelBtn.Title.TextColor3 = Color3.fromRGB(215, 220, 230)
                    cancelBtn.HoverFrame.BackgroundTransparency = 1

                    local function setSubmitting(busy)
                        isSubmitting = busy
                        sendBtn.Title.Text = busy and Creator.Translate('Sending') or Creator.Translate('Send')
                        sendBtn.Frame.Active = not busy
                        cancelBtn.Frame.Active = not busy
                        sendBtn.Frame.AutoButtonColor = false
                        cancelBtn.Frame.AutoButtonColor = false
                        sendBtn.Frame.BackgroundTransparency = busy and 0.12 or 0
                        cancelBtn.Frame.BackgroundTransparency = busy and 0.3 or 0.14
                    end
                    Creator.AddSignal(sendBtn.Frame.MouseButton1Click, function()
                        if isSubmitting then
                            return
                        end
                        local subjectText, bodyText = trim(subjectBox.Input.Text), trim(bodyInput.Text)
                        if subjectText == '' or bodyText == '' then
                            Library:Notify {
                                Title = feedbackConfig.TypeName,
                                Content = Creator.Translate('FillBothFields'),
                                Duration = 4
                            }
                            return
                        end
                        setSubmitting(true)
                        task.spawn(function()
                            local sentOk, errMsg = sendWebhook(feedbackConfig.TypeName, feedbackConfig.WebhookUrl, subjectText, bodyText)
                            task.defer(function()
                                if canClose then
                                    setSubmitting(false)
                                end
                                Library:Notify {
                                    Title = feedbackConfig.TypeName,
                                    Content = sentOk and string.format(Creator.Translate('SentSuccess'), feedbackConfig.TypeName) or (errMsg or string.format(Creator.Translate('SentFailed'), string.lower(feedbackConfig.TypeName))),
                                    Duration = 4
                                }
                                if sentOk and canClose then
                                    bodyInput.Text = ''
                                end
                            end)
                        end)
                    end)
                    Creator.AddSignal(cancelBtn.Frame.MouseButton1Click, function()
                        if isSubmitting then
                            return
                        end
                        canClose = false
                        dialog:Close()
                    end)
                    dialog:Open()
                end
                Creator.AddSignal(Window.PlayerVisibilityToggle.MouseButton1Click, function()
                    dismissPlayerCard()
                end)
                Creator.AddSignal(Window.PlayerDismissButton.MouseButton1Click, function()
                    dismissPlayerCard()
                end)
                Creator.AddSignal(Window.PlayerCardButton.MouseEnter, function()
                    applyCardState'hover'
                end)
                Creator.AddSignal(Window.PlayerCardButton.MouseLeave, function()
                    applyCardState'default'
                end)
                Creator.AddSignal(Window.PlayerCardButton.MouseButton1Down, function()
                    applyCardState'pressed'
                end)
                Creator.AddSignal(Window.PlayerCardButton.MouseButton1Up, function()
                    applyCardState'hover'
                end)

                local function openProfileModal()
                    local absW = (Window.Root and Window.Root.AbsoluteSize.X > 0) and Window.Root.AbsoluteSize.X or Window.Size.X.Offset
                    local absH = (Window.Root and Window.Root.AbsoluteSize.Y > 0) and Window.Root.AbsoluteSize.Y or Window.Size.Y.Offset
                    local winW, winH = math.floor(absW), math.floor(absH)
                    local compactLayout = isMobile or winW < 560 or winH < 410
                    local modalWidth = math.clamp(winW - (compactLayout and 20 or 160), math.min(280, math.max(240, winW - 12)), 500)
                    local modalHeight = math.clamp(winH - (compactLayout and 18 or 140), math.min(276, math.max(240, winH - 12)), 380)
                    local outerPad = compactLayout and 10 or 16
                    local headerTop = compactLayout and 34 or 48
                    local heroHeight = compactLayout and 48 or 64
                    local footerHeight = compactLayout and 40 or 52
                    local btnHeight = compactLayout and 28 or 34
                    local sectionGap = compactLayout and 5 or 8
                    local discordBarH = compactLayout and 26 or 32
                    local bodyTop = headerTop + heroHeight + sectionGap
                    local bodyAvail = math.max(96, modalHeight - footerHeight - bodyTop - sectionGap)
                    local gridGap = compactLayout and 5 or 6
                    local tileH = math.clamp(math.floor((bodyAvail - discordBarH - sectionGap - (gridGap * 2)) / 3), 28, 48)
                    local gridH = (tileH * 3) + (gridGap * 2)
                    local discordBarTop = bodyTop + gridH + sectionGap

                    local dialog = dialogFactory:Create()
                    dialog.Title.Text = Creator.Translate('ProfileDetails')
                    dialog.Root.Size = UDim2.fromOffset(modalWidth, modalHeight)
                    dialog.Root.BackgroundTransparency = 0.06
                    dialog.Root.UIStroke.Color = Color3.fromRGB(70, 78, 92)
                    dialog.Root.UIStroke.Transparency = 0.35
                    dialog.Root.ClipsDescendants = true
                    dialog.Title.Position = UDim2.fromOffset(outerPad, compactLayout and 10 or 14)
                    dialog.Title.Size = UDim2.new(1, -(outerPad * 2), 0, compactLayout and 20 or 24)
                    dialog.Title.TextSize = compactLayout and 14 or 16
                    New('UISizeConstraint', {MinSize = Vector2.new(math.min(280, modalWidth), math.min(250, modalHeight)), MaxSize = Vector2.new(520, 400), Parent = dialog.Root})
                    New('Frame', {
                        Size = UDim2.fromScale(1, 1),
                        BackgroundColor3 = Color3.fromRGB(16, 18, 24),
                        BackgroundTransparency = 0.06,
                        ZIndex = 0,
                        Parent = dialog.Root
                    }, {
                        New('UICorner', {CornerRadius = UDim.new(0, 10)})
                    })

                    -- Header card: Avatar + Name + Username + Executor tag
                    local heroCard = New('Frame', {
                        Size = UDim2.new(1, -(outerPad * 2), 0, heroHeight),
                        Position = UDim2.fromOffset(outerPad, headerTop),
