                        BackgroundTransparency = 0.15,
                        Parent = dialog.Root
                    }, {
                        New('UICorner', {CornerRadius = UDim.new(0, 10)}),
                        New('UIStroke', {Color = Color3.fromRGB(58, 66, 80), Transparency = 0.45, Thickness = 1})
                    })
                    local avatarPx = compactLayout and 36 or 44
                    local avatarWrap = New('Frame', {
                        AnchorPoint = Vector2.new(0, 0.5),
                        Size = UDim2.fromOffset(avatarPx, avatarPx),
                        Position = UDim2.new(0, compactLayout and 8 or 12, 0.5, 0),
                        BackgroundColor3 = Color3.fromRGB(32, 36, 46),
                        Parent = heroCard
                    }, {
                        New('UICorner', {CornerRadius = UDim.new(1, 0)}),
                        New('UIStroke', {Color = Color3.fromRGB(82, 92, 110), Transparency = 0.35, Thickness = 1})
                    })
                    New('ImageLabel', {
                        Size = UDim2.fromScale(1, 1),
                        BackgroundTransparency = 1,
                        Image = Window.PlayerAvatar.Image,
                        ScaleType = Enum.ScaleType.Crop,
                        Parent = avatarWrap
                    }, {New('UICorner', {CornerRadius = UDim.new(1, 0)})})
                    New('Frame', {
                        AnchorPoint = Vector2.new(1, 1),
                        Position = UDim2.new(1, 0, 1, 0),
                        Size = UDim2.fromOffset(compactLayout and 9 or 11, compactLayout and 9 or 11),
                        BackgroundColor3 = Color3.fromRGB(67, 181, 129),
                        Parent = avatarWrap
                    }, {
                        New('UICorner', {CornerRadius = UDim.new(1, 0)}),
                        New('UIStroke', {Color = Color3.fromRGB(24, 27, 35), Thickness = 2})
                    })

                    local textLeft = (compactLayout and 8 or 12) + avatarPx + (compactLayout and 10 or 12)
                    local userHandle = LocalPlayer and ('@' .. LocalPlayer.Name) or Creator.Translate('UnavailableText')
                    local userIdNum = LocalPlayer and tostring(LocalPlayer.UserId) or '0'
                    local accountAgeNum = LocalPlayer and tonumber(LocalPlayer.AccountAge) or 0
                    local executorName = getExecutorName()

                    New('TextLabel', {
                        BackgroundTransparency = 1,
                        Position = UDim2.fromOffset(textLeft, compactLayout and 8 or 11),
                        Size = UDim2.new(1, -(textLeft + (compactLayout and 76 or 106)), 0, compactLayout and 18 or 22),
                        FontFace = Font.new('rbxasset://fonts/families/GothamSSm.json', Enum.FontWeight.Bold, Enum.FontStyle.Normal),
                        Text = displayName,
                        TextSize = compactLayout and 13 or 15,
                        TextXAlignment = Enum.TextXAlignment.Left,
                        TextColor3 = Color3.fromRGB(244, 246, 250),
                        TextTruncate = Enum.TextTruncate.AtEnd,
                        Parent = heroCard
                    })
                    New('TextLabel', {
                        BackgroundTransparency = 1,
                        Position = UDim2.fromOffset(textLeft, compactLayout and 27 or 34),
                        Size = UDim2.new(1, -(textLeft + (compactLayout and 76 or 106)), 0, compactLayout and 14 or 16),
                        FontFace = Font.new('rbxasset://fonts/families/GothamSSm.json', Enum.FontWeight.Medium, Enum.FontStyle.Normal),
                        Text = `{userHandle}  •  ID {userIdNum}`,
                        TextSize = compactLayout and 10 or 11,
                        TextXAlignment = Enum.TextXAlignment.Left,
                        TextColor3 = Color3.fromRGB(152, 160, 174),
                        TextTruncate = Enum.TextTruncate.AtEnd,
                        Parent = heroCard
                    })

                    local execBadge = New('Frame', {
                        AnchorPoint = Vector2.new(1, 0.5),
                        Position = UDim2.new(1, compactLayout and -8 or -12, 0.5, 0),
                        AutomaticSize = Enum.AutomaticSize.X,
                        Size = UDim2.fromOffset(0, compactLayout and 22 or 24),
                        BackgroundColor3 = Color3.fromRGB(34, 39, 50),
                        Parent = heroCard
                    }, {
                        New('UICorner', {CornerRadius = UDim.new(1, 0)}),
                        New('UIStroke', {Color = Color3.fromRGB(72, 82, 98), Transparency = 0.4, Thickness = 1}),
                        New('UIPadding', {PaddingLeft = UDim.new(0, 9), PaddingRight = UDim.new(0, 9)}),
                        New('TextLabel', {
                            BackgroundTransparency = 1,
                            AutomaticSize = Enum.AutomaticSize.X,
                            Size = UDim2.fromScale(0, 1),
                            FontFace = Font.new('rbxasset://fonts/families/GothamSSm.json', Enum.FontWeight.SemiBold, Enum.FontStyle.Normal),
                            Text = executorName,
                            TextSize = compactLayout and 10 or 11,
                            TextColor3 = Color3.fromRGB(215, 222, 234)
                        })
                    })

                    -- 2x3 Player & Telemetry Info Grid
                    local statsGrid = New('Frame', {
                        Position = UDim2.fromOffset(outerPad, bodyTop),
                        Size = UDim2.new(1, -(outerPad * 2), 0, gridH),
                        BackgroundTransparency = 1,
                        ClipsDescendants = true,
                        Parent = dialog.Root
                    }, {
                        New('UIGridLayout', {
                            CellSize = UDim2.new(0.5, -(math.ceil(gridGap / 2) + 1), 0, tileH),
                            CellPadding = UDim2.fromOffset(gridGap, gridGap),
                            FillDirectionMaxCells = 2,
                            SortOrder = Enum.SortOrder.LayoutOrder
                        })
                    })

                    local function createStatTile(order, iconName, labelText, valueText, valueColor, onClick)
                        local tile = New('TextButton', {
                            LayoutOrder = order,
                            AutoButtonColor = false,
                            Text = '',
                            BackgroundColor3 = Color3.fromRGB(22, 25, 33),
                            BackgroundTransparency = 0.12,
                            ClipsDescendants = true,
                            Parent = statsGrid
                        }, {
                            New('UICorner', {CornerRadius = UDim.new(0, 8)}),
                            New('UIStroke', {Color = Color3.fromRGB(52, 59, 72), Transparency = 0.48, Thickness = 1})
                        })
                        local tightTile = tileH <= 32
                        local iconLbl = New('ImageLabel', {
                            Position = UDim2.fromOffset(compactLayout and 8 or 10, tightTile and 4 or (compactLayout and 5 or 7)),
                            Size = UDim2.fromOffset(12, 12),
                            BackgroundTransparency = 1,
                            ImageColor3 = Color3.fromRGB(145, 155, 172),
                            Parent = tile
                        })
                        Library.Utilities.Icons:SetIcon(iconLbl, iconName)
                        New('TextLabel', {
                            BackgroundTransparency = 1,
                            Position = UDim2.fromOffset(compactLayout and 24 or 26, tightTile and 3 or (compactLayout and 4 or 6)),
                            Size = UDim2.new(1, -(compactLayout and 30 or 34), 0, 14),
                            FontFace = Font.new('rbxasset://fonts/families/GothamSSm.json', Enum.FontWeight.Medium, Enum.FontStyle.Normal),
                            Text = labelText,
                            TextSize = compactLayout and 9 or 10,
                            TextXAlignment = Enum.TextXAlignment.Left,
                            TextColor3 = Color3.fromRGB(142, 150, 165),
                            TextTruncate = Enum.TextTruncate.AtEnd,
                            Parent = tile
                        })
                        local valLbl = New('TextLabel', {
                            BackgroundTransparency = 1,
                            Position = UDim2.fromOffset(compactLayout and 8 or 10, tightTile and 14 or (compactLayout and 17 or 21)),
                            Size = UDim2.new(1, -(compactLayout and 16 or 20), 0, tightTile and 15 or (compactLayout and 16 or 19)),
                            FontFace = Font.new('rbxasset://fonts/families/GothamSSm.json', Enum.FontWeight.SemiBold, Enum.FontStyle.Normal),
                            Text = valueText,
                            TextSize = tightTile and 11 or (compactLayout and 11 or 13),
                            TextXAlignment = Enum.TextXAlignment.Left,
                            TextColor3 = valueColor or Color3.fromRGB(238, 242, 248),
                            TextTruncate = Enum.TextTruncate.AtEnd,
                            Parent = tile
                        })
                        if onClick then
                            Creator.AddSignal(tile.MouseEnter, function()
                                TweenService:Create(tile, TweenInfo.new(0.15, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {BackgroundColor3 = Color3.fromRGB(30, 34, 45)}):Play()
                            end)
                            Creator.AddSignal(tile.MouseLeave, function()
                                TweenService:Create(tile, TweenInfo.new(0.15, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {BackgroundColor3 = Color3.fromRGB(22, 25, 33)}):Play()
                            end)
                            Creator.AddSignal(tile.MouseButton1Click, onClick)
                        end
                        return valLbl
                    end

                    local function readPingMs()
                        local ok, val = pcall(function()
                            return Stats.Network.ServerStatsItem['Data Ping']:GetValue()
                        end)
                        if ok and typeof(val) == 'number' then
                            return math.max(0, math.floor(val + 0.5))
                        end
                        return nil
                    end

                    createStatTile(1, 'user', Creator.Translate('StatDisplayName'), displayName)
                    createStatTile(2, 'at-sign', Creator.Translate('StatUsername'), userHandle, nil, function()
                        if copyToClipboard(LocalPlayer and LocalPlayer.Name or '') then
                            Library:Notify {Title = Creator.Translate('StatUsername'), Content = `{Creator.Translate('CopiedPrefix')}: {userHandle}`, Duration = 2.5}
                        end
                    end)
                    createStatTile(3, 'hash', Creator.Translate('StatUserId'), userIdNum, nil, function()
                        if copyToClipboard(userIdNum) then
                            Library:Notify {Title = Creator.Translate('StatUserId'), Content = `{Creator.Translate('CopiedPrefix')}: {userIdNum}`, Duration = 2.5}
                        end
                    end)
                    createStatTile(4, 'calendar', Creator.Translate('StatAccountAge'), `{Creator.FormatNumber(accountAgeNum)} {Creator.Translate('StatDaysSuffix')}`)

                    local initPing = readPingMs()
                    local fpsValueLbl = createStatTile(5, 'gauge', Creator.Translate('StatFps'), '-- FPS', Color3.fromRGB(87, 214, 141))
                    local pingValueLbl = createStatTile(6, 'wifi', Creator.Translate('StatPing'), initPing and (`{initPing} ms`) or '-- ms', Color3.fromRGB(115, 200, 255))

                    -- Live FPS & Ping updater while dialog is open
                    local frameCount, elapsedWindow = 0, 0
                    local telemetryConn = RunService.RenderStepped:Connect(function(dt)
                        if not dialog.Root or not dialog.Root.Parent then
                            return
                        end
                        frameCount += 1
                        elapsedWindow += dt
                        if elapsedWindow >= 0.35 then
                            local fps = math.max(1, math.floor((frameCount / elapsedWindow) + 0.5))
                            frameCount, elapsedWindow = 0, 0
                            fpsValueLbl.Text = `{fps} FPS`
                            fpsValueLbl.TextColor3 = fps >= 55 and Color3.fromRGB(87, 214, 141) or (fps >= 30 and Color3.fromRGB(245, 190, 75) or Color3.fromRGB(240, 95, 95))
                            local ping = readPingMs()
                            if ping then
                                pingValueLbl.Text = `{ping} ms`
                                pingValueLbl.TextColor3 = ping <= 95 and Color3.fromRGB(87, 214, 141) or (ping <= 180 and Color3.fromRGB(245, 190, 75) or Color3.fromRGB(240, 95, 95))
                            end
                        end
                    end)
                    dialog.Closing:Connect(function()
                        if telemetryConn then
                            telemetryConn:Disconnect()
                            telemetryConn = nil
                        end
                    end)

                    -- Slim clickable Discord Live Strip
                    local cachedStats = Creator.DiscordCache and Creator.DiscordCache[discordInviteCode]
                    local function formatDiscordBarStats(info)
                        if info and info.members then
                            return `{Creator.FormatNumber(info.online)} {Creator.Translate('DiscordOnlineWord')}  •  {Creator.FormatNumber(info.members)} {Creator.Translate('DiscordMembersWord')}`
                        end
                        return `...`
                    end

                    local discordBar = New('TextButton', {
                        Position = UDim2.fromOffset(outerPad, discordBarTop),
                        Size = UDim2.new(1, -(outerPad * 2), 0, discordBarH),
                        AutoButtonColor = false,
                        Text = '',
                        BackgroundColor3 = Color3.fromRGB(24, 28, 38),
                        BackgroundTransparency = 0.1,
                        Parent = dialog.Root
                    }, {
                        New('UICorner', {CornerRadius = UDim.new(0, 8)}),
                        New('UIStroke', {Color = Color3.fromRGB(64, 74, 96), Transparency = 0.4, Thickness = 1})
                    })
                    New('Frame', {
                        AnchorPoint = Vector2.new(0, 0.5),
                        Position = UDim2.new(0, compactLayout and 10 or 12, 0.5, 0),
                        Size = UDim2.fromOffset(8, 8),
                        BackgroundColor3 = Color3.fromRGB(67, 181, 129),
                        Parent = discordBar
                    }, {New('UICorner', {CornerRadius = UDim.new(1, 0)})})
                    New('TextLabel', {
                        BackgroundTransparency = 1,
                        Position = UDim2.fromOffset(compactLayout and 24 or 28, 0),
                        Size = UDim2.new(0.45, -(compactLayout and 24 or 28), 1, 0),
                        FontFace = Font.new('rbxasset://fonts/families/GothamSSm.json', Enum.FontWeight.SemiBold, Enum.FontStyle.Normal),
                        Text = discordInvite,
                        TextSize = compactLayout and 10 or 12,
                        TextXAlignment = Enum.TextXAlignment.Left,
                        TextColor3 = Color3.fromRGB(142, 162, 255),
                        TextTruncate = Enum.TextTruncate.AtEnd,
                        Parent = discordBar
                    })
                    local modalDiscordCountLbl = New('TextLabel', {
                        BackgroundTransparency = 1,
                        AnchorPoint = Vector2.new(1, 0),
                        Position = UDim2.new(1, compactLayout and -10 or -12, 0, 0),
                        Size = UDim2.new(0.55, -(compactLayout and 12 or 16), 1, 0),
                        FontFace = Font.new('rbxasset://fonts/families/GothamSSm.json', Enum.FontWeight.Medium, Enum.FontStyle.Normal),
                        Text = formatDiscordBarStats(cachedStats),
                        TextSize = compactLayout and 9 or 11,
                        TextXAlignment = Enum.TextXAlignment.Right,
                        TextColor3 = Color3.fromRGB(184, 194, 210),
                        TextTruncate = Enum.TextTruncate.AtEnd,
                        Parent = discordBar
                    })
                    Creator.AddSignal(discordBar.MouseEnter, function()
                        TweenService:Create(discordBar, TweenInfo.new(0.15, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {BackgroundColor3 = Color3.fromRGB(32, 37, 52)}):Play()
                    end)
                    Creator.AddSignal(discordBar.MouseLeave, function()
                        TweenService:Create(discordBar, TweenInfo.new(0.15, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {BackgroundColor3 = Color3.fromRGB(24, 28, 38)}):Play()
                    end)
                    Creator.AddSignal(discordBar.MouseButton1Click, joinAndCopyDiscord)
                    task.spawn(function()
                        local fresh = Creator.FetchDiscordInviteStats(discordInviteCode)
                        if fresh and modalDiscordCountLbl.Parent then
                            modalDiscordCountLbl.Text = formatDiscordBarStats(fresh)
                        end
                    end)

                    -- Footer
                    dialog.ButtonHolderFrame.BackgroundTransparency = 1
                    dialog.ButtonHolderFrame.Frame.BackgroundColor3 = Color3.fromRGB(52, 58, 70)
                    dialog.ButtonHolderFrame.Frame.BackgroundTransparency = 0.5
                    dialog.ButtonHolderFrame.Size = UDim2.new(1, 0, 0, footerHeight)
                    dialog.ButtonHolderFrame.Position = UDim2.new(0, 0, 1, -footerHeight)
                    dialog.ButtonHolder.Size = UDim2.new(1, -(outerPad * 2), 0, btnHeight)
                    dialog.ButtonHolder.Position = UDim2.fromScale(0.5, 0.5)
                    local joinBtn, closeBtn = dialog:Button(Creator.Translate('JoinDiscordBtn'), function()
                        joinAndCopyDiscord()
                    end), dialog:Button(Creator.Translate('Close'), function() end)
                    for _, btnObj in next, {joinBtn, closeBtn} do
                        btnObj.Frame.Size = UDim2.new(0.5, -5, 0, btnHeight)
                        btnObj.Frame.UICorner.CornerRadius = UDim.new(0, 8)
                        btnObj.Frame.UIStroke.Transparency = 0.45
                        btnObj.Title.TextSize = compactLayout and 11 or 12
                        btnObj.Title.TextXAlignment = Enum.TextXAlignment.Left
                        btnObj.Title.Size = UDim2.new(1, -(compactLayout and 34 or 38), 1, 0)
                        btnObj.Title.Position = UDim2.fromOffset(compactLayout and 28 or 32, 0)
                    end
                    joinBtn.Frame.BackgroundTransparency = 0
                    joinBtn.Frame.BackgroundColor3 = Color3.fromRGB(88, 101, 242)
                    joinBtn.Frame.UIStroke.Color = Color3.fromRGB(122, 134, 255)
                    joinBtn.Title.TextColor3 = Color3.fromRGB(255, 255, 255)
                    joinBtn.HoverFrame.BackgroundTransparency = 1
                    closeBtn.Frame.BackgroundColor3 = Color3.fromRGB(32, 36, 46)
                    closeBtn.Frame.BackgroundTransparency = 0.12
                    closeBtn.Frame.UIStroke.Color = Color3.fromRGB(72, 80, 96)
                    closeBtn.Title.TextColor3 = Color3.fromRGB(215, 220, 232)
                    closeBtn.HoverFrame.BackgroundTransparency = 1

                    local joinIcon = New('ImageLabel', {
                        AnchorPoint = Vector2.new(0, 0.5),
                        Position = UDim2.new(0, compactLayout and 9 or 11, 0.5, 0),
                        Size = UDim2.fromOffset(compactLayout and 13 or 15, compactLayout and 13 or 15),
                        BackgroundTransparency = 1,
                        ImageColor3 = Color3.fromRGB(255, 255, 255),
                        Parent = joinBtn.Frame
                    })
                    Library.Utilities.Icons:SetIcon(joinIcon, 'link')
                    local closeIcon = New('ImageLabel', {
                        AnchorPoint = Vector2.new(0, 0.5),
                        Position = UDim2.new(0, compactLayout and 9 or 11, 0.5, 0),
                        Size = UDim2.fromOffset(compactLayout and 13 or 15, compactLayout and 13 or 15),
                        BackgroundTransparency = 1,
                        ImageColor3 = Color3.fromRGB(180, 188, 204),
                        Parent = closeBtn.Frame
                    })
                    Library.Utilities.Icons:SetIcon(closeIcon, 'x')
                    dialog:Open()
                end
                Creator.AddSignal(Window.ProfileButton.MouseEnter, function()
                    TweenService:Create(Window.ProfileButton, TweenInfo.new(0.18, Enum.EasingStyle.Quint, Enum.EasingDirection.Out), {BackgroundTransparency = 0.02}):Play()
                end)
                Creator.AddSignal(Window.ProfileButton.MouseLeave, function()
                    TweenService:Create(Window.ProfileButton, TweenInfo.new(0.18, Enum.EasingStyle.Quint, Enum.EasingDirection.Out), {BackgroundTransparency = 0.1}):Play()
                end)
                Creator.AddSignal(Window.ProfileButton.MouseButton1Click, openProfileModal)
                Creator.AddSignal(Window.PlayerCardButton.MouseButton1Click, openProfileModal)
                Window.SidebarContainer = sidebarContainer
                Window.ContentPanel = contentPanel
                Window.BackgroundState = {
                    Image = '',
                    Media = nil,
                    Source = '',
                    ScaleMode = 'Crop',
                    ImageTransparency = 0,
                    OverlayTransparency = 0.78,
                    MenuTransparency = 0
                }

                local function applyBackgroundState()
                    local state = Window.BackgroundState
                    local scaleMap = {
                        Crop = Enum.ScaleType.Crop,
                        Fit = Enum.ScaleType.Fit,
                        Tile = Enum.ScaleType.Tile,
                        Stretch = Enum.ScaleType.Stretch
                    }
                    local scaleEnum = scaleMap[state.ScaleMode] or Enum.ScaleType.Crop
                    local menuFade = math.clamp(tonumber(state.MenuTransparency) or 0, 0, 0.9)
                    if state.Image ~= '' then
                        local imgAlpha = math.clamp(state.ImageTransparency + menuFade * (1 - state.ImageTransparency), 0, 1)
                        Window.AcrylicPaint.SetBackground(state.Media or state.Image, scaleEnum, imgAlpha)
                        Window.AcrylicPaint.CustomBackground.ResampleMode = Enum.ResamplerMode.Default
                        Window.AcrylicPaint.CustomBackground.ImageColor3 = Color3.fromRGB(255, 255, 255)
                        local baseOverlay = math.clamp(state.OverlayTransparency, 0.05, 1)
                        local overlay = math.clamp(baseOverlay + menuFade * (1 - baseOverlay), 0.05, 1)
                        Window.AcrylicPaint.Frame.BackgroundTransparency = 1
                        Window.AcrylicPaint.SetOverlayAlpha(overlay)
                        local sideBase = math.clamp(0.20 + baseOverlay * 0.80, 0.2, 1)
                        local contentBase = math.clamp(0.16 + baseOverlay * 0.84, 0.16, 1)
                        sidebarContainer.BackgroundTransparency = math.clamp(sideBase + menuFade * (1 - sideBase), 0.16, 1)
                        contentPanel.BackgroundTransparency = math.clamp(contentBase + menuFade * (1 - contentBase), 0.08, 1)
                    else
                        Window.AcrylicPaint.Frame.BackgroundTransparency = math.clamp(0.9 + menuFade * 0.1, 0.9, 1)
                        Window.AcrylicPaint.SetBackground('', Enum.ScaleType.Crop, 0)
                        if menuFade > 0 then
                            Window.AcrylicPaint.SetOverlayAlpha(math.clamp(0.45 + menuFade * 0.53, 0.45, 0.98))
                        else
                            Window.AcrylicPaint.SetOverlayAlpha(nil)
                        end
                        sidebarContainer.BackgroundTransparency = math.clamp(0.16 + menuFade * 0.84, 0.16, 0.97)
                        contentPanel.BackgroundTransparency = math.clamp(0.08 + menuFade * 0.92, 0.08, 0.97)
                    end
                end

                function Window:SetWindowTransparency(alpha, skipSave)
                    if typeof(alpha) == 'number' then
                        Window.BackgroundState.MenuTransparency = math.clamp(alpha, 0, 0.85)
                        applyBackgroundState()
                        if not skipSave then
                            Creator.SaveSettings({WindowTransparency = Window.BackgroundState.MenuTransparency})
                        end
                    end
                end

                function Window:SetTransparency(alpha, skipSave)
                    Window:SetWindowTransparency(alpha, skipSave)
                end

                function Window:SetBackgroundScale(mode, skipSave)
                    if typeof(mode) == 'string' then
                        Window.BackgroundState.ScaleMode = mode
                        applyBackgroundState()
                        if not skipSave then
                            Creator.SaveSettings({BackgroundScaleMode = mode})
                        end
                    end
                end

                function Window:SetBackgroundTransparency(alpha, skipSave)
                    if typeof(alpha) == 'number' then
                        Window.BackgroundState.ImageTransparency = math.clamp(alpha, 0, 1)
                        applyBackgroundState()
                        if not skipSave then
                            Creator.SaveSettings({BackgroundTransparency = Window.BackgroundState.ImageTransparency})
                        end
                    end
                end

                function Window:SetBackgroundOverlay(alpha, skipSave)
                    if typeof(alpha) == 'number' then
                        Window.BackgroundState.OverlayTransparency = math.clamp(alpha, 0.05, 1)
                        applyBackgroundState()
                        if not skipSave then
                            Creator.SaveSettings({BackgroundOverlay = Window.BackgroundState.OverlayTransparency})
                        end
                    end
                end

                local bgRequestSeq = 0

                function Window:ResetBackground(silent, skipSave)
                    bgRequestSeq += 1
                    Window.BackgroundState.Source = ''
                    Window.BackgroundState.Image = ''
                    Window.BackgroundState.Media = nil
                    applyBackgroundState()
                    if not skipSave then
                        Creator.SaveSettings({BackgroundSource = ''})
                    end
                    if not silent then
                        Library:Notify {
                            Title = Creator.Translate('SettingsBackgroundSection'),
                            Content = Creator.Translate('SettingsBgCleared'),
                            Duration = 3
                        }
                    end
                end

                function Window:SetBackgroundImage(source, opts)
                    opts = typeof(opts) == 'table' and opts or {}
                    if opts.ScaleMode then
                        Window.BackgroundState.ScaleMode = opts.ScaleMode
                    end
                    if typeof(opts.Transparency) == 'number' then
                        Window.BackgroundState.ImageTransparency = math.clamp(opts.Transparency, 0, 1)
                    end
                    if typeof(opts.Overlay) == 'number' then
                        Window.BackgroundState.OverlayTransparency = math.clamp(opts.Overlay, 0.05, 1)
                    end
                    local trimmed = trim(source)
                    if trimmed == '' then
                        Window:ResetBackground(opts.Silent, opts.SkipSave)
                        return
                    end
                    bgRequestSeq += 1
                    local mySeq = bgRequestSeq
                    Window.BackgroundState.Source = trimmed
                    local isHttp = trimmed:match('^https?://') ~= nil
                    if isHttp and not opts.Silent then
                        Library:Notify {
                            Title = Creator.Translate('SettingsBackgroundSection'),
                            Content = Creator.Translate('SettingsBgDownloading'),
                            Duration = 2
                        }
                    end
                    task.spawn(function()
                        local ok, resolved = Creator.ResolveMediaAsset(trimmed, 'rezhub_bg')
                        if mySeq ~= bgRequestSeq then
                            return
                        end
                        if ok and typeof(resolved) == 'table' then
                            Window.BackgroundState.Media = resolved
                            Window.BackgroundState.Image = (resolved.uri and resolved.uri ~= '' and resolved.uri) or trimmed
                            applyBackgroundState()
                            if Window._bgListListeners then
                                for _, fn in next, Window._bgListListeners do
                                    task.spawn(fn)
                                end
                            end
                            if not opts.SkipSave then
                                Creator.SaveSettings({
                                    BackgroundSource = trimmed,
                                    BackgroundScaleMode = Window.BackgroundState.ScaleMode,
                                    BackgroundTransparency = Window.BackgroundState.ImageTransparency,
                                    BackgroundOverlay = Window.BackgroundState.OverlayTransparency
                                })
                            end
                            if not opts.Silent then
                                Library:Notify {
                                    Title = Creator.Translate('SettingsBackgroundSection'),
                                    Content = Creator.Translate('SettingsBgApplied'),
                                    Duration = 3
                                }
                            end
                        elseif not opts.Silent then
                            Library:Notify {
                                Title = Creator.Translate('SettingsBackgroundSection'),
                                Content = resolved or Creator.Translate('SettingsBgInvalid'),
                                Duration = 4
                            }
                        end
                    end)
                end

                local tabManager, fadeTime, tabSwitchTime = require(ParentFolder.Tab):Init(Window), 0.15, 0
                Window.TabManager = tabManager
                Creator.AddSignal(Window.SearchBox.Input:GetPropertyChangedSignal'Text', function()
                    tabSwitchTime += 1
                    local lastTabSwitch = tabSwitchTime
                    task.delay(fadeTime, function()
                        if lastTabSwitch ~= tabSwitchTime then
                            return
                        end
                        tabManager:ApplySearch(Window.SearchBox.Input.Text)
                    end)
                end)

                function Window:Tab(config)
                    return tabManager:New(config.Title, config.Icon, Window.TabHolder, config)
                end

                function Window:AddTab(config)
                    return Window:Tab(config)
                end

                function Window:CreateTab(config)
                    return Window:Tab(config)
                end

                function Window:SelectTab(tabIndex)
                    tabManager:SelectTab(tabIndex)
                end
                Creator.AddSignal(Window.TabHolder:GetPropertyChangedSignal'CanvasPosition', function()
                    lastScrollY = tabManager:GetCurrentTabPos() + tabHalfH
                    lastTick = 0
                    Window.SelectorPosMotor:setGoal(Instant(tabManager:GetCurrentTabPos()))
                end)
                return Window
            end
        end)()
    end,

    -- ========================================================================
    -- [Module 13]: Fluent Renewed/Elements
    -- ========================================================================
    [13] = function()
        local env, script, require = waxGetEnv(13)
        return (function(...)
            local Root = script.Parent
            local Creator, Layout = require(Root.Modules.Creator), require(Root.Modules.Layout)
            local New = Creator.New
            local TweenService = game:GetService('TweenService')
            local Elements = {}
            for _, value in next, script:GetChildren() do
                Elements[#Elements + 1] = require(value)
            end

            local Banner = {}
            Banner.__index = Banner
            Banner.__type = 'Banner'

            function Banner:New(idOrConfig, maybeConfig)
                local library = self.Library
                local id = typeof(idOrConfig) == 'string' and idOrConfig or nil
                local config = typeof(idOrConfig) == 'table' and idOrConfig or maybeConfig
                assert(typeof(config) == 'table', 'Banner - Missing config table')
                config.Title = config.Title or ''
                local descText = config.Description ~= nil and config.Description or (config.Content or '')
                local isMob = Layout.IsMobile
                local avSize = tonumber(config.AvatarSize) or (isMob and 54 or 64)
                local avCornerRadius = config.AvatarCorner == 'Circle' and UDim.new(1, 0) or UDim.new(0, tonumber(config.AvatarCorner) or 16)
                local rawBannerH = config.BannerHeight ~= nil and tonumber(config.BannerHeight) or (isMob and 96 or 124)
                local bannerH = math.max(0, rawBannerH or 0)
                local showBanner = bannerH > 0 and not config.HideBanner
                local showAvatar = config.Avatar ~= nil or config.AvatarFallback ~= nil

                local cardFrame = New('TextButton', {
                    Name = id or 'BannerCard',
                    Size = UDim2.new(1, 0, 0, 0),
                    AutomaticSize = Enum.AutomaticSize.Y,
                    BackgroundTransparency = 0.86,
                    AutoButtonColor = false,
                    Text = '',
                    ClipsDescendants = true,
                    LayoutOrder = 7,
                    Parent = self.Container,
                    ThemeTag = {BackgroundColor3 = 'Element'}
                }, {
                    New('UIListLayout', {SortOrder = Enum.SortOrder.LayoutOrder, Padding = UDim.new(0, 0)}),
                    New('UICorner', {CornerRadius = UDim.new(0, 12)}),
                    New('UIStroke', {Transparency = 0.42, ThemeTag = {Color = 'InElementBorder'}})
                })

                local headerWrap = New('Frame', {
                    Name = 'BannerHeader',
                    Size = UDim2.new(1, 0, 0, showBanner and bannerH or (showAvatar and (avSize + 12) or 0)),
                    BackgroundTransparency = 1,
                    Visible = showBanner or showAvatar,
                    LayoutOrder = 1,
                    ZIndex = 2,
                    Parent = cardFrame
                })

                local bannerImg = New('ImageLabel', {
                    Name = 'BannerImage',
                    Size = UDim2.new(1, 0, 0, bannerH),
                    BackgroundColor3 = Color3.fromRGB(43, 52, 86),
                    BackgroundTransparency = 0,
                    Image = '',
                    ScaleType = Enum.ScaleType.Crop,
                    Visible = showBanner,
                    ZIndex = 1,
                    Parent = headerWrap
                }, {
                    New('UIGradient', {
                        Rotation = 90,
                        Color = ColorSequence.new({
                            ColorSequenceKeypoint.new(0, Color3.fromRGB(255, 255, 255)),
                            ColorSequenceKeypoint.new(1, Color3.fromRGB(165, 175, 200))
                        })
                    })
                })

                local avY = showBanner and math.max(8, bannerH - math.floor(avSize / 2)) or 10
                local avWrap = New('Frame', {
                    Name = 'BannerAvatarWrap',
                    Position = UDim2.fromOffset(14, avY),
                    Size = UDim2.fromOffset(avSize, avSize),
                    BackgroundColor3 = config.AccentColor or Color3.fromRGB(88, 101, 242),
                    Visible = showAvatar,
                    ZIndex = 4,
                    Parent = headerWrap
                }, {
                    New('UICorner', {CornerRadius = avCornerRadius}),
                    New('UIStroke', {Thickness = 3, ThemeTag = {Color = 'Element'}})
                })

                local avFallback = New('TextLabel', {
                    Size = UDim2.fromScale(1, 1),
                    BackgroundTransparency = 1,
                    IgnoreFontFamily = true,
                    FontFace = Font.new('rbxasset://fonts/families/GothamSSm.json', Enum.FontWeight.Bold, Enum.FontStyle.Normal),
                    Text = tostring(config.AvatarFallback or ''),
                    TextColor3 = Color3.fromRGB(255, 255, 255),
                    TextSize = math.max(14, math.floor(avSize * 0.38)),
                    Visible = typeof(config.AvatarFallback) == 'string' and config.AvatarFallback ~= '',
                    ZIndex = 4,
                    Parent = avWrap
                })

                local avImg = New('ImageLabel', {
                    Name = 'BannerAvatar',
                    Size = UDim2.fromScale(1, 1),
                    BackgroundTransparency = 1,
                    Image = '',
                    ScaleType = Enum.ScaleType.Crop,
                    Visible = false,
                    ZIndex = 5,
                    Parent = avWrap
                }, {New('UICorner', {CornerRadius = avCornerRadius})})

                local decoSz = math.floor(avSize * 1.28 + 0.5)
                local decoImg = New('ImageLabel', {
                    Name = 'BannerDecoration',
                    AnchorPoint = Vector2.new(0.5, 0.5),
                    Position = UDim2.fromScale(0.5, 0.5),
                    Size = UDim2.fromOffset(decoSz, decoSz),
                    BackgroundTransparency = 1,
                    Image = '',
                    ScaleType = Enum.ScaleType.Fit,
                    Visible = false,
                    ZIndex = 6,
                    Parent = avWrap
                })

                local bodyWrap = New('Frame', {
                    Name = 'BannerBody',
                    Size = UDim2.new(1, 0, 0, 0),
                    AutomaticSize = Enum.AutomaticSize.Y,
                    BackgroundTransparency = 1,
                    LayoutOrder = 2,
                    ZIndex = 3,
                    Parent = cardFrame
                }, {
                    New('UIPadding', {
                        PaddingTop = UDim.new(0, 8),
                        PaddingBottom = UDim.new(0, 12),
                        PaddingLeft = UDim.new(0, 14),
                        PaddingRight = UDim.new(0, 14)
                    }),
                    New('UIListLayout', {SortOrder = Enum.SortOrder.LayoutOrder, Padding = UDim.new(0, 10)})
                })

                local titleAreaPad = New('UIPadding', {
