                        if ch:IsA('Frame') then
                            ch:Destroy()
                        end
                    end
                    if typeof(stats) ~= 'table' or #stats == 0 then
                        statsRow.Visible = false
                        return
                    end
                    statsRow.Visible = true
                    local count = #stats
                    local gapAdjust = math.ceil(8 * (count - 1) / count)
                    for idx, item in next, stats do
                        local labelText = typeof(item) == 'table' and tostring(item.Text or '') or tostring(item)
                        local dotColor = (typeof(item) == 'table' and typeof(item.Color) == 'Color3') and item.Color or Color3.fromRGB(35, 165, 90)
