                        }, {
                            New('UICorner', {CornerRadius = UDim.new(0, 8)}),
                            New('Frame', {
                                AnchorPoint = Vector2.new(0, 0.5),
                                Position = UDim2.new(0, 10, 0.5, 0),
                                Size = UDim2.fromOffset(8, 8),
                                BackgroundColor3 = dotColor
                            }, {New('UICorner', {CornerRadius = UDim.new(1, 0)})})
                        })
                        Creator.BindFont(New('TextLabel', {
                            Position = UDim2.fromOffset(24, 0),
                            Size = UDim2.new(1, -30, 1, 0),
                            BackgroundTransparency = 1,
                            FontFace = Font.new('rbxasset://fonts/families/GothamSSm.json', Enum.FontWeight.SemiBold, Enum.FontStyle.Normal),
                            Text = Creator.TranslateRaw(labelText),
                            TextSize = isMob and 11 or 12,
                            TextXAlignment = Enum.TextXAlignment.Left,
                            TextTruncate = Enum.TextTruncate.AtEnd,
                            Parent = pill,
                            ThemeTag = {TextColor3 = 'Text'}
                        }), isMob and 11 or 12, {minCap = 9, maxCap = 18})
                    end
                end

                if typeof(config.Stats) == 'table' then
                    control:SetStats(config.Stats)
                end

                local lastCtaTick = 0
                local function fireCallback()
                    if typeof(config.Callback) == 'function' then
                        library:SafeCallback(config.Callback)
                    end
                end
                Creator.AddSignal(ctaBtn.MouseEnter, function()
                    TweenService:Create(ctaBtn, TweenInfo.new(0.15), {BackgroundTransparency = 0}):Play()
                end)
                Creator.AddSignal(ctaBtn.MouseLeave, function()
                    TweenService:Create(ctaBtn, TweenInfo.new(0.15), {BackgroundTransparency = 0.08}):Play()
                end)
                Creator.AddSignal(ctaBtn.MouseButton1Click, function()
                    lastCtaTick = tick()
                    fireCallback()
                end)
                if typeof(config.Callback) == 'function' and config.Clickable ~= false then
                    Creator.AddSignal(cardFrame.MouseButton1Click, function()
                        if tick() - lastCtaTick > 0.1 then
                            fireCallback()
                        end
                    end)
                end

                function control:Destroy()
                    cardFrame:Destroy()
                    if id then
                        library.Options[id] = nil
                    end
                end

                if id then
                    library.Options[id] = control
                end
                return control
            end

            Elements[#Elements + 1] = Banner
            return Elements
        end)()
    end,

