    [14] = function()
        local env, script, require = waxGetEnv(14)
        return (function(...)
            local Root = script.Parent.Parent
            local Creator, Layout = require(Root.Modules.Creator), require(Root.Modules.Layout)
            local New, Components, Button = Creator.New, Root.Components, {}
            Button.__index = Button
            Button.__type = 'Button'

            function Button:New(idOrConfig, maybeConfig)
                local id = typeof(idOrConfig) == 'string' and idOrConfig or nil
                local config = typeof(idOrConfig) == 'table' and idOrConfig or maybeConfig
                assert(typeof(config) == 'table' and config.Title, 'Button - Missing Title')
                config.Callback = config.Callback or function() end
                local element = require(Components.Element)(config.Title, config.Description, self.Container, true)
                local imageLabel = nil
                if config.RightIcon ~= false then
                    imageLabel = (New('ImageLabel', {
                        Size = UDim2.fromOffset(Layout.Card.IconSize, Layout.Card.IconSize),
                        AnchorPoint = Vector2.new(1, 0.5),
                        Position = UDim2.new(1, -Layout.Card.TrailingInset, 0.5, 0),
                        BackgroundTransparency = 1,
                        Parent = element.Frame,
                        ThemeTag = {ImageColor3 = 'Text'}
                    }))
                    self.Library.Utilities.Icons:SetIcon(imageLabel, typeof(config.RightIcon) == 'string' and config.RightIcon or 'chevron-right')
                end

                local avSrc = config.Avatar ~= nil and config.Avatar or config.Image
                local hasAvatar = avSrc ~= nil or config.Decoration ~= nil or config.Fallback ~= nil or config.StatusColor ~= nil or config.ShowAvatar == true
                local avSize = tonumber(config.AvatarSize) or (Layout.IsMobile and 34 or 40)
                local avCorner = config.AvatarCorner == 'Circle' and UDim.new(1, 0) or (typeof(config.AvatarCorner) == 'number' and UDim.new(0, config.AvatarCorner) or UDim.new(1, 0))
                local avWrap, fallbackLbl, avImg, decoImg, statusDot

                local function ensureAvatarSlot()
                    if avWrap then
                        return
                    end
                    local leftX = Layout.Card.LeftInset
                    local extraLeft = avSize + 12
                    element.LabelHolder.Position = UDim2.fromOffset(leftX + extraLeft, 0)
                    element.LabelHolder.Size = UDim2.new(1, -(leftX + extraLeft + Layout.Card.DefaultLabelRightReserve), 0, 0)
                    New('UISizeConstraint', {
                        MinSize = Vector2.new(0, avSize + (Layout.IsMobile and 14 or 18)),
                        Parent = element.Frame
                    })
                    avWrap = New('Frame', {
                        Name = 'AvatarWrap',
                        AnchorPoint = Vector2.new(0, 0.5),
                        Position = UDim2.new(0, leftX, 0.5, 0),
                        Size = UDim2.fromOffset(avSize, avSize),
                        BackgroundColor3 = config.AccentColor or config.Color or Color3.fromRGB(88, 101, 242),
                        BackgroundTransparency = 0.15,
                        ZIndex = 2,
                        Parent = element.Frame
                    }, {
                        New('UICorner', {CornerRadius = avCorner}),
                        New('UIStroke', {Thickness = 1.4, Transparency = 0.35, ThemeTag = {Color = 'InElementBorder'}})
                    })
                    fallbackLbl = New('TextLabel', {
                        Size = UDim2.fromScale(1, 1),
                        BackgroundTransparency = 1,
                        IgnoreFontFamily = true,
                        FontFace = Font.new('rbxasset://fonts/families/GothamSSm.json', Enum.FontWeight.Bold, Enum.FontStyle.Normal),
                        Text = tostring(config.Fallback or ''),
                        TextColor3 = Color3.fromRGB(255, 255, 255),
                        TextSize = Layout.IsMobile and 13 or 15,
                        ZIndex = 2,
                        Parent = avWrap
                    })
                    avImg = New('ImageLabel', {
                        Name = 'Avatar',
                        Size = UDim2.fromScale(1, 1),
                        BackgroundTransparency = 1,
                        Image = '',
                        ScaleType = Enum.ScaleType.Crop,
                        Visible = false,
                        ZIndex = 3,
                        Parent = avWrap
                    }, {New('UICorner', {CornerRadius = avCorner})})
                    local decoSz = math.floor(avSize * 1.28 + 0.5)
                    decoImg = New('ImageLabel', {
                        Name = 'AvatarDecoration',
                        AnchorPoint = Vector2.new(0.5, 0.5),
                        Position = UDim2.fromScale(0.5, 0.5),
                        Size = UDim2.fromOffset(decoSz, decoSz),
                        BackgroundTransparency = 1,
                        Image = '',
                        ScaleType = Enum.ScaleType.Fit,
                        Visible = false,
                        ZIndex = 5,
                        Parent = avWrap
                    })
                end

                function element:SetAvatar(src, cacheKey)
                    ensureAvatarSlot()
                    Creator.ApplyImageSource(avImg, src, cacheKey or config.AvatarCacheKey, fallbackLbl)
                end

                function element:SetDecoration(src, cacheKey)
                    ensureAvatarSlot()
                    Creator.ApplyImageSource(decoImg, src, cacheKey or config.DecorationCacheKey)
                end

                function element:SetStatusColor(color)
                    ensureAvatarSlot()
                    if not statusDot then
                        statusDot = New('Frame', {
                            Name = 'StatusDot',
                            AnchorPoint = Vector2.new(1, 1),
                            Position = UDim2.new(1, 1, 1, 1),
                            Size = UDim2.fromOffset(Layout.IsMobile and 10 or 11, Layout.IsMobile and 10 or 11),
                            BackgroundColor3 = typeof(color) == 'Color3' and color or Color3.fromRGB(128, 132, 142),
                            ZIndex = 6,
                            Parent = avWrap
                        }, {
                            New('UICorner', {CornerRadius = UDim.new(1, 0)}),
                            New('UIStroke', {Thickness = 2, ThemeTag = {Color = 'Element'}})
                        })
                    end
                    if typeof(color) == 'Color3' then
                        statusDot.BackgroundColor3 = color
                        statusDot.Visible = true
                    else
                        statusDot.Visible = false
                    end
                end

                function element:SetAccentColor(color)
                    ensureAvatarSlot()
                    if typeof(color) == 'Color3' then
                        avWrap.BackgroundColor3 = color
                    end
                end

                if hasAvatar then
                    ensureAvatarSlot()
                    if avSrc and avSrc ~= '' then
                        element:SetAvatar(avSrc)
                    end
                    if config.Decoration and config.Decoration ~= '' then
                        element:SetDecoration(config.Decoration)
                    end
                    if typeof(config.StatusColor) == 'Color3' then
                        element:SetStatusColor(config.StatusColor)
                    end
                end

                function element:Lock(reason)
                    if self.Locked then
                        return
                    end
                    self.Locked = true
                    if self.DescLabel then
                        self.DescLabel.Visible = false
                    end
                    if not self.LockOverlay then
                        local lockIconSz = Layout.IsMobile and 16 or 20
                        self.LockOverlay = New('Frame', {
                            Size = UDim2.fromScale(1, 1),
                            BackgroundColor3 = Color3.new(0, 0, 0),
                            BackgroundTransparency = 0.6,
                            ZIndex = 10,
                            Parent = element.Frame
                        }, {New('UICorner', {CornerRadius = UDim.new(0, Layout.Card.Radius)})})
                        self.LockIcon = New('ImageLabel', {
                            Size = UDim2.fromOffset(lockIconSz, lockIconSz),
                            Position = UDim2.fromScale(0.5, 0.5),
                            AnchorPoint = Vector2.new(0.5, 0.5),
                            BackgroundTransparency = 1,
                            Parent = self.LockOverlay,
                            ZIndex = 11,
                            ThemeTag = {ImageColor3 = 'Text'}
                        })
                        self.Library.Utilities.Icons:SetIcon(self.LockIcon, 'lock')
                    end
                    self.LockOverlay.Visible = true
                end

                function element:Unlock()
                    if not self.Locked then
                        return
                    end
                    self.Locked = false
                    if self.LockOverlay then
                        self.LockOverlay.Visible = false
                    end
                    if config.Description and self.DescLabel then
                        self.DescLabel.Visible = true
                    end
                end
                Creator.AddSignal(element.Frame.MouseButton1Click, function()
                    if element.Locked then
                        return
                    end
                    if typeof(config.Callback) == 'function' then
                        self.Library:SafeCallback(config.Callback, config.Value)
                    end
                end)
                if id then
                    self.Library.Options[id] = element
                    local baseDestroy = element.Destroy
                    function element:Destroy()
                        baseDestroy(self)
                        self.Library.Options[id] = nil
                    end
                end
                element.Instance = element
                return element
            end
            return Button
        end)()
    end,

