                            isSelected = control.Value == value
                        end
                        local bgMotor, setBgAlpha = Creator.SpringMotor(1, optionBtn, 'BackgroundTransparency')
                        local barMotor, setBarAlpha = Creator.SpringMotor(1, optionFrame, 'BackgroundTransparency')
                        local checkMotor, setCheckAlpha = Creator.SpringMotor(1, optionCheck, 'ImageTransparency')
                        local barSizeMotor = Flipper.SingleMotor.new(Layout.IsMobile and 4 or 6)
                        barSizeMotor:onStep(function(barHeight)
                            optionFrame.Size = UDim2.new(0, 4, 0, barHeight)
                        end)
                        Creator.AddSignal(optionBtn.MouseEnter, function()
                            setBgAlpha(isSelected and 0.85 or 0.89)
                        end)
                        Creator.AddSignal(optionBtn.MouseLeave, function()
                            setBgAlpha(isSelected and 0.89 or 1)
                        end)
                        Creator.AddSignal(optionBtn.MouseButton1Down, function()
                            setBgAlpha(0.92)
                        end)
                        Creator.AddSignal(optionBtn.MouseButton1Up, function()
                            setBgAlpha(isSelected and 0.85 or 0.89)
                        end)

                        function buttonMap:UpdateButton()
                            if config.Multi then
                                isSelected = control.Value[value]
                                if isSelected then
                                    setBgAlpha(0.89)
                                end
                            else
                                isSelected = control.Value == value
                                setBgAlpha(isSelected and 0.89 or 1)
                            end
                            barSizeMotor:setGoal(Flipper.Spring.new(isSelected and (Layout.IsMobile and 10 or 14) or (Layout.IsMobile and 4 or 6), {frequency = 6}))
                            setBarAlpha(isSelected and 0 or 1)
                            setCheckAlpha(isSelected and 0 or 1)
                        end
                        optionLabel.InputBegan:Connect(function(input)
                            if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
                                local nextSelected = not isSelected
                                if control:GetActiveValues() == 1 and not nextSelected and not config.AllowNull then
                                else
                                    if config.Multi then
                                        isSelected = nextSelected
                                        control.Value[value] = isSelected and true or nil
                                        if typeof(control.Callback) == 'function' then
                                            library:SafeCallback(control.Callback, control.Value)
                                        end
                                        if typeof(control.Changed) == 'function' then
                                            library:SafeCallback(control.Changed, control.Value)
                                        end
                                    else
                                        isSelected = nextSelected
                                        control:SetValue(isSelected and value or nil)
                                        for _, btnCtrl in next, filteredList do
                                            btnCtrl:UpdateButton()
                                        end
                                    end
                                    buttonMap:UpdateButton()
                                    control:Display()
                                end
                            end
                        end)
                        optionLabel.Text = control.Displayer(value)
                        optionBtn.Parent = scrollFrame
                        buttonMap:UpdateButton()
                        control:Display()
                        filteredList[optionBtn] = buttonMap
                    end
                    menuWidth = 0
                    for key, value in next, filteredList do
                        if key.ButtonLabel then
                            if key.ButtonLabel.TextBounds.X > menuWidth then
                                menuWidth = key.ButtonLabel.TextBounds.X
                            end
                        end
                    end
                    menuWidth = menuWidth + 30
                    updateCanvasSize()
                    updateMenuSize()
                end

                function control:SetValues(values)
                    if values then
                        rawset(control, 'Values', values)
                    end
                    control:BuildDropdownList()
                end

                function control:OnChanged(callback)
                    control.Changed = callback
                    library:SafeCallback(callback, control.Value, control.Value)
                end

                function control:SetValue(value)
                    if control.Multi then
                        local formattedList = {}
                        for key, value in next, value do
                            if table.find(control.Values, key) then
                                formattedList[key] = true
                            end
                        end
                        rawset(control, 'Value', formattedList)
                    else
                        if not value then
                            rawset(control, 'Value', nil)
                        elseif table.find(control.Values, value) then
                            rawset(control, 'Value', value)
                        end
                    end
                    control:BuildDropdownList()
                    if typeof(control.Callback) == 'function' then
                        library:SafeCallback(control.Callback, control.Value)
                    end
                    if typeof(control.Changed) == 'function' then
                        library:SafeCallback(control.Changed, control.Value)
                    end
                end

                function control:Destroy()
                    element:Destroy()
                    library.Options[id] = nil
                end

                function control:Lock(reason)
                    if control.Locked then
                        return
                    end
                    control.Locked = true
                    control:Close()
                    control.SetDesc(nil)
                    if not control.LockIcon then
                        control.LockIcon = New('ImageLabel', {
                            Image = 'rbxassetid://3926305904',
                            Size = UDim2.fromOffset(16, 16),
                            AnchorPoint = Vector2.new(1, 0.5),
                            Position = UDim2.new(1, -Layout.Dropdown.ChevronInset, 0.5, 0),
                            BackgroundTransparency = 1,
                            Parent = dropdownBtn,
                            ThemeTag = {ImageColor3 = 'SubText'},
                            ZIndex = 5
                        })
                    end
                    arrowIcon.Visible = false
                    control.LockIcon.Visible = true
                    dropdownBtn.BackgroundTransparency = 0.5
                    selectedLabel.TextTransparency = 0.5
                end

                function control:Unlock()
                    if not control.Locked then
                        return
                    end
                    control.Locked = false
                    if control.LockIcon then
                        control.LockIcon.Visible = false
                    end
                    arrowIcon.Visible = true
                    control.SetDesc(config.Description)
                    dropdownBtn.BackgroundTransparency = 0.9
                    selectedLabel.TextTransparency = 0
                end
                control:BuildDropdownList()
                control:Display()
                local newSelection = {}
                if type(config.Default) == 'table' then
                    for _, value in next, config.Default do
                        local foundIdx = table.find(control.Values, value)
                        if foundIdx then
                            newSelection[#newSelection + 1] = foundIdx
                        end
                    end
                    table.clear(config.Default)
                elseif type(config.Default) == 'number' and control.Values[config.Default] ~= nil then
                    newSelection[#newSelection + 1] = config.Default
                else
                    local defaultIdx = table.find(control.Values, config.Default)
                    if defaultIdx then
                        newSelection[#newSelection + 1] = defaultIdx
                    end
                end
                if next(newSelection) then
                    for index = 1, #newSelection do
                        local itemVal = newSelection[index]
                        if config.Multi then
                            control.Value[control.Values[itemVal]] = true
                        else
                            control.Value = control.Values[itemVal]
                            break
                        end
                    end
                    control:BuildDropdownList()
                    control:Display()
                end

                function control:Lock(reason)
                    if control.Locked then
                        return
                    end
                    control.Locked = true
                    if not control.LockOverlay then
                        local lockIconSz = Layout.IsMobile and 16 or 20
                        control.LockOverlay = New('Frame', {
                            Size = UDim2.fromScale(1, 1),
                            BackgroundColor3 = Color3.new(0, 0, 0),
                            BackgroundTransparency = 0.6,
                            ZIndex = 10,
                            Parent = element.Frame
                        }, {New('UICorner', {CornerRadius = UDim.new(0, Layout.Card.Radius)})})
                        control.LockIcon = New('ImageLabel', {
                            Size = UDim2.fromOffset(lockIconSz, lockIconSz),
