                        end
                        rawset(selfObj, propKey, newVal)
                    end
                })
            end
            return Dropdown
        end)()
    end,

    -- ========================================================================
    -- [Module 17]: Fluent Renewed/Elements/Input
    -- ========================================================================
    [17] = function()
        local env, script, require = waxGetEnv(17)
        return (function(...)
            local Root = script.Parent.Parent
            local Creator, Layout = require(Root.Modules.Creator), require(Root.Modules.Layout)
            local AddSignal, Components, Input = Creator.AddSignal, Root.Components, {}
            Input.__index = Input
            Input.__type = 'Input'

            function Input:New(id, config)
                local library = self.Library
                assert(config.Title, 'Input - Missing Title')
                config.Callback = config.Callback or function() end
                local control, element = {
                    Value = config.Default or config.Value or '',
                    Numeric = config.Numeric or false,
                    Finished = config.Finished or false,
                    Callback = config.Callback or function(_unused) end,
                    ClearOnFocusLost = config.ClearOnFocusLost or false,
                    Type = 'Input'
                }, require(Components.Element)(config.Title, config.Description, self.Container, false, {LabelRightReserve = Layout.Card.ControlLabelRightReserve})
                control.SetTitle = element.SetTitle
                control.SetDesc = element.SetDesc
                local textbox = require(Components.Textbox)(element.Frame, true)
                textbox.Frame.Position = UDim2.new(1, -Layout.Card.TrailingInset, 0.5, 0)
                textbox.Frame.AnchorPoint = Vector2.new(1, 0.5)
                textbox.Frame.Size = UDim2.fromOffset(Layout.Card.ControlMaxWidth, Layout.Card.ControlHeight)
                textbox.Input.Text = config.Default or ''
                textbox.Input.PlaceholderText = config.Placeholder or ''
                local inputBox, maxInputWidth, minInputWidth = textbox.Input, Layout.Card.ControlMaxWidth, Layout.Card.ControlMinWidth

                local function updateInputWidth()
                    local availWidth = element.Frame.AbsoluteSize.X - (Layout.Card.TrailingInset + 8)
                    local inputWidth = math.max(minInputWidth, math.min(maxInputWidth, availWidth))
                    textbox.Frame.Size = UDim2.fromOffset(inputWidth, Layout.Card.ControlHeight)
                end
                Creator.AddSignal(element.Frame:GetPropertyChangedSignal'AbsoluteSize', updateInputWidth)
                task.defer(updateInputWidth)

                function control:SetValue(value)
                    if config.MaxLength and #value > config.MaxLength then
                        value = value:sub(1, config.MaxLength)
                    end
                    if control.Numeric then
                        if (not tonumber(value)) and value:len() > 0 then
                            value = control.Value
                        end
                    end
                    rawset(control, 'Value', value)
                    inputBox.Text = value
                    if typeof(control.Callback) == 'function' then
                        library:SafeCallback(control.Callback, control.Value)
                    end
                    if typeof(control.Changed) == 'function' then
                        library:SafeCallback(control.Changed, control.Value)
                    end
                end
                if control.Finished then
                    AddSignal(inputBox.FocusLost, function(enterPressed, _unused)
                        if not enterPressed then
                            return
                        end
                        control:SetValue(inputBox.Text)
                        if config.ClearOnFocusLost then
                            inputBox.Text = ''
                        end
                    end)
                else
                    AddSignal(inputBox:GetPropertyChangedSignal'Text', function()
                        control:SetValue(inputBox.Text)
                    end)
                end

                function control:OnChanged(callback)
                    control.Changed = callback
                    library:SafeCallback(callback, control.Value, control.Value)
                end

                function control:Destroy()
                    element:Destroy()
                    library.Options[id] = nil
                end

                function control:Lock(reason)
                    if control.Locked then
                        return
                    end
                    control.Locked = true
                    if not control.LockOverlay then
                        local lockIconSz = Layout.IsMobile and 16 or 20
                        control.LockOverlay = New('Frame', {
                            Size = UDim2.fromScale(1, 1),
                            BackgroundColor3 = Color3.new(0, 0, 0),
                            BackgroundTransparency = 0.6,
                            ZIndex = 10,
                            Parent = element.Frame
                        }, {New('UICorner', {CornerRadius = UDim.new(0, Layout.Card.Radius)})})
                        control.LockIcon = New('ImageLabel', {
                            Size = UDim2.fromOffset(lockIconSz, lockIconSz),
                            Position = UDim2.fromScale(0.5, 0.5),
                            AnchorPoint = Vector2.new(0.5, 0.5),
                            BackgroundTransparency = 1,
                            Parent = control.LockOverlay,
                            ZIndex = 11,
                            ThemeTag = {ImageColor3 = 'Text'}
                        })
                        library.Utilities.Icons:SetIcon(control.LockIcon, 'lock')
                    end
                    control.LockOverlay.Visible = true
                    inputBox.TextEditable = false
                end

                function control:Unlock()
                    if not control.Locked then
                        return
                    end
                    control.Locked = false
                    if control.LockOverlay then
                        control.LockOverlay.Visible = false
                    end
                    inputBox.TextEditable = true
                end
                library.Options[id] = control
                control.Instance = element
                return setmetatable(control, {
                    __newindex = function(selfObj, propKey, newVal)
                        if propKey == 'Value' then
                            task.spawn(control.SetValue, control, newVal)
                        end
                        rawset(selfObj, propKey, newVal)
                    end
                })
            end
            return Input
        end)()
    end,

    -- ========================================================================
    -- [Module 18]: Fluent Renewed/Elements/Keybind
    -- ========================================================================
    [18] = function()
        local env, script, require = waxGetEnv(18)
        return (function(...)
            local UserInputService, Root = game:GetService'UserInputService', script.Parent.Parent
            local Creator, Layout = require(Root.Modules.Creator), require(Root.Modules.Layout)
            local New, Components, Keybind = Creator.New, Root.Components, {}
            Keybind.__index = Keybind
            Keybind.__type = 'Keybind'

            function Keybind:New(id, config)
                local library, control, isListening, element = self.Library, {
                    Value = config.Default or config.Value or Enum.KeyCode.Unknown,
                    Toggled = false,
                    Mode = config.Mode or 'Toggle',
                    Type = 'Keybind',
                    Callback = config.Callback or function(_unused) end,
                    ChangedCallback = config.ChangedCallback or function(_unused) end
                }, false, require(Components.Element)(config.Title or 'Keybind', config.Description, self.Container, true, {LabelRightReserve = Layout.Card.ControlLabelRightReserve})
                control.SetTitle = element.SetTitle
                control.SetDesc = element.SetDesc
                local label = New('TextLabel', {
                    FontFace = Font.new('rbxasset://fonts/families/GothamSSm.json', Enum.FontWeight.Regular, Enum.FontStyle.Normal),
                    Text = library.Utilities:Prettify(control.Value),
                    TextColor3 = Color3.fromRGB(240, 240, 240),
                    TextSize = Layout.Card.ControlTextSize,
                    TextXAlignment = Enum.TextXAlignment.Center,
                    Size = UDim2.new(0, 0, 0, Layout.Card.TitleHeight),
                    Position = UDim2.new(0, 0, 0.5, 0),
                    AnchorPoint = Vector2.new(0, 0.5),
                    BackgroundColor3 = Color3.fromRGB(255, 255, 255),
                    AutomaticSize = Enum.AutomaticSize.X,
                    BackgroundTransparency = 1,
                    ThemeTag = {TextColor3 = 'Text'}
                })
                local keyPad = Layout.IsMobile and 6 or 8
                local button = (New('TextButton', {
                    Size = UDim2.fromOffset(0, Layout.Card.ControlHeight),
                    Position = UDim2.new(1, -Layout.Card.TrailingInset, 0.5, 0),
                    AnchorPoint = Vector2.new(1, 0.5),
                    BackgroundTransparency = 0.9,
                    Parent = element.Frame,
                    AutomaticSize = Enum.AutomaticSize.X,
                    ThemeTag = {BackgroundColor3 = 'Keybind'}
                }, {
                    New('UICorner', {CornerRadius = UDim.new(0, Layout.Card.ControlCornerRadius)}),
                    New('UIPadding', {PaddingLeft = UDim.new(0, keyPad), PaddingRight = UDim.new(0, keyPad)}),
                    New('UIStroke', {
                        Transparency = 0.5,
                        ApplyStrokeMode = Enum.ApplyStrokeMode.Border,
                        ThemeTag = {Color = 'InElementBorder'}
                    }),
                    label
                }))

                function control:GetState()
                    if UserInputService:GetFocusedTextBox() and control.Mode ~= 'Always' then
                        return false
                    end
                    if control.Mode == 'Always' then
                        return true
                    elseif control.Mode == 'Hold' then
                        if control.Value == 'None' then
                            return false
                        end
                        local curKey = control.Value
                        if curKey == 'LeftMousebutton' or curKey == 'RightMousebutton' then
                            return curKey == 'LeftMousebutton' and UserInputService:IsMouseButtonPressed(Enum.UserInputType.MouseButton1) or curKey == 'RightMousebutton' and UserInputService:IsMouseButtonPressed(Enum.UserInputType.MouseButton2)
                        else
                            return UserInputService:IsKeyDown(Enum.KeyCode[control.Value])
                        end
                    else
                        return control.Toggled
                    end
                end

                function control:SetValue(value, mode)
                    value = value or control.Value
                    mode = mode or control.Mode
                    rawset(control, 'Value', value)
                    control.Mode = mode
                    label.Text = library.Utilities:Prettify(control.Value)
                    if typeof(control.ChangedCallback) == 'function' then
                        library:SafeCallback(control.ChangedCallback, value)
                    end
                    if typeof(control.Changed) == 'function' then
                        library:SafeCallback(control.Changed, value)
                    end
                end

                function control:OnClick(callback)
                    control.Clicked = callback
                end

                function control:OnChanged(callback)
                    control.Changed = callback
                    library:SafeCallback(callback, control.Value, control.Value)
                end

                function control:DoClick()
                    if typeof(control.Callback) == 'function' then
                        library:SafeCallback(control.Callback, control.Toggled)
                    end
                    if typeof(control.Clicked) == 'function' then
                        library:SafeCallback(control.Clicked, control.Toggled)
                    end
                end

                function control:Destroy()
                    element:Destroy()
                    library.Options[id] = nil
                end
                Creator.AddSignal(button.InputBegan, function(input)
                    if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
                        isListening = true
                        label.Text = '...'
                        wait(0.2)
                        UserInputService.InputBegan:Once(function(input)
                            local capturedKey
                            if input.UserInputType == Enum.UserInputType.Keyboard then
                                capturedKey = input.KeyCode.Name
                            elseif input.UserInputType == Enum.UserInputType.MouseButton1 then
                                capturedKey = 'LeftMousebutton'
                            elseif input.UserInputType == Enum.UserInputType.MouseButton2 then
                                capturedKey = 'RightMousebutton'
                            end
                            UserInputService.InputEnded:Once(function(input)
                                if (input.KeyCode.Name == capturedKey or capturedKey == 'LeftMousebutton' and input.UserInputType == Enum.UserInputType.MouseButton1 or capturedKey == 'RightMousebutton' and input.UserInputType == Enum.UserInputType.MouseButton2) and not library.Unloaded then
                                    isListening = false
                                    control.Value = capturedKey
                                    label.Text = library.Utilities:Prettify(control.Value)
                                    library:SafeCallback(control.ChangedCallback, input.KeyCode or input.UserInputType)
                                    library:SafeCallback(control.Changed, input.KeyCode or input.UserInputType)
                                end
                            end)
                        end)
                    end
                end)
                Creator.AddSignal(UserInputService.InputBegan, function(input)
                    if not isListening and not UserInputService:GetFocusedTextBox() then
                        if control.Mode == 'Toggle' then
                            local boundKey = control.Value
                            if boundKey == 'LeftMousebutton' or boundKey == 'RightMousebutton' then
                                if boundKey == 'LeftMousebutton' and input.UserInputType == Enum.UserInputType.MouseButton1 or boundKey == 'RightMousebutton' and input.UserInputType == Enum.UserInputType.MouseButton2 then
                                    control.Toggled = not control.Toggled
                                    control:DoClick()
                                end
                            elseif input.UserInputType == Enum.UserInputType.Keyboard then
                                if input.KeyCode.Name == boundKey or input.KeyCode == boundKey then
                                    control.Toggled = not control.Toggled
                                    control:DoClick()
                                end
                            end
                        end
                    end
                end)
                control:SetValue(control.Value)
                library.Options[id] = control
                control.Instance = element
                return setmetatable(control, {
                    __newindex = function(selfObj, propKey, newVal)
                        if propKey == 'Value' then
                            task.spawn(control.SetValue, control, newVal)
                        end
                        rawset(selfObj, propKey, newVal)
                    end
                })
            end
            return Keybind
        end)()
    end,

