                    Size = UDim2.new(1, Layout.IsMobile and 28 or 18, 0, Layout.IsMobile and 44 or 28),
                    ZIndex = 6
                })
                New('Frame', {
                    Size = UDim2.new(1, 0, 0, Layout.IsMobile and 6 or 4),
                    AnchorPoint = Vector2.new(1, 0.5),
                    Position = UDim2.new(1, -Layout.Card.TrailingInset, 0.5, 0),
                    BackgroundTransparency = 0.4,
                    Parent = element.Frame,
                    ThemeTag = {BackgroundColor3 = 'SliderRail'}
                }, {
                    New('UICorner', {CornerRadius = UDim.new(1, 0)}),
                    New('UISizeConstraint', {MaxSize = Vector2.new(Layout.IsMobile and 88 or 150, math.huge)}),
                    valueInput,
                    fillFrame,
                    railFrame,
                    sliderHitArea
                })
                local activeInput, pausedScrollFrames = nil, {}
                local function restoreScrollFrames()
                    for sf in next, pausedScrollFrames do
                        if sf and sf.Parent then
                            sf.ScrollingEnabled = true
                        end
                        pausedScrollFrames[sf] = nil
                    end
                end
                local function stopDragging()
                    if isDragging then
                        isDragging = false
                        activeInput = nil
                        restoreScrollFrames()
                    end
                end
                local function updateSliderFromX(screenX)
                    local w = railFrame.AbsoluteSize.X
                    if w <= 0 then
                        return
                    end
                    local ratio = math.clamp((screenX - railFrame.AbsolutePosition.X) / w, 0, 1)
                    control:SetValue(control.Min + ((control.Max - control.Min) * ratio))
                end
                local function beginSliderDrag(input)
                    if control.Locked then
                        return
                    end
                    if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
                        isDragging = true
                        activeInput = input
                        if input.UserInputType == Enum.UserInputType.Touch then
                            local p = element.Frame and element.Frame.Parent
                            while p do
                                if p:IsA('ScrollingFrame') and p.ScrollingEnabled then
                                    pausedScrollFrames[p] = true
                                    p.ScrollingEnabled = false
                                end
                                p = p.Parent
                            end
                        end
                        updateSliderFromX(input.Position.X)
                    end
                end
                Creator.AddSignal(sliderHitArea.InputBegan, beginSliderDrag)
                Creator.AddSignal(thumbIcon.InputBegan, beginSliderDrag)
                Creator.AddSignal(sliderHitArea.InputEnded, function(input)
                    if input == activeInput or input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
                        stopDragging()
                    end
                end)
                Creator.AddSignal(UserInputService.InputEnded, function(input)
                    if input == activeInput or input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
                        stopDragging()
                    end
                end)

                function control:OnChanged(callback)
                    control.Changed = callback
                    library:SafeCallback(callback, control.Value, control.Value)
                end

                function control:SetValue(value)
                    local targetVal = self.Value or value
                    rawset(self, 'Value', library.Utilities:Round(math.clamp(value, control.Min, control.Max), control.Rounding))
                    thumbIcon.Position = UDim2.new((self.Value - control.Min) / (control.Max - control.Min), -thumbHalf, 0.5, 0)
                    fillFrame.Size = UDim2.fromScale((self.Value - control.Min) / (control.Max - control.Min), 1)
                    valueInput.Text = tostring(self.Value)
                    if typeof(control.Callback) == 'function' then
                        library:SafeCallback(control.Callback, self.Value, targetVal)
                    end
                    if typeof(control.Changed) == 'function' then
                        library:SafeCallback(control.Changed, self.Value, targetVal)
                    end
                end
                Creator.AddSignal(UserInputService.InputChanged, function(input)
                    if isDragging and (input == activeInput or input.UserInputType == Enum.UserInputType.MouseMovement or input.UserInputType == Enum.UserInputType.Touch) then
                        updateSliderFromX(input.Position.X)
                    end
                end)
                Creator.AddSignal(valueInput.FocusLost, function()
                    control:SetValue(tonumber(valueInput.Text) or control.Value)
                end)

                function control:Destroy()
                    stopDragging()
                    element:Destroy()
                    library.Options[id] = nil
                end

                function control:Lock(reason)
                    if control.Locked then
                        return
                    end
                    control.Locked = true
                    if not control.LockOverlay then
                        local lockIconSz = Layout.IsMobile and 16 or 20
                        control.LockOverlay = New('Frame', {
                            Size = UDim2.fromScale(1, 1),
                            BackgroundColor3 = Color3.new(0, 0, 0),
                            BackgroundTransparency = 0.6,
                            ZIndex = 10,
                            Parent = element.Frame
                        }, {New('UICorner', {CornerRadius = UDim.new(0, Layout.Card.Radius)})})
                        control.LockIcon = New('ImageLabel', {
                            Size = UDim2.fromOffset(lockIconSz, lockIconSz),
                            Position = UDim2.fromScale(0.5, 0.5),
                            AnchorPoint = Vector2.new(0.5, 0.5),
                            BackgroundTransparency = 1,
                            Parent = control.LockOverlay,
                            ZIndex = 11,
                            ThemeTag = {ImageColor3 = 'Text'}
                        })
                        library.Utilities.Icons:SetIcon(control.LockIcon, 'lock')
                    end
                    control.LockOverlay.Visible = true
                end

                function control:Unlock()
                    if not control.Locked then
                        return
                    end
                    control.Locked = false
                    if control.LockOverlay then
                        control.LockOverlay.Visible = false
                    end
                end
                control:SetValue(typeof(config.Default) == 'number' and config.Default or control.Min)
                library.Options[id] = control
                control.Instance = element
                return setmetatable(control, {
                    __newindex = function(selfObj, propKey, newVal)
                        if propKey == 'Value' then
                            task.spawn(control.SetValue, control, newVal)
                        end
                        rawset(selfObj, propKey, newVal)
