    [21] = function()
        local env, script, require = waxGetEnv(21)
        return (function(...)
            local TweenService, UserInputService, Root = game:GetService'TweenService', game:GetService'UserInputService', script.Parent.Parent
            local Creator, Layout = require(Root.Modules.Creator), require(Root.Modules.Layout)
            local New, Components, Toggle = Creator.New, Root.Components, {}
            Toggle.__index = Toggle
            Toggle.__type = 'Toggle'

            function Toggle:New(id, config)
                local library = self.Library
