                local switchW, switchH = Layout.IsMobile and 30 or 36, Layout.IsMobile and 16 or 18
                local knobSize, knobOnX = Layout.IsMobile and 12 or 14, Layout.IsMobile and 16 or 19
                local knobIcon, trackStroke, particleLayer = (New('ImageLabel', {
                    AnchorPoint = Vector2.new(0, 0.5),
                    Size = UDim2.fromOffset(knobSize, knobSize),
