                        TweenService:Create(value, TweenInfo.new(duration, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {BackgroundTransparency = targetAlpha}):Play()
                    end
                end

                local function animateParticle(particle, token)
                    task.spawn(function()
                        while control.ParticleToken == token and control.Value and particle.Parent do
                            local layerSize = particleLayer.AbsoluteSize
                            local maxX, maxY = math.max(18, math.floor(layerSize.X) - 10), math.max(18, math.floor(layerSize.Y) - 10)
