                local function setParticlesEnabled(enabled)
                    control.ParticleToken += 1
                    local token = control.ParticleToken
                    if not enabled then
                        fadeParticles(1, 0.15)
                        return
                    end
                    for _, value in next, particles do
                        animateParticle(value, token)
                    end
                end

                function control:OnChanged(callback)
                    control.Changed = callback
                    library:SafeCallback(callback, control.Value, control.Value)
