                    Creator.OverrideTag(trackStroke, {Color = control.Value and 'Accent' or 'ToggleSlider'})
                    Creator.OverrideTag(knobIcon, {ImageColor3 = control.Value and 'ToggleToggled' or 'ToggleSlider'})
                    knobIcon:TweenPosition(UDim2.new(0, control.Value and knobOnX or 2, 0.5, 0), Enum.EasingDirection.Out, Enum.EasingStyle.Quint, 0.25, true)
                    TweenService:Create(switchTrack, TweenInfo.new(0.25, Enum.EasingStyle.Quint, Enum.EasingDirection.Out), {BackgroundTransparency = control.Value and 0.08 or 1}):Play()
                    knobIcon.ImageTransparency = control.Value and 0 or 0.5
                    setParticlesEnabled(control.Value)
                    if typeof(control.Callback) == 'function' then
                        library:SafeCallback(control.Callback, control.Value)
                    end
                    if typeof(control.Changed) == 'function' then
                        library:SafeCallback(control.Changed, control.Value)
                    end
                end

                function control:Destroy()
