    -- ========================================================================
    -- [Module 23]: Fluent Renewed/Modules/Acrylic
    -- ========================================================================
    [23] = function()
        local env, script, require = waxGetEnv(23)
        return (function(...)
            local Acrylic = {
                AcrylicBlur = require(script.AcrylicBlur),
                CreateAcrylic = require(script.CreateAcrylic),
                AcrylicPaint = require(script.AcrylicPaint)
            }

            function Acrylic.init()
                if getgenv().AcrylicController then
                    return
                end
                local dofEffect = Instance.new'DepthOfFieldEffect'
                dofEffect.FarIntensity = 0
                dofEffect.InFocusRadius = 0.1
                dofEffect.NearIntensity = 1
                local savedDofStates = {}
                getgenv().AcrylicController = {ActiveModels = {}}
                getgenv().AcrylicController.Enable = function()
                    for _, value in next, savedDofStates do
                        value.Enabled = false
                    end
                    dofEffect.Parent = game:GetService'Lighting'
                end
                getgenv().AcrylicController.Disable = function()
                    for _, value in next, savedDofStates do
                        value.Enabled = value.enabled
                    end
                    dofEffect.Parent = nil
                end
                getgenv().AcrylicController.Update = function()
                    local baseViewport = 0
                    for _, value in next, getgenv().AcrylicController.ActiveModels do
                        if value then
                            baseViewport = baseViewport + 1
                        end
                    end
                    if baseViewport > 0 then
                        getgenv().AcrylicController.Enable()
                    else
                        getgenv().AcrylicController.Disable()
                    end
                end

                local function initAcrylic()
                    local function saveDofState(obj)
                        if obj:IsA'DepthOfFieldEffect' then
                            savedDofStates[obj] = {enabled = obj.Enabled}
                        end
                    end
                    for _, value in next, game:GetService'Lighting':GetChildren() do
                        saveDofState(value)
                    end
                    if game:GetService'Workspace'.CurrentCamera then
                        for _, value in next, game:GetService'Workspace'.CurrentCamera:GetChildren() do
                            saveDofState(value)
                        end
                    end
                end
                initAcrylic()
                getgenv().AcrylicController.Enable()
                Acrylic.Enable = getgenv().AcrylicController.Enable
                Acrylic.Disable = getgenv().AcrylicController.Disable
            end
            return Acrylic
        end)()
    end,

    -- ========================================================================
    -- [Module 24]: Fluent Renewed/Modules/Acrylic/AcrylicBlur
    -- ========================================================================
    [24] = function()
        local env, script, require = waxGetEnv(24)
        return (function(...)
            local Root = script.Parent.Parent.Parent
            local Creator, CreateAcrylic, mapScreenToWorld, getViewportScale = require(Root.Modules.Creator), require(script.Parent.CreateAcrylic), unpack(require(script.Parent.Utils))
            local blurFolder = Instance.new('Folder', game:GetService'Workspace'.CurrentCamera)

            local function createBlurMesh(blurDistance)
                local connections = {}
                blurDistance = blurDistance or 0.001
                local corners, acrylicPart = {topLeft = Vector2.new(), topRight = Vector2.new(), bottomRight = Vector2.new()}, CreateAcrylic()
                local blurMesh = acrylicPart:FindFirstChildWhichIsA'SpecialMesh'
                acrylicPart.Parent = blurFolder

                local function setBounds(size, pos)
                    corners.topLeft = pos
                    corners.topRight = pos + Vector2.new(size.X, 0)
                    corners.bottomRight = pos + size
                end

                local function updateBlurCFrame()
                    local Camera = game:GetService'Workspace'.CurrentCamera
                    local camCFrame, tl, tr, br = (Camera and {(Camera.CFrame)} or {(CFrame.identity)})[1], corners.topLeft, corners.topRight, corners.bottomRight
                    local worldTL, worldTR, worldBR = mapScreenToWorld(tl, blurDistance), mapScreenToWorld(tr, blurDistance), mapScreenToWorld(br, blurDistance)
                    local meshWidth, meshHeight = (worldTR - worldTL).Magnitude, (worldTR - worldBR).Magnitude
                    acrylicPart.CFrame = CFrame.fromMatrix((worldTL + worldBR) / 2, camCFrame.XVector, camCFrame.YVector, camCFrame.ZVector)
                    if blurMesh then
                        blurMesh.Scale = Vector3.new(meshWidth, meshHeight, 0)
                    end
                end

                local function updateFromGui(guiObj)
                    local inset = getViewportScale()
                    local frameSize, framePos = guiObj.AbsoluteSize - Vector2.new(inset, inset), guiObj.AbsolutePosition + Vector2.new(inset / 2, inset / 2)
                    setBounds(frameSize, framePos)
                    task.spawn(updateBlurCFrame)
                end

                local function bindCameraSignals()
                    local Camera = game:GetService'Workspace'.CurrentCamera
                    if not Camera then
                        return
                    end
                    connections[#connections + 1] = Camera:GetPropertyChangedSignal'CFrame':Connect(updateBlurCFrame)
                    connections[#connections + 1] = Camera:GetPropertyChangedSignal'ViewportSize':Connect(updateBlurCFrame)
                    connections[#connections + 1] = Camera:GetPropertyChangedSignal'FieldOfView':Connect(updateBlurCFrame)
                    task.spawn(updateBlurCFrame)
                end
                acrylicPart.Destroying:Connect(function()
                    for _, conn in connections do
                        pcall(function()
                            conn:Disconnect()
                        end)
                    end
                    local controller = getgenv().AcrylicController
                    if controller then
                        controller.ActiveModels[acrylicPart] = nil
                        controller.Update()
                    end
                end)
                bindCameraSignals()
                return updateFromGui, acrylicPart
            end
            return function(uiElement)
                local blurApi, syncBounds, blurPart = {}, createBlurMesh(uiElement)
                local guiFrame = Creator.New('Frame', {BackgroundTransparency = 1, Size = UDim2.fromScale(1, 1)})
                Creator.AddSignal(guiFrame:GetPropertyChangedSignal'AbsolutePosition', function()
                    syncBounds(guiFrame)
                end)
                Creator.AddSignal(guiFrame:GetPropertyChangedSignal'AbsoluteSize', function()
                    syncBounds(guiFrame)
                end)
                blurApi.AddParent = function(targetGui)
                    Creator.AddSignal(targetGui:GetPropertyChangedSignal'Visible', function()
                        blurApi.SetVisibility(targetGui.Visible)
                    end)
                end
                blurApi.SetVisibility = function(visible)
                    blurPart.Transparency = visible and 0.98 or 1
                    blurPart.Parent = visible and blurFolder or nil
                    local controller = getgenv().AcrylicController
                    if controller then
                        controller.ActiveModels[blurPart] = visible or nil
                        controller.Update()
                    end
                end
                blurApi.Frame = guiFrame
                blurApi.Model = blurPart
                return blurApi
            end
        end)()
    end,

