                        ScaleType = Enum.ScaleType.Tile,
                        TileSize = UDim2.new(0, 128, 0, 128),
                        Size = UDim2.fromScale(1, 1),
                        BackgroundTransparency = 1,
                        ZIndex = 2,
                        ThemeTag = {ImageTransparency = 'AcrylicNoise'}
                    }, {New('UICorner', {CornerRadius = UDim.new(0, 8)})})
                    acrylicPaint.Frame = New('Frame', {
                    Size = UDim2.fromScale(1, 1),
                    BackgroundTransparency = 0.9,
                    BackgroundColor3 = Color3.fromRGB(255, 255, 255),
                    BorderSizePixel = 0
                }, {
                    New('ImageLabel', {
                        Image = 'rbxassetid://8992230677',
                        ScaleType = 'Slice',
                        SliceCenter = Rect.new(Vector2.new(99, 99), Vector2.new(99, 99)),
                        AnchorPoint = Vector2.new(0.5, 0.5),
                        Size = UDim2.new(1, 120, 1, 116),
                        Position = UDim2.new(0.5, 0, 0.5, 0),
                        BackgroundTransparency = 1,
                        ImageColor3 = Color3.fromRGB(0, 0, 0),
                        ImageTransparency = 0.7,
                        ZIndex = 0
                    }),
                    New('UICorner', {CornerRadius = UDim.new(0, 8)}),
                    acrylicPaint.BackgroundClip,
                    New('Frame', {
                        BackgroundTransparency = 0.45,
                        Size = UDim2.fromScale(1, 1),
                        Name = 'Background',
                        ZIndex = 2,
                        ThemeTag = {BackgroundColor3 = 'AcrylicMain'}
                    }, {New('UICorner', {CornerRadius = UDim.new(0, 8)})}),
                    acrylicPaint.GradientFrame,
                    acrylicPaint.FineNoiseLabel,
                    acrylicPaint.NoiseLabel,
                    New('Frame', {BackgroundTransparency = 1, Size = UDim2.fromScale(1, 1), ZIndex = 3}, {
                        New('UICorner', {CornerRadius = UDim.new(0, 8)}),
                        New('UIStroke', {Transparency = 0.5, Thickness = 1, ThemeTag = {Color = 'AcrylicBorder'}})
                    })
                })

                function acrylicPaint.SetBackground(mediaInput, scaleType, imageTransparency)
                    local uri = typeof(mediaInput) == 'table' and (mediaInput.kind == 'image' and mediaInput.uri or '') or (typeof(mediaInput) == 'string' and mediaInput or '')
                    if scaleType then
                        acrylicPaint.CustomBackground.ScaleType = scaleType
                        if scaleType == Enum.ScaleType.Tile then
                            acrylicPaint.CustomBackground.TileSize = UDim2.fromOffset(128, 128)
                        end
                    end
                    if typeof(imageTransparency) == 'number' then
                        acrylicPaint.CustomBackground.ImageTransparency = math.clamp(imageTransparency, 0, 1)
                    end
                    local hasImage = uri ~= ''
                    acrylicPaint.CustomBackground.Image = hasImage and uri or ''
                    acrylicPaint.CustomBackground.Visible = hasImage
                end

                function acrylicPaint.SetOverlayAlpha(alpha)
                    if typeof(alpha) == 'number' then
                        local clamped = math.clamp(alpha, 0.05, 1)
                        acrylicPaint.Frame.Background.BackgroundTransparency = clamped
                        acrylicPaint.GradientFrame.BackgroundTransparency = math.clamp(clamped + 0.12, 0.25, 1)
                        local showNoise = clamped < 0.90
                        if acrylicPaint.NoiseLabel then
                            acrylicPaint.NoiseLabel.Visible = showNoise
                        end
                        if acrylicPaint.FineNoiseLabel then
                            acrylicPaint.FineNoiseLabel.Visible = showNoise
                        end
                    else
                        acrylicPaint.Frame.Background.BackgroundTransparency = 0.45
                        acrylicPaint.GradientFrame.BackgroundTransparency = 0.4
                        if acrylicPaint.NoiseLabel then
                            acrylicPaint.NoiseLabel.Visible = true
                        end
                        if acrylicPaint.FineNoiseLabel then
                            acrylicPaint.FineNoiseLabel.Visible = true
                        end
                    end
                end
                local blurInstance
                if require(Root).UseAcrylic then
                    blurInstance = AcrylicBlur()
                    blurInstance.Frame.Parent = acrylicPaint.Frame
                    acrylicPaint.Model = blurInstance.Model
                    acrylicPaint.AddParent = blurInstance.AddParent
                    acrylicPaint.SetVisibility = blurInstance.SetVisibility
                end
                return acrylicPaint
            end
        end)()
    end,

