                    ImageLabel = {
                        BackgroundTransparency = 1,
                        BackgroundColor3 = Color3.new(1, 1, 1),
                        BorderColor3 = Color3.new(0, 0, 0),
                        BorderSizePixel = 0
                    },
                    ImageButton = {
                        BackgroundColor3 = Color3.new(1, 1, 1),
                        BorderColor3 = Color3.new(0, 0, 0),
                        AutoButtonColor = false
                    },
                    CanvasGroup = {
                        BackgroundColor3 = Color3.new(1, 1, 1),
                        BorderColor3 = Color3.new(0, 0, 0),
                        BorderSizePixel = 0
                    }
                },
                Theme = {Updating = false, Updated = Signal.new(), AnimationId = 0, ActiveTweens = {}}
            }

            local function applyThemeTag(inst, props)
                if typeof(props) == 'table' and props.ThemeTag then
                    Creator.AddThemeObject(inst, props.ThemeTag)
                end
            end

            function Creator.AddSignal(signal, callback)
                Creator.Signals[#Creator.Signals + 1] = signal:Connect(callback)
            end

            function Creator.Disconnect()
                for index = #Creator.Signals, 1, -1 do
                    local conn = table.remove(Creator.Signals, index)
                    if conn then
                        conn:Disconnect()
                    end
                end
            end

            function Creator.GetThemeProperty(propertyName)
                if Themes[require(Root).Theme][propertyName] then
                    return Themes[require(Root).Theme][propertyName]
                end
                return Themes['Dark'][propertyName]
            end

            local function getThemeObjectY(inst)
                if typeof(inst) ~= 'Instance' then
                    return 0
                end
                if inst:IsA('GuiBase2d') then
                    return inst.AbsolutePosition.Y
                end
                local guiParent = inst:FindFirstAncestorWhichIsA('GuiBase2d')
                if guiParent then
                    return guiParent.AbsolutePosition.Y
                end
                return 0
            end

            local function tweenColorSequence(grad, targetSeq, duration, myGen)
                local startSeq = grad.Color
                if typeof(startSeq) ~= 'ColorSequence' or typeof(targetSeq) ~= 'ColorSequence' or #startSeq.Keypoints < 2 or #targetSeq.Keypoints < 2 then
                    grad.Color = targetSeq
                    return
                end
                local c0From, c1From = startSeq.Keypoints[1].Value, startSeq.Keypoints[#startSeq.Keypoints].Value
                local c0To, c1To = targetSeq.Keypoints[1].Value, targetSeq.Keypoints[#targetSeq.Keypoints].Value
                local elapsed = 0
                local conn
                conn = RunService.RenderStepped:Connect(function(dt)
                    if Creator.Theme.AnimationId ~= myGen or not grad.Parent then
                        if conn then
                            conn:Disconnect()
                        end
                        return
                    end
                    elapsed += dt
                    local alpha = math.clamp(elapsed / duration, 0, 1)
                    local eased = TweenService:GetValue(alpha, Enum.EasingStyle.Sine, Enum.EasingDirection.Out)
                    grad.Color = ColorSequence.new(c0From:Lerp(c0To, eased), c1From:Lerp(c1To, eased))
                    if alpha >= 1 then
                        grad.Color = targetSeq
                        if conn then
                            conn:Disconnect()
                        end
                    end
                end)
            end

            function Creator.UpdateTheme(targetObject, animated)
                if typeof(targetObject) == 'Instance' and Creator.Registry[targetObject] then
                    for key, value in next, Creator.Registry[targetObject].Properties do
                        targetObject[key] = Creator.GetThemeProperty(value)
                    end
                    return
                end
                Creator.Theme.AnimationId = (Creator.Theme.AnimationId or 0) + 1
                local myGen = Creator.Theme.AnimationId
                for idx = #Creator.Theme.ActiveTweens, 1, -1 do
                    local tw = Creator.Theme.ActiveTweens[idx]
                    Creator.Theme.ActiveTweens[idx] = nil
                    pcall(tw.Cancel, tw)
                end

                if not animated then
                    for obj, registryEntry in next, Creator.Registry do
                        if obj and obj.Parent then
                            for key, value in next, registryEntry.Properties do
                                registryEntry.Object[key] = Creator.GetThemeProperty(value)
                            end
                        end
                    end
                    local elemTrans = Creator.GetThemeProperty'ElementTransparency'
                    for _, motor in next, Creator.TransparencyMotors do
                        motor:setGoal(Flipper.Instant.new(elemTrans))
                    end
                    Creator.Theme.Updating = false
                    Creator.Theme.Updated:Fire()
                    return
                end

                local ordered = {}
                for obj, registryEntry in next, Creator.Registry do
                    if obj and obj.Parent then
                        ordered[#ordered + 1] = {entry = registryEntry, y = getThemeObjectY(obj)}
                    else
                        Creator.Registry[obj] = nil
                    end
                end
                table.sort(ordered, function(a, b)
                    if a.y == b.y then
                        return (a.entry.Idx or 0) < (b.entry.Idx or 0)
                    end
                    return a.y < b.y
                end)

                local duration = 0.28
                local tweenInfo = TweenInfo.new(duration, Enum.EasingStyle.Sine, Enum.EasingDirection.Out)
                local elemTrans = Creator.GetThemeProperty'ElementTransparency'
                for _, motor in next, Creator.TransparencyMotors do
                    motor:setGoal(Flipper.Spring.new(elemTrans, {frequency = 6}))
                end

                task.spawn(function()
                    if #ordered == 0 then
                        Creator.Theme.Updated:Fire()
                        return
                    end
                    local bandStartY = ordered[1].y
                    local rowBandPx = 22
                    for _, item in ipairs(ordered) do
                        if Creator.Theme.AnimationId ~= myGen then
                            return
                        end
                        if item.y - bandStartY > rowBandPx then
                            task.wait(0.022)
                            if Creator.Theme.AnimationId ~= myGen then
                                return
                            end
                            bandStartY = item.y
                        end
                        local inst = item.entry.Object
                        if inst and inst.Parent then
                            local tweenProps = {}
                            local hasTweenProp = false
                            for propName, themeKey in next, item.entry.Properties do
                                local targetVal = Creator.GetThemeProperty(themeKey)
                                if targetVal ~= nil then
                                    local valType = typeof(targetVal)
                                    if valType == 'Color3' or valType == 'number' then
                                        tweenProps[propName] = targetVal
                                        hasTweenProp = true
                                    elseif valType == 'ColorSequence' and inst:IsA('UIGradient') then
                                        tweenColorSequence(inst, targetVal, duration, myGen)
                                    else
                                        pcall(function()
                                            inst[propName] = targetVal
                                        end)
                                    end
                                end
                            end
                            if hasTweenProp then
                                local ok, tw = pcall(TweenService.Create, TweenService, inst, tweenInfo, tweenProps)
                                if ok and tw then
                                    Creator.Theme.ActiveTweens[#Creator.Theme.ActiveTweens + 1] = tw
                                    tw:Play()
                                end
                            end
                        end
                    end
                    Creator.Theme.Updated:Fire()
                end)
            end

            function Creator.AddThemeObject(object, properties)
                Creator.ThemeSeq += 1
                local entry = {Object = object, Properties = properties, Idx = Creator.ThemeSeq}
                Creator.Registry[object] = entry
                Creator.UpdateTheme(object)
                return object
            end

            function Creator.OverrideTag(object, properties)
                Creator.Registry[object].Properties = properties
                Creator.UpdateTheme(object)
            end

            local function applyFontFamilyToObj(obj, savedEntry, familyKey)
                if typeof(obj) ~= 'Instance' or obj:GetAttribute('IgnoreFontFamily') then
                    return
                end
                local origFace = savedEntry and savedEntry.face
                if not origFace then
                    return
                end
                if not familyKey or familyKey == 'Default' or not Creator.FontPresets[familyKey] then
                    pcall(function()
                        obj.FontFace = origFace
                    end)
                    return
                end
                local baseFace = Font.fromEnum(Creator.FontPresets[familyKey].Enum)
                local applied = pcall(function()
                    obj.FontFace = Font.new(baseFace.Family, origFace.Weight, origFace.Style)
                end)
                if not applied then
                    pcall(function()
                        obj.FontFace = baseFace
                    end)
                end
            end

            local function trackFontObject(instance)
                if typeof(instance) ~= 'Instance' or instance:GetAttribute('IgnoreFontFamily') then
                    return
                end
                if not (instance:IsA('TextLabel') or instance:IsA('TextButton') or instance:IsA('TextBox')) then
                    return
                end
                if not Creator.FontObjects[instance] then
                    local ok, face = pcall(function()
                        return instance.FontFace
                    end)
                    if ok and face then
                        Creator.FontObjects[instance] = {face = face}
                    end
                end
                if Creator.FontFamily ~= 'Default' and Creator.FontObjects[instance] then
                    applyFontFamilyToObj(instance, Creator.FontObjects[instance], Creator.FontFamily)
                end
            end

            function Creator.New(title, config, parent)
                local instance = Instance.new(title)
                for key, value in next, Creator.DefaultProperties[title] or {} do
                    instance[key] = value
                end
                for key, value in next, config or {} do
                    if key == 'IgnoreFontFamily' then
                        instance:SetAttribute('IgnoreFontFamily', value and true or nil)
                    elseif key ~= 'ThemeTag' then
                        instance[key] = value
                    end
                end
                for _, value in next, parent or {} do
                    value.Parent = instance
                end
                applyThemeTag(instance, config)
                if title == 'TextLabel' or title == 'TextButton' or title == 'TextBox' then
                    trackFontObject(instance)
                end
                return instance
            end

            local function applyFontEntry(obj, entry)
                local scaledDelta = (Creator.FontDelta or 0) * (entry.deltaScale or 1)
                local nextSize = math.clamp(math.floor(entry.base + scaledDelta + 0.5), entry.minCap or 9, entry.maxCap or 26)
                pcall(function()
                    obj.TextSize = nextSize
                end)
                if entry.onResize then
                    pcall(entry.onResize, nextSize)
                end
            end

            function Creator.BindFont(obj, baseSize, opts)
                if typeof(obj) ~= 'Instance' then
                    return obj
                end
                opts = typeof(opts) == 'table' and opts or {}
                local entry = {
                    base = tonumber(baseSize) or 13,
                    minCap = opts.minCap,
                    maxCap = opts.maxCap,
                    deltaScale = opts.deltaScale,
                    onResize = opts.onResize
                }
                Creator.FontBindings[obj] = entry
                applyFontEntry(obj, entry)
                return obj
            end

            function Creator.SetFontSize(size, skipSave)
                local clamped = math.clamp(math.floor((tonumber(size) or 14) + 0.5), 14, 20)
                Creator.FontSize = clamped
                Creator.FontDelta = clamped - 14
                for obj, entry in next, Creator.FontBindings do
                    if typeof(obj) == 'Instance' then
                        applyFontEntry(obj, entry)
                    end
                end
                Creator.FontChanged:Fire(clamped, Creator.FontFamily)
                if not skipSave then
                    Creator.SaveSettings({MenuFontSize = clamped})
                end
                return clamped
            end

            function Creator.SetFontFamily(familyName, skipSave)
                local nextKey = (typeof(familyName) == 'string' and Creator.FontPresets[familyName]) and familyName or 'Default'
                Creator.FontFamily = nextKey
                for obj, savedEntry in next, Creator.FontObjects do
                    if typeof(obj) == 'Instance' then
                        applyFontFamilyToObj(obj, savedEntry, nextKey)
                    end
                end
                Creator.FontChanged:Fire(Creator.FontSize, nextKey)
                if not skipSave then
                    Creator.SaveSettings({MenuFontFamily = nextKey})
                end
                return nextKey
            end

            function Creator.SpringMotor(initial, object, property, ignoreDialog, resetOnTheme)
                ignoreDialog = ignoreDialog or false
                resetOnTheme = resetOnTheme or false
                local motor = Flipper.SingleMotor.new(initial)
                motor:onStep(function(val)
                    object[property] = val
                end)
                if resetOnTheme then
                    Creator.TransparencyMotors[#Creator.TransparencyMotors + 1] = motor
                end

                local function setMotorGoal(targetVal, instant)
                    instant = instant or false
                    if not ignoreDialog then
                        if not instant then
                            if property == 'BackgroundTransparency' and require(Root).DialogOpen then
                                return
                            end
                        end
                    end
                    motor:setGoal(Flipper.Spring.new(targetVal, {frequency = 8}))
                end
                return motor, setMotorGoal
            end

            function Creator.NormalizeLocale(rawLocale)
                if typeof(rawLocale) ~= 'string' then
                    return 'vi'
                end
                local normalized = rawLocale:lower():gsub('_', '-'):match('^%s*(.-)%s*$')
                if normalized == '' or normalized == 'auto' then
                    return Creator.Locale.DetectedLang or 'vi'
                end
                local base = normalized:match('^([a-z]+)')
                if base == 'vi' or base == 'vn' then
                    return 'vi'
                end
                return 'en'
            end

            function Creator.DetectCountryLocaleAsync()
                if Creator.Locale.DetectedLang ~= nil or Creator.Locale.Detecting then
                    return
                end
                Creator.Locale.Detecting = true
                task.spawn(function()
                    local countryCode
                    local httpReq = request or http_request or (syn and syn.request) or (http and http.request) or (fluxus and fluxus.request)
                    local function parseCountry(body)
                        if typeof(body) ~= 'string' or body == '' then
                            return nil
                        end
                        local ok, decoded = pcall(HttpService.JSONDecode, HttpService, body)
                        if ok and typeof(decoded) == 'table' and typeof(decoded.country) == 'string' and decoded.country ~= '' then
                            return decoded.country:upper()
                        end
                        return nil
                    end
                    if typeof(httpReq) == 'function' then
                        local okPost, resPost = pcall(httpReq, {
                            Url = 'https://api.country.is',
                            Method = 'POST',
                            Headers = {['Content-Type'] = 'application/json'},
                            Body = '{}'
                        })
                        if okPost and typeof(resPost) == 'table' then
                            countryCode = parseCountry(resPost.Body)
                        end
                        if not countryCode then
                            local okGet, resGet = pcall(httpReq, {
                                Url = 'https://api.country.is',
                                Method = 'GET'
                            })
                            if okGet and typeof(resGet) == 'table' then
                                countryCode = parseCountry(resGet.Body)
                            end
                        end
                    end
                    if not countryCode then
                        local okHttp, body = pcall(function()
                            return game:HttpGet('https://api.country.is')
                        end)
                        if okHttp then
                            countryCode = parseCountry(body)
                        end
                    end
                    if not countryCode then
                        local okLoc, region = pcall(function()
                            return LocalizationService:GetCountryRegionForPlayerAsync(Players.LocalPlayer)
                        end)
                        if okLoc and typeof(region) == 'string' and region ~= '' then
                            countryCode = region:upper()
                        end
                    end
                    Creator.Locale.DetectedCountry = countryCode or 'VN'
                    local nextLang = (Creator.Locale.DetectedCountry == 'VN') and 'vi' or 'en'
                    local changed = Creator.Locale.DetectedLang ~= nextLang
                    Creator.Locale.DetectedLang = nextLang
                    Creator.Locale.Detecting = false
                    if changed and (Creator.Locale.Mode == 'Auto' or Creator.Locale.Mode == '' or Creator.Locale.Mode == nil) then
                        Creator.UpdateLocale()
                    end
                end)
            end

            function Creator.DetectRobloxLocale()
                if Creator.Locale.DetectedLang == nil then
                    Creator.DetectCountryLocaleAsync()
                    return 'vi'
                end
                return Creator.Locale.DetectedLang
            end

            function Creator.GetActiveLocale()
                if Creator.Locale.Mode == 'Auto' or Creator.Locale.Mode == '' or Creator.Locale.Mode == nil then
                    return Creator.DetectRobloxLocale()
                end
                return Creator.NormalizeLocale(Creator.Locale.Mode)
            end

            function Creator.Translate(key, fallback)
                local lang = Creator.GetActiveLocale()
                local customTbl = Creator.Locale.Custom[lang]
                if customTbl and customTbl[key] ~= nil then
                    return customTbl[key]
                end
                local langTbl = Creator.Translations[lang]
                if langTbl and langTbl[key] ~= nil then
                    return langTbl[key]
                end
                local enTbl = Creator.Translations.en
                if enTbl and enTbl[key] ~= nil then
                    return enTbl[key]
                end
                return fallback or key
            end

            local function trimStr(str)
                return tostring(str or ''):match('^%s*(.-)%s*$')
            end

            local function getHttpRequestFn()
                return request or http_request or (syn and syn.request) or (http and http.request) or (fluxus and fluxus.request)
            end

            local function getCustomAssetFn()
                return getcustomasset or getsynasset
            end

            local function hashString32(str)
                local h = 5381
                for idx = 1, #str do
                    h = ((h * 33) + string.byte(str, idx)) % 2147483647
                end
                return tostring(h)
            end

            local b64Chars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/'
            local b64Lookup = {}
            for idx = 1, 64 do
                b64Lookup[string.byte(b64Chars, idx)] = idx - 1
            end

            function Creator.Base64Decode(data)
                if typeof(data) ~= 'string' or data == '' then
                    return ''
                end
                local out, buf, count = {}, 0, 0
                for idx = 1, #data do
                    local byteVal = string.byte(data, idx)
                    local v = b64Lookup[byteVal]
                    if v ~= nil then
                        buf = buf * 64 + v
                        count = count + 1
                        if count == 4 then
                            out[#out + 1] = string.char(buf // 65536, (buf // 256) % 256, buf % 256)
                            buf, count = 0, 0
                        end
                    elseif byteVal == 61 then
                        if count == 3 then
                            local n = buf * 64
                            out[#out + 1] = string.char(n // 65536, (n // 256) % 256)
                        elseif count == 2 then
                            local n = buf * 4096
                            out[#out + 1] = string.char(n // 65536)
                        end
                        break
                    end
                end
                return table.concat(out)
            end

            local function httpGetRaw(url, customHeaders)
                local httpReq = getHttpRequestFn()
                if typeof(httpReq) == 'function' then
                    local reqTbl = {Url = url, Method = 'GET'}
                    if typeof(customHeaders) == 'table' then
                        reqTbl.Headers = customHeaders
                    end
                    local ok, res = pcall(httpReq, reqTbl)
                    if ok and typeof(res) == 'table' and typeof(res.Body) == 'string' and res.Body ~= '' then
                        local status = tonumber(res.StatusCode or res.Status)
                        if not status or (status >= 200 and status < 300) then
                            return res.Body
                        end
                    end
                end
                local ok, res = pcall(function()
                    return game:HttpGet(url)
                end)
                if ok and typeof(res) == 'string' and res ~= '' then
                    return res
                end
                return nil
            end

            function Creator.OpenExternalUrl(url)
                local copied = Creator.CopyToClipboard(url)
                local opener = openurl or browseurl or open_url
                if typeof(opener) == 'function' then
                    pcall(opener, url)
                end
                return copied
            end

            local function decodeHtmlEntities(str)
                if typeof(str) ~= 'string' or str == '' then
                    return ''
                end
                local decoded = str
                    :gsub('&amp;', '&')
                    :gsub('&quot;', '"')
                    :gsub('&apos;', "'")
                    :gsub('&#39;', "'")
                    :gsub('&lt;', '<')
                    :gsub('&gt;', '>')
                    :gsub('&#x([%da-fA-F]+);', function(h)
                        local n = tonumber(h, 16)
                        return n and utf8.char(n) or ''
                    end)
                    :gsub('&#(%d+);', function(d)
                        local n = tonumber(d, 10)
                        return n and utf8.char(n) or ''
                    end)
                return trimStr(decoded)
            end

            function Creator.CopyToClipboard(text)
                local clipboardFn = setclipboard or toclipboard or set_clipboard or copystring or (Clipboard and Clipboard.set) or (clipboard and clipboard.set) or (Clipboard and Clipboard.copy) or (clipboard and clipboard.copy)
                if typeof(clipboardFn) == 'function' then
                    return pcall(clipboardFn, text)
                end
                return false
            end

            function Creator.FormatNumber(n)
                local num = math.floor(tonumber(n) or 0)
                local formatted = tostring(num)
                while true do
                    local nextStr, count = formatted:gsub('^(%-?%d+)(%d%d%d)', '%1,%2')
                    formatted = nextStr
                    if count == 0 then
                        break
                    end
                end
                return formatted
            end

            function Creator.OpenDiscordInvite(inviteCodeOrUrl)
                local raw = trimStr(inviteCodeOrUrl)
                local inviteCode = raw:match('discord%.gg/([%w%-_]+)') or raw:match('^([%w%-_]+)$') or 'rezhub'
                local inviteLink = 'https://discord.gg/' .. inviteCode
                local httpReq = getHttpRequestFn()
                if typeof(httpReq) == 'function' then
                    task.spawn(function()
                        pcall(httpReq, {
                            Url = 'http://127.0.0.1:6463/rpc?v=1',
                            Method = 'POST',
                            Headers = {
                                ['Content-Type'] = 'application/json',
                                ['Origin'] = 'https://discord.com'
                            },
                            Body = HttpService:JSONEncode({
                                cmd = 'INVITE_BROWSER',
                                args = {code = inviteCode},
                                nonce = HttpService:GenerateGUID(false)
                            })
                        })
                    end)
                end
                local copied = Creator.CopyToClipboard(inviteLink)
                return copied, inviteLink, inviteCode
            end

            local function ensureFolderPath(dirPath)
                if typeof(isfolder) ~= 'function' or typeof(makefolder) ~= 'function' then
                    return
                end
                local cur = ''
                for part in tostring(dirPath):gmatch('[^/\\]+') do
                    cur = cur == '' and part or (cur .. '/' .. part)
                    if not isfolder(cur) then
                        pcall(makefolder, cur)
                    end
                end
            end

            function Creator.FetchDiscordInviteStats(inviteCodeOrUrl, forceRefresh)
                local raw = trimStr(inviteCodeOrUrl)
                local code = raw:match('discord%.gg/([%w%-_]+)') or raw:match('^([%w%-_]+)$') or 'rezhub'
                local cached = Creator.DiscordCache[code]
                if cached and not forceRefresh and (tick() - (cached.fetchedAt or 0)) < 90 then
                    return cached
                end
                local url = 'https://discord.com/api/v10/invites/' .. code .. '?with_counts=true'
                local body = httpGetRaw(url)
                if body then
                    local ok, decoded = pcall(HttpService.JSONDecode, HttpService, body)
                    if ok and typeof(decoded) == 'table' and (decoded.approximate_member_count or decoded.approximate_presence_count) then
                        local g = typeof(decoded.guild) == 'table' and decoded.guild or {}
                        local gId = tostring(g.id or '')
                        local iconUrl = (gId ~= '' and typeof(g.icon) == 'string' and g.icon ~= '')
                            and string.format('https://cdn.discordapp.com/icons/%s/%s.png?size=256', gId, g.icon) or nil
                        local bannerHash = (typeof(g.banner) == 'string' and g.banner ~= '' and g.banner) or nil
                        local splashHash = (typeof(g.splash) == 'string' and g.splash ~= '' and g.splash) or nil
                        local bannerUrl = nil
                        if gId ~= '' and bannerHash then
                            bannerUrl = string.format('https://cdn.discordapp.com/banners/%s/%s.png?size=600', gId, bannerHash)
                        elseif gId ~= '' and splashHash then
                            bannerUrl = string.format('https://cdn.discordapp.com/splashes/%s/%s.png?size=600', gId, splashHash)
                        end
                        local info = {
                            code = code,
                            guildId = gId,
                            members = tonumber(decoded.approximate_member_count) or 0,
                            online = tonumber(decoded.approximate_presence_count) or 0,
                            name = (typeof(g.name) == 'string' and g.name ~= '' and g.name) or 'Rez Hub',
                            description = typeof(g.description) == 'string' and g.description or '',
                            boosts = tonumber(g.premium_subscription_count) or 0,
                            tier = tonumber(g.premium_tier) or 0,
                            iconUrl = iconUrl,
                            bannerUrl = bannerUrl,
                            fetchedAt = tick()
                        }
                        Creator.DiscordCache[code] = info
                        return info
                    end
                end
                return cached
            end

            function Creator.FetchLanyardUser(userId)
                local uid = tostring(userId or ''):match('%d+')
                if not uid or uid == '' then
                    return nil
                end
                local body = httpGetRaw('https://api.lanyard.rest/v1/users/' .. uid)
                if not body then
                    return nil
                end
                local ok, decoded = pcall(HttpService.JSONDecode, HttpService, body)
                if not ok or typeof(decoded) ~= 'table' or not decoded.success or typeof(decoded.data) ~= 'table' then
                    return nil
                end
                local d = decoded.data
                local u = typeof(d.discord_user) == 'table' and d.discord_user or {}
                local avatarUrl
                if typeof(u.avatar) == 'string' and u.avatar ~= '' then
                    avatarUrl = string.format('https://cdn.discordapp.com/avatars/%s/%s.png?size=256', uid, u.avatar)
                else
                    avatarUrl = 'https://cdn.discordapp.com/embed/avatars/0.png'
                end
                local decoData = typeof(u.avatar_decoration_data) == 'table' and u.avatar_decoration_data or nil
                local decoAsset = decoData and typeof(decoData.asset) == 'string' and decoData.asset or nil
                local decoUrl = decoAsset and string.format('https://cdn.discordapp.com/avatar-decoration-presets/%s.png?size=240&passthrough=false', decoAsset) or nil
                local actText = ''
                if typeof(d.activities) == 'table' then
                    for _, act in ipairs(d.activities) do
                        if typeof(act) == 'table' and act.type ~= 4 and typeof(act.name) == 'string' and act.name ~= '' then
                            actText = act.name
                            if typeof(act.details) == 'string' and act.details ~= '' then
                                actText = actText .. ' - ' .. act.details
                            end
                            break
                        elseif typeof(act) == 'table' and act.type == 4 and typeof(act.state) == 'string' and act.state ~= '' then
                            actText = act.state
                        end
                    end
                end
                return {
                    id = uid,
                    username = u.username or 'rez_hub',
                    displayName = u.display_name or u.global_name or u.username or 'Rez Hub',
                    status = d.discord_status or 'offline',
                    avatarUrl = avatarUrl,
                    decorationAsset = decoAsset,
                    decorationUrl = decoUrl,
                    activity = actText
                }
            end

            function Creator.FetchSocialProfileMeta(url)
                local headers = {
                    ['User-Agent'] = 'facebookexternalhit/1.1 (+http://www.facebook.com/externalhit_uatext.php)',
                    ['Accept-Language'] = 'vi-VN,vi;q=0.9,en;q=0.8'
                }
                local body = httpGetRaw(url, headers)
                if not body then
                    return nil
                end
                local function extractMeta(propName)
                    local val = body:match('<meta[^>]+property=["\']' .. propName .. '["\'][^>]+content=["\']([^"\']*)["\']')
                        or body:match('<meta[^>]+content=["\']([^"\']*)["\'][^>]+property=["\']' .. propName .. '["\']')
                    return val and decodeHtmlEntities(val) or nil
                end
                local title = extractMeta('og:title') or decodeHtmlEntities(body:match('<title>([^<]+)</title>') or '')
                local desc = extractMeta('og:description') or ''
                local img = extractMeta('og:image') or ''
                local summary = desc
                if desc ~= '' then
                    local fbFollow = desc:match('([%d%.,]+%s*người theo dõi[^%.]*)') or desc:match('([%d%.,]+%s*followers?[^%.]*)')
                    local ttStats = desc:match('(@[%w_%.]+%s+[^%-]+)')
                    if fbFollow then
                        summary = trimStr(fbFollow)
                    elseif ttStats then
                        summary = trimStr(ttStats)
                    end
                end
                return {
                    title = title,
                    description = desc,
                    summary = summary,
                    image = img
                }
            end

            function Creator.LoadRemoteImageToLabel(imageLabel, url, cacheKey, cacheFolder)
                if typeof(imageLabel) ~= 'Instance' or typeof(url) ~= 'string' or url == '' then
                    return false
                end
                local customAsset = getCustomAssetFn()
                if typeof(customAsset) ~= 'function' or typeof(writefile) ~= 'function' then
                    return false
                end
                local body = httpGetRaw(url, {['User-Agent'] = 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36'})
                if not body then
                    return false
                end
                local ext = nil
                if #body >= 8 then
                    if string.sub(body, 1, 8) == '\137PNG\r\n\26\n' then
                        ext = 'png'
                    elseif string.sub(body, 1, 3) == '\255\216\255' then
                        ext = 'jpg'
                    elseif string.sub(body, 1, 4) == 'RIFF' and string.sub(body, 9, 12) == 'WEBP' then
                        ext = 'webp'
                    end
                end
                if not ext then
                    return false
                end
                local targetDir = cacheFolder or 'Rez/social_cache'
                ensureFolderPath(targetDir)
                local safeName = tostring(cacheKey or hashString32(url)):gsub('[^%w_%-]', '_')
                local filePath = `{targetDir}/{safeName}.{ext}`
                local writeOk = pcall(writefile, filePath, body)
                if not writeOk then
                    return false
                end
                local aOk, assetUri = pcall(customAsset, filePath)
                if aOk and typeof(assetUri) == 'string' and assetUri ~= '' and imageLabel.Parent then
                    imageLabel.Image = assetUri
                    imageLabel.Visible = true
                    return true
                end
                return false
            end

            function Creator.ApplyImageSource(imageLabel, rawSource, cacheKey, fallbackObj)
                if typeof(imageLabel) ~= 'Instance' then
                    return false
                end
                local reqId = (tonumber(imageLabel:GetAttribute('_imgReqId')) or 0) + 1
                imageLabel:SetAttribute('_imgReqId', reqId)
                local cleaned = trimStr(rawSource)
                if cleaned == '' then
                    imageLabel.Image = ''
                    imageLabel.Visible = false
                    if typeof(fallbackObj) == 'Instance' then
                        fallbackObj.Visible = true
                    end
                    return false
                end
                if cleaned:match('^%d+$') then
                    cleaned = 'rbxassetid://' .. cleaned
                else
                    local rbxId = cleaned:match('[?&]id=(%d+)') or cleaned:match('roblox%.com/library/(%d+)') or cleaned:match('create%.roblox%.com/store/asset/(%d+)')
                    if rbxId then
                        cleaned = 'rbxassetid://' .. rbxId
                    end
                end
                if cleaned:match('^rbxassetid://') or cleaned:match('^rbxthumb://') or cleaned:match('^rbxasset://') then
                    imageLabel.Image = cleaned
                    imageLabel.Visible = true
                    if typeof(fallbackObj) == 'Instance' then
                        fallbackObj.Visible = false
                    end
                    return true
                end
                if cleaned:match('^https?://') then
                    task.spawn(function()
                        local ok = Creator.LoadRemoteImageToLabel(imageLabel, cleaned, cacheKey or ('img_' .. hashString32(cleaned)), 'Rez/img_cache')
                        if tonumber(imageLabel:GetAttribute('_imgReqId')) ~= reqId then
                            return
                        end
                        if ok and typeof(fallbackObj) == 'Instance' then
                            fallbackObj.Visible = false
                        end
                    end)
                    return true
                end
                local customAsset = getCustomAssetFn()
                if typeof(customAsset) == 'function' and typeof(isfile) == 'function' and isfile(cleaned) then
                    local aOk, assetUri = pcall(customAsset, cleaned)
                    if aOk and typeof(assetUri) == 'string' and assetUri ~= '' then
                        imageLabel.Image = assetUri
                        imageLabel.Visible = true
                        if typeof(fallbackObj) == 'Instance' then
                            fallbackObj.Visible = false
                        end
                        return true
                    end
                end
                return false
            end

            local function isImageExtPath(pathStr)
                local lower = pathStr:lower()
                if lower:find('_tmp%.') then
                    return false
                end
                return lower:match('%.png$') ~= nil or lower:match('%.jpe?g$') ~= nil or lower:match('%.webp$') ~= nil or lower:match('%.bmp$') ~= nil
            end

            function Creator.ListSavedBackgrounds()
                local results, seen = {}, {}
                if typeof(listfiles) ~= 'function' then
                    return results
                end
                local function addCandidate(rawPath, rootOnlyPrefix)
                    if typeof(rawPath) ~= 'string' or rawPath == '' then
                        return
                    end
                    local norm = rawPath:gsub('\\', '/'):gsub('^%./', '')
                    local fileName = norm:match('([^/]+)$') or norm
                    if rootOnlyPrefix and not fileName:lower():match('^rezhub_bg_') then
                        return
                    end
                    if isImageExtPath(norm) and not seen[norm:lower()] then
                        if typeof(isfile) ~= 'function' or isfile(norm) then
                            seen[norm:lower()] = true
                            results[#results + 1] = norm
                        end
                    end
                end
                if typeof(isfolder) == 'function' and isfolder('Rez/bg_cache') then
                    local ok, files = pcall(listfiles, 'Rez/bg_cache')
                    if ok and typeof(files) == 'table' then
                        for _, f in next, files do
                            addCandidate(f, false)
                        end
                    end
                end
                local okRoot, rootFiles = pcall(listfiles, '')
                if okRoot and typeof(rootFiles) == 'table' then
                    for _, f in next, rootFiles do
                        addCandidate(f, true)
                    end
                end
                table.sort(results, function(a, b)
                    return a:lower() < b:lower()
                end)
                return results
            end

            function Creator.FormatSavedBackgroundName(filePath)
                if typeof(filePath) ~= 'string' then
                    return ''
                end
                return (filePath:gsub('\\', '/'):match('([^/]+)$')) or filePath
            end

            function Creator.DeleteSavedBackground(filePath)
                if typeof(filePath) ~= 'string' or filePath == '' or typeof(delfile) ~= 'function' then
                    return false
                end
                local norm = filePath:gsub('\\', '/'):gsub('^%./', '')
                local lower = norm:lower()
                local allowed = lower:sub(1, 13) == 'rez/bg_cache/' or lower:match('^rezhub_bg_') ~= nil
                if not allowed or not isImageExtPath(norm) then
                    return false
                end
                if typeof(isfile) == 'function' and not isfile(norm) then
                    return false
                end
                local ok = pcall(delfile, norm)
                return ok == true and (typeof(isfile) ~= 'function' or not isfile(norm))
            end

            local function isUnsupportedMediaUrl(lowerName)
                if not lowerName then
                    return false
                end
                return lowerName:match('%.gifv?[%?#]?') ~= nil or lowerName:match('%.gifv?$') ~= nil
                    or lowerName:match('%.mp4[%?#]?') ~= nil or lowerName:match('%.mp4$') ~= nil
                    or lowerName:match('%.webm[%?#]?') ~= nil or lowerName:match('%.webm$') ~= nil
                    or lowerName:match('%.mov[%?#]?') ~= nil or lowerName:match('%.mov$') ~= nil
                    or lowerName:match('%.m4v[%?#]?') ~= nil or lowerName:match('%.m4v$') ~= nil
                    or lowerName:match('%.mkv[%?#]?') ~= nil or lowerName:match('%.mkv$') ~= nil
                    or lowerName:match('%.avi[%?#]?') ~= nil or lowerName:match('%.avi$') ~= nil
            end

            local function detectImageExtFromBytes(body, lowerName)
                if typeof(body) == 'string' and #body >= 8 then
                    local h6 = string.sub(body, 1, 6)
                    if h6 == 'GIF87a' or h6 == 'GIF89a' then
                        return nil
                    end
                    if string.sub(body, 5, 8) == 'ftyp' or string.sub(body, 1, 4) == '\26\69\223\163' or (string.sub(body, 1, 4) == 'RIFF' and string.sub(body, 9, 12) == 'AVI ') then
                        return nil
                    end
                    if string.sub(body, 1, 8) == '\137PNG\r\n\26\n' then
                        return 'png'
                    end
                    if string.sub(body, 1, 3) == '\255\216\255' then
                        return 'jpg'
                    end
                    if string.sub(body, 1, 4) == 'RIFF' and string.sub(body, 9, 12) == 'WEBP' then
                        return 'webp'
                    end
                    if string.sub(body, 1, 2) == 'BM' then
                        return 'bmp'
                    end
                    local headTrim = string.sub(body, 1, 64):lower()
                    if headTrim:match('^%s*<!doctype') or headTrim:match('^%s*<html') then
                        return nil
                    end
                end
                if isUnsupportedMediaUrl(lowerName) then
                    return nil
                end
                if lowerName then
                    return (lowerName:match('%.jpe?g') and 'jpg') or (lowerName:match('%.webp') and 'webp') or (lowerName:match('%.bmp') and 'bmp') or 'png'
                end
                return 'png'
            end

            function Creator.ResolveMediaAsset(rawInput, cachePrefix)
                local cleaned = trimStr(rawInput)
                if cleaned == '' then
                    return true, {kind = 'none', uri = ''}
                end
                if cleaned:lower():match('^video:') then
                    return false, Creator.Translate('SettingsBgInvalid')
                end
                if cleaned:match('^%d+$') then
                    return true, {kind = 'image', uri = 'rbxassetid://' .. cleaned}
                end
                if cleaned:match('^rbxassetid://') or cleaned:match('^rbxthumb://') or cleaned:match('^rbxasset://') then
                    return true, {kind = 'image', uri = cleaned}
                end
                local rbxId = cleaned:match('[?&]id=(%d+)') or cleaned:match('roblox%.com/library/(%d+)') or cleaned:match('create%.roblox%.com/store/asset/(%d+)')
                if rbxId then
                    return true, {kind = 'image', uri = 'rbxassetid://' .. rbxId}
                end
                local customAsset = getCustomAssetFn()
                if cleaned:match('^https?://') then
                    if typeof(customAsset) ~= 'function' or typeof(writefile) ~= 'function' then
                        return false, Creator.Translate('SettingsBgInvalid')
                    end
                    if isUnsupportedMediaUrl(cleaned:lower()) then
                        return false, Creator.Translate('SettingsBgInvalid')
                    end
                    local body = httpGetRaw(cleaned)
                    if not body then
                        return false, Creator.Translate('SettingsBgInvalid')
                    end
                    local ext = detectImageExtFromBytes(body, cleaned:lower())
                    if not ext then
                        return false, Creator.Translate('SettingsBgInvalid')
                    end
                    ensureFolderPath('Rez/bg_cache')
                    local fileName = `Rez/bg_cache/{cachePrefix or 'rezhub_bg'}_{hashString32(cleaned)}.{ext}`
                    local writeOk = pcall(writefile, fileName, body)
                    if not writeOk then
                        return false, Creator.Translate('SettingsBgInvalid')
                    end
                    local assetOk, assetUri = pcall(customAsset, fileName)
                    if assetOk and typeof(assetUri) == 'string' and assetUri ~= '' then
                        return true, {kind = 'image', uri = assetUri}
                    end
                    return false, Creator.Translate('SettingsBgInvalid')
                end
                if typeof(customAsset) == 'function' and typeof(isfile) == 'function' and isfile(cleaned) then
                    local rawBytes = typeof(readfile) == 'function' and select(2, pcall(readfile, cleaned)) or nil
                    local ext = detectImageExtFromBytes(typeof(rawBytes) == 'string' and rawBytes or nil, cleaned:lower())
                    if not ext then
                        return false, Creator.Translate('SettingsBgInvalid')
                    end
                    local assetOk, assetUri = pcall(customAsset, cleaned)
                    if assetOk and typeof(assetUri) == 'string' and assetUri ~= '' then
                        return true, {kind = 'image', uri = assetUri}
                    end
                end
                return false, Creator.Translate('SettingsBgInvalid')
            end

            function Creator.ResolveImageAsset(rawInput, cachePrefix)
                local ok, res = Creator.ResolveMediaAsset(rawInput, cachePrefix)
                if ok and typeof(res) == 'table' then
                    return true, res.uri or ''
                end
                return false, res
            end

            function Creator.EnsureEmbeddedAsset(filePath, b64)
                local customAsset = getCustomAssetFn()
                if typeof(customAsset) ~= 'function' or typeof(filePath) ~= 'string' or filePath == '' then
                    return nil
                end
                if typeof(isfile) == 'function' and isfile(filePath) then
                    local ok, uri = pcall(customAsset, filePath)
                    if ok and typeof(uri) == 'string' and uri ~= '' then
                        return uri
                    end
                end
                if typeof(writefile) == 'function' and typeof(b64) == 'string' and b64 ~= '' and not b64:match('^__REZ_') then
                    if typeof(isfolder) == 'function' and typeof(makefolder) == 'function' and not isfolder('Rez') then
                        pcall(makefolder, 'Rez')
                    end
                    local bytes = Creator.Base64Decode(b64)
                    if bytes ~= '' then
                        pcall(writefile, filePath, bytes)
                        local ok, uri = pcall(customAsset, filePath)
                        if ok and typeof(uri) == 'string' and uri ~= '' then
                            return uri
                        end
                    end
                end
                return nil
            end

            function Creator.EnsureDefaultLogoAsset()
                return Creator.EnsureEmbeddedAsset('Rez/rez_logo.png', Creator.DefaultLogoBase64)
            end

            function Creator.RefreshLocaleBindings()
                local lang = Creator.GetActiveLocale()
                for obj, props in next, Creator.Locale.Bindings do
                    for prop, keyOrFn in next, props do
                        local val = typeof(keyOrFn) == 'function' and keyOrFn(lang) or Creator.Translate(keyOrFn)
                        pcall(function()
                            obj[prop] = val
                        end)
                    end
                end
            end

            local function scheduleLocaleRefresh()
                if Creator.Locale.RefreshScheduled then
                    return
                end
                Creator.Locale.RefreshScheduled = true
                task.delay(0.12, function()
                    Creator.Locale.RefreshScheduled = false
                    Creator.RefreshLocaleBindings()
                end)
            end

            local function ensureRezFolder()
                if typeof(isfolder) == 'function' and typeof(makefolder) == 'function' and not isfolder('Rez') then
                    pcall(makefolder, 'Rez')
                end
            end

            function Creator.LoadSettings()
                if Creator.SettingsLoaded then
                    return Creator.Config
                end
                Creator.SettingsLoaded = true
                if typeof(isfile) == 'function' and typeof(readfile) == 'function' and isfile(Creator.SettingsPath) then
                    local ok, raw = pcall(readfile, Creator.SettingsPath)
                    if ok and typeof(raw) == 'string' and raw ~= '' then
                        local dok, parsed = pcall(HttpService.JSONDecode, HttpService, raw)
                        if dok and typeof(parsed) == 'table' then
                            for k, v in next, parsed do
                                Creator.Config[k] = v
                            end
                        end
                    end
                end
                if typeof(isfile) == 'function' and typeof(readfile) == 'function' and isfile(Creator.TranslateCachePath) then
                    local ok, raw = pcall(readfile, Creator.TranslateCachePath)
                    if ok and typeof(raw) == 'string' and raw ~= '' then
                        local dok, parsed = pcall(HttpService.JSONDecode, HttpService, raw)
                        if dok and typeof(parsed) == 'table' then
                            for langCode, dict in next, parsed do
                                if typeof(langCode) == 'string' and typeof(dict) == 'table' then
                                    Creator.Locale.AutoCache[langCode] = Creator.Locale.AutoCache[langCode] or {}
                                    for srcText, tgtText in next, dict do
                                        if typeof(srcText) == 'string' and typeof(tgtText) == 'string' and tgtText ~= '' then
                                            Creator.Locale.AutoCache[langCode][srcText] = tgtText
                                        end
                                    end
                                end
                            end
                        end
                    end
                end
                return Creator.Config
            end

            function Creator.SaveSettings(patch)
                if typeof(patch) == 'table' then
                    for k, v in next, patch do
                        Creator.Config[k] = v
                    end
                end
                if typeof(writefile) ~= 'function' or Creator.SettingsSaveScheduled then
                    return
                end
                Creator.SettingsSaveScheduled = true
                task.delay(0.15, function()
                    Creator.SettingsSaveScheduled = false
                    ensureRezFolder()
                    local ok, encoded = pcall(HttpService.JSONEncode, HttpService, Creator.Config)
                    if ok and typeof(encoded) == 'string' then
                        pcall(writefile, Creator.SettingsPath, encoded)
                    end
                end)
            end

            local function scheduleTranslateCacheSave()
                if typeof(writefile) ~= 'function' or Creator.CacheSaveScheduled then
                    return
                end
                Creator.CacheSaveScheduled = true
                task.delay(1.0, function()
                    Creator.CacheSaveScheduled = false
                    ensureRezFolder()
                    local ok, encoded = pcall(HttpService.JSONEncode, HttpService, Creator.Locale.AutoCache)
                    if ok and typeof(encoded) == 'string' then
                        pcall(writefile, Creator.TranslateCachePath, encoded)
                    end
                end)
            end

            local function shouldAutoTranslateText(text)
                if #text < 2 or #text > 500 then
                    return false
                end
                local lower = text:lower()
                if lower:match('^https?://') or lower:match('discord%.gg/') or lower:match('^rbx') or lower:match('^[%d%s%p]+$') then
                    return false
                end
                if text:match('<[^>]+>') or text:find('\n', 1, true) then
                    return false
                end
                if not text:match('[%a\128-\255]') then
                    return false
                end
                return true
            end

            local function splitLinesTrimmed(str)
                local list = {}
                local pos = 1
                while true do
                    local nl = string.find(str, '\n', pos, true)
                    if nl then
                        list[#list + 1] = trimStr(string.sub(str, pos, nl - 1))
                        pos = nl + 1
                    else
                        list[#list + 1] = trimStr(string.sub(str, pos))
                        break
                    end
                end
                return list
            end

            local function translateViaMyMemory(text, srcLang, targetLang)
                local url = 'https://api.mymemory.translated.net/get?q=' .. HttpService:UrlEncode(text) .. '&langpair=' .. srcLang .. '|' .. targetLang
                local body = httpGetRaw(url)
                if not body then
                    return nil
                end
                local ok, decoded = pcall(HttpService.JSONDecode, HttpService, body)
                if ok and typeof(decoded) == 'table' and tonumber(decoded.responseStatus) == 200 and typeof(decoded.responseData) == 'table' then
                    local out = decoded.responseData.translatedText
                    if typeof(out) == 'string' and out ~= '' and not out:upper():find('MYMEMORY WARNING') then
                        return trimStr(out)
                    end
                end
                return nil
            end

            local function translateViaGoogleFallback(text, targetLang)
                local url = 'https://translate.googleapis.com/translate_a/single?client=gtx&sl=vi&tl=' .. targetLang .. '&dt=t&q=' .. HttpService:UrlEncode(text)
                local body = httpGetRaw(url)
                if not body then
                    return nil
                end
                local ok, decoded = pcall(HttpService.JSONDecode, HttpService, body)
                if ok and typeof(decoded) == 'table' and typeof(decoded[1]) == 'table' then
                    local parts = {}
                    for _, seg in ipairs(decoded[1]) do
                        if typeof(seg) == 'table' and typeof(seg[1]) == 'string' then
                            parts[#parts + 1] = seg[1]
                        end
                    end
                    local joined = table.concat(parts)
                    if joined ~= '' then
                        return trimStr(joined)
                    end
                end
                return nil
            end

            local function translateBatchOrSingle(text, srcLang, targetLang)
                local res = translateViaGoogleFallback(text, targetLang)
                if not res then
                    res = translateViaMyMemory(text, srcLang, targetLang)
                end
                return res
            end

            local function pumpTranslateQueue()
                if Creator.Locale.FlushScheduled or #Creator.Locale.Queue == 0 or Creator.Locale.ActiveRequests > 0 then
                    return
                end
                Creator.Locale.FlushScheduled = true
                task.delay(0.08, function()
                    Creator.Locale.FlushScheduled = false
                    if #Creator.Locale.Queue == 0 then
                        return
                    end
                    Creator.Locale.ActiveRequests += 1
                    task.spawn(function()
                        while #Creator.Locale.Queue > 0 do
                            local first = table.remove(Creator.Locale.Queue, 1)
                            local batch = {first}
                            local totalLen = #first.text
                            for idx = #Creator.Locale.Queue, 1, -1 do
                                local candidate = Creator.Locale.Queue[idx]
                                if candidate.src == first.src and candidate.lang == first.lang and (totalLen + #candidate.text + 1) <= 320 and #batch < 10 then
                                    table.remove(Creator.Locale.Queue, idx)
                                    batch[#batch + 1] = candidate
                                    totalLen += #candidate.text + 1
                                end
                            end
                            local anyUpdated = false
                            if #batch > 1 then
                                local joined = {}
                                for i, item in ipairs(batch) do
                                    joined[i] = item.text
                                end
                                local combined = translateBatchOrSingle(table.concat(joined, '\n'), first.src, first.lang)
                                local lines = combined and splitLinesTrimmed(combined)
                                if lines and #lines == #batch then
                                    Creator.Locale.AutoCache[first.lang] = Creator.Locale.AutoCache[first.lang] or {}
                                    for i, item in ipairs(batch) do
                                        Creator.Locale.AutoCache[first.lang][item.text] = lines[i] ~= '' and lines[i] or item.text
                                        Creator.Locale.Pending[item.key] = nil
                                        if lines[i] ~= '' and lines[i] ~= item.text then
                                            anyUpdated = true
                                        end
                                    end
                                else
                                    for _, item in ipairs(batch) do
                                        local single = translateBatchOrSingle(item.text, item.src, item.lang)
                                        if single then
                                            Creator.Locale.AutoCache[item.lang] = Creator.Locale.AutoCache[item.lang] or {}
                                            Creator.Locale.AutoCache[item.lang][item.text] = single
                                            if single ~= item.text then
                                                anyUpdated = true
                                            end
                                        else
                                            Creator.Locale.Cooldown[item.key] = tick() + 30
                                        end
                                        Creator.Locale.Pending[item.key] = nil
                                        task.wait(0.15)
                                    end
                                end
                            else
                                local single = translateBatchOrSingle(first.text, first.src, first.lang)
                                if single then
                                    Creator.Locale.AutoCache[first.lang] = Creator.Locale.AutoCache[first.lang] or {}
                                    Creator.Locale.AutoCache[first.lang][first.text] = single
                                    if single ~= first.text then
                                        anyUpdated = true
                                    end
                                else
                                    Creator.Locale.Cooldown[first.key] = tick() + 30
                                end
                                Creator.Locale.Pending[first.key] = nil
                            end
                            if anyUpdated then
                                scheduleLocaleRefresh()
                                scheduleTranslateCacheSave()
                            end
                            if #Creator.Locale.Queue > 0 then
                                task.wait(0.18)
                            end
                        end
                        Creator.Locale.ActiveRequests -= 1
                    end)
                end)
            end

            function Creator.TranslateRaw(text)
                if typeof(text) ~= 'string' or text == '' then
                    return text
                end
                local lang = Creator.GetActiveLocale()
                local customTbl = Creator.Locale.Custom[lang]
                if customTbl and customTbl[text] ~= nil then
                    return customTbl[text]
                end
                -- Bản gốc dành cho người Việt: giữ nguyên chính xác những gì tác giả viết
                if lang == 'vi' then
                    return text
                end
                if not Creator.Locale.AutoTranslate then
                    return text
                end
                local normKey = trimStr(text):lower()
                local commonEntry = Creator.CommonLabels and Creator.CommonLabels[normKey]
