    [30] = function()
        waxGetEnv(30)
        return (function(...)
            local UserInputService = game:GetService'UserInputService'
            local Workspace = game:GetService'Workspace'

            local function getViewportSize()
                local cam = Workspace.CurrentCamera
                if cam and cam.ViewportSize and cam.ViewportSize.X > 0 and cam.ViewportSize.Y > 0 then
                    return cam.ViewportSize
                end
                return Vector2.new(1920, 1080)
            end

            local function checkIsMobile()
                local vp = getViewportSize()
                return (UserInputService.TouchEnabled and not UserInputService.KeyboardEnabled) or vp.Y < 520
            end

            local isMobile = checkIsMobile()

            local function resolveWindowSize(sizeVal, minSizeVal)
                local vp = getViewportSize()
                local minVec = typeof(minSizeVal) == 'Vector2' and minSizeVal or Vector2.new(isMobile and 320 or 470, isMobile and 240 or 380)
                local rawW, rawH
                if typeof(sizeVal) == 'UDim2' then
                    rawW = (sizeVal.X.Scale * vp.X) + sizeVal.X.Offset
                    rawH = (sizeVal.Y.Scale * vp.Y) + sizeVal.Y.Offset
                else
                    rawW = isMobile and math.clamp(vp.X * 0.78, 320, 620) or 470
                    rawH = isMobile and math.clamp(vp.Y * 0.88, 260, 420) or 380
                end
                if rawW <= 0 then
                    rawW = isMobile and math.clamp(vp.X * 0.78, 320, 620) or 470
                end
                if rawH <= 0 then
                    rawH = isMobile and math.clamp(vp.Y * 0.88, 260, 420) or 380
                end
                local maxMinW = math.max(260, vp.X - 16)
                local maxMinH = math.max(200, vp.Y - 16)
                local clampedMinW = math.min(minVec.X, maxMinW)
                local clampedMinH = math.min(minVec.Y, maxMinH)
                if isMobile then
                    clampedMinW = math.min(clampedMinW, math.max(260, math.floor(vp.X * 0.65)))
                    clampedMinH = math.min(clampedMinH, math.max(200, math.floor(vp.Y * 0.65)))
                end
                local finalW = math.clamp(math.floor(rawW + 0.5), clampedMinW, vp.X)
                local finalH = math.clamp(math.floor(rawH + 0.5), clampedMinH, vp.Y)
                return UDim2.fromOffset(finalW, finalH), Vector2.new(clampedMinW, clampedMinH)
            end

            return {
                IsMobile = isMobile,
                CheckIsMobile = checkIsMobile,
                GetViewportSize = getViewportSize,
                ResolveWindowSize = resolveWindowSize,
                Window = isMobile and {
                    SidebarInset = 6,
                    ContentInsetX = 10,
                    ContentInsetTop = 34,
                    ContentInsetBottom = 8,
                    OuterMargin = 6,
                    TopOffset = 38,
                    DefaultTabWidth = 98
                } or {
                    SidebarInset = 14,
                    ContentInsetX = 24,
                    ContentInsetTop = 70,
                    ContentInsetBottom = 18,
                    OuterMargin = 12,
                    TopOffset = 54,
                    DefaultTabWidth = 160
                },
                Page = isMobile and {
                    ItemGap = 3,
                    PaddingLeft = 2,
                    PaddingRight = 8,
                    PaddingTop = 2,
                    PaddingBottom = 4
                } or {
                    ItemGap = 5,
                    PaddingLeft = 2,
                    PaddingRight = 18,
                    PaddingTop = 2,
                    PaddingBottom = 2
                },
                Card = isMobile and {
                    Radius = 6,
                    LeftInset = 10,
                    TopInset = 6,
                    BottomInset = 6,
                    TrailingInset = 10,
                    ParticleInset = 2,
                    ControlGap = 8,
                    DefaultLabelRightReserve = 26,
                    ToggleLabelRightReserve = 50,
                    ControlLabelRightReserve = 122,
                    SwatchLabelRightReserve = 36,
                    TitleTextSize = 11,
                    DescTextSize = 10,
                    TitleHeight = 12,
                    DescHeight = 12,
                    ControlHeight = 24,
                    ControlTextSize = 11,
                    ControlMaxWidth = 112,
                    ControlMinWidth = 44,
                    ControlCornerRadius = 4,
                    IconSize = 14
                } or {
                    Radius = 8,
                    LeftInset = 16,
                    TopInset = 12,
                    BottomInset = 14,
                    TrailingInset = 16,
                    ParticleInset = 3,
                    ControlGap = 12,
                    DefaultLabelRightReserve = 42,
                    ToggleLabelRightReserve = 76,
                    ControlLabelRightReserve = 176,
                    SwatchLabelRightReserve = 56,
                    TitleTextSize = 13,
                    DescTextSize = 11,
                    TitleHeight = 14,
                    DescHeight = 14,
                    ControlHeight = 30,
                    ControlTextSize = 13,
                    ControlMaxWidth = 160,
                    ControlMinWidth = 48,
                    ControlCornerRadius = 5,
                    IconSize = 16
                },
                Dropdown = isMobile and {
                    ChevronInset = 8,
                    OptionHeight = 24,
                    SearchHeight = 26,
                    MaxMenuHeight = 220,
                    MinMenuWidth = 120
                } or {
                    ChevronInset = 12,
