            function GroupMotor:step(arg)
                if self._complete then
                    return true
                end
                local flag = true
                for _, value in pairs(self._motors) do
                    local val = value:step(arg)
                    if not val then
                        flag = false
                    end
                end
                self._onStep:fire(self:getValue())
                if flag then
                    if self._useImplicitConnections then
