    if className == 'LocalScript' or className == 'Script' then
        local ok, result = xpcallFn(moduleFn, function(err)
            return debug.traceback(err, 2)
        end)
        if not ok then
            errorFn(formatRuntimeErr(result), 0)
        end
    else
        local results = {
            xpcallFn(moduleFn, function(err)
                return debug.traceback(err, 2)
            end)
        }
        local ok = tableRemove(results, 1)
        if not ok then
            local ok = tableRemove(results, 1)
            errorFn(formatRuntimeErr(ok), 0)
        end
        loadedModules[targetScript] = results
        return unpackFn(results)
    end
end

function waxGetEnv(moduleId)
    local moduleInst = instanceById[moduleId]

    local function pcallWithTraceback(targetFn, ...)
        local results = {
            xpcallFn(targetFn, function(err)
                return debug.traceback(err, 2)
            end, ...)
        }
        local ok = tableRemove(results, 1)
        if not ok then
            errorFn(results[1], 3)
        end
        return unpackFn(results)
    end
    local envSharedProxy = tableFreeze(setmetatableFn({}, {
        __index = sharedEnv,
        __newindex = function(tbl, key, val)
            sharedEnv[key] = val
        end,
        __len = function()
            return #sharedEnv
        end,
        __iter = function()
            return nextFn, sharedEnv
        end
    }))
    local envTable, currentScript = tableFreeze {
        version = waxVersion,
        envname = waxEnvName,
        shared = envSharedProxy,
        script = rootScript,
        require = realRequire
    }, moduleInst

    local function customRequire(targetModule, ...)
        local valueType, errNonModule, errSelfRequire = typeFn(targetModule), 'Attempted to call require with a non-ModuleScript', 'Attempted to call require with self'
        if valueType == 'table' and childrenMap[targetModule] then
            if targetModule.ClassName ~= 'ModuleScript' then
                errorFn(errNonModule, 2)
            elseif targetModule == moduleInst then
                errorFn(errSelfRequire, 2)
            end
            return executeScript(targetModule)
        elseif valueType == 'string' and stringSub(targetModule, 1, 1) ~= '@' then
            if #targetModule == 0 then
                errorFn('Attempted to call require with empty string', 2)
            end
            local searchInst = moduleInst
            if stringSub(targetModule, 1, 1) == '/' then
                searchInst = virtualRoot
            elseif stringSub(targetModule, 1, 2) == './' then
                targetModule = stringSub(targetModule, 3)
            end
            local pathStr
            for key in stringGmatch(targetModule, '([^/]*)/?') do
                local segmentName = key
                if key == '..' then
                    segmentName = 'Parent'
                end
                if segmentName ~= '' then
                    local foundChild = searchInst:FindFirstChild(segmentName)
                    if not foundChild then
                        local parentObj = searchInst.Parent
                        if parentObj then
                            foundChild = parentObj:FindFirstChild(segmentName)
                        end
                    end
                    if foundChild then
                        searchInst = foundChild
                    elseif key ~= pathStr and key ~= 'init' and key ~= 'init.server' and key ~= 'init.client' then
                        errorFn('Virtual script path "' .. targetModule .. '" not found', 2)
                    end
                end
                pathStr = key
            end
            if searchInst.ClassName ~= 'ModuleScript' then
                errorFn(errNonModule, 2)
            elseif searchInst == moduleInst then
                errorFn(errSelfRequire, 2)
            end
            return executeScript(searchInst)
        end
        return pcallWithTraceback(realRequire, targetModule, ...)
    end
    return envTable, currentScript, customRequire
end
for _, value in nextFn, startupScripts do
    spawnFn(executeScript, value)
end
return executeScript(virtualRoot:GetChildren()[1])
